/**
 * d3-data.js — data utilities for chart-ready row arrays.
 *
 * Pure functions over arrays of plain objects ("rows"): grouped aggregation,
 * wide<->long pivots, numeric binning, top-N with an "Other" bucket, date
 * coercion, computed columns, and time-series regraining. No chart
 * coupling — every function returns NEW rows (inputs are never mutated) so
 * results feed straight into any builder's `data`/`series` config.
 *
 * Design rules (matching the library's string-accessor style):
 *   - Field arguments are STRINGS (`data.topN(rows, 'budget', 5)`), so specs
 *     stay serializable. Functions are accepted only where a reduction or a
 *     computed column genuinely needs code (custom `agg` reducers, `derive`).
 *   - Aggregations get string shorthands: 'sum' | 'mean' | 'median' | 'min' |
 *     'max' | 'count'.
 *   - Nulls never silently become 0. The `nulls` policy ('drop' | 'keep' |
 *     'zero') is explicit on rollup/bin/pivotLonger; pivotWider uses `fill`
 *     (default null) for missing combinations.
 *   - Deterministic output ordering: group/bin/pivot rows sort ascending by
 *     their key(s); pivot columns keep first-appearance order.
 *
 * Exposed as `ChartFactory.data` and the named `data` export.
 */

import * as d3 from 'd3';

// ============================================
// Internals
// ============================================

const isNil = v => v === null || v === undefined ||
    (typeof v === 'number' && Number.isNaN(v));

function assertRows(rows, fn) {
    if (!Array.isArray(rows)) {
        throw new TypeError(`data.${fn}: rows must be an array (got ${typeof rows})`);
    }
}

function assertField(field, fn, what = 'field') {
    if (typeof field !== 'string' || field === '') {
        throw new TypeError(`data.${fn}: ${what} must be a non-empty field-name string`);
    }
}

/** Ascending compare that keeps numbers numeric, Dates chronological, and
 *  mixed/string values in d3.ascending order. Nullish sorts last. */
function keyCompare(a, b) {
    if (isNil(a)) return isNil(b) ? 0 : 1;
    if (isNil(b)) return -1;
    return d3.ascending(a, b) ?? 0;
}

const NULL_POLICIES = ['drop', 'keep', 'zero'];

function assertNulls(nulls, fn, allowed = NULL_POLICIES) {
    if (!allowed.includes(nulls)) {
        throw new TypeError(`data.${fn}: nulls must be one of ${allowed.map(p => `'${p}'`).join(' | ')} (got '${nulls}')`);
    }
}

const AGG_NAMES = ['sum', 'mean', 'median', 'min', 'max', 'count'];
const AGG_FNS = {
    sum: d3.sum,
    mean: d3.mean,
    median: d3.median,
    min: d3.min,
    max: d3.max
};

/**
 * Normalize one agg spec entry into a reducer over group rows.
 * Accepted spellings:
 *   'count'                      -> group size
 *   [field, 'sum'|'mean'|...]    -> named aggregation of a field
 *   [field, 'count']             -> count of non-null values of the field
 *   (groupRows) => value         -> custom reducer
 * `nulls` governs null/undefined/NaN field values:
 *   'drop' (default)  excluded from the aggregation (d3 semantics)
 *   'keep'            any null present -> result is null
 *   'zero'            nulls counted as 0
 */
function makeReducer(outField, spec, nulls, fn) {
    if (typeof spec === 'function') return spec;
    if (spec === 'count') return rows => rows.length;
    if (Array.isArray(spec) && spec.length === 2 &&
        typeof spec[0] === 'string' && typeof spec[1] === 'string') {
        const [field, name] = spec;
        if (!AGG_NAMES.includes(name)) {
            throw new TypeError(`data.${fn}: unknown aggregation '${name}' for '${outField}' — use ${AGG_NAMES.map(n => `'${n}'`).join(' | ')} or a function`);
        }
        return rows => {
            let values = rows.map(r => r[field]);
            if (name === 'count') {
                return nulls === 'keep' ? values.length : values.filter(v => !isNil(v)).length;
            }
            if (nulls === 'keep' && values.some(isNil)) return null;
            if (nulls === 'zero') values = values.map(v => (isNil(v) ? 0 : v));
            else values = values.filter(v => !isNil(v));
            if (values.length === 0) return null;
            return AGG_FNS[name](values);
        };
    }
    throw new TypeError(`data.${fn}: invalid agg spec for '${outField}' — use 'count', ['field', 'sum'|'mean'|'median'|'min'|'max'|'count'], or a function`);
}

function makeReducers(agg, nulls, fn) {
    const spec = agg && Object.keys(agg).length ? agg : { count: 'count' };
    return Object.entries(spec).map(([outField, entry]) => [outField, makeReducer(outField, entry, nulls, fn)]);
}

// ============================================
// rollup
// ============================================

/**
 * Grouped aggregation: one output row per distinct combination of `by` keys,
 * with the group keys as fields plus one field per `agg` entry.
 *
 *   data.rollup(rows, {
 *       by: 'decade',                        // or ['chamber', 'congress']
 *       agg: {
 *           avgBirths: ['births', 'mean'],   // [field, 'sum'|'mean'|'median'|'min'|'max'|'count']
 *           n: 'count',                      // group size
 *           spread: rows => d3.max(rows, r => r.v) - d3.min(rows, r => r.v)
 *       },
 *       nulls: 'drop'                        // 'drop' (default) | 'keep' | 'zero'
 *   })
 *
 * Computed group keys: add them first with data.derive(). Output rows are
 * sorted ascending by the `by` key(s). Omitting `agg` yields `{...keys, count}`.
 */
function rollup(rows, { by, agg, nulls = 'drop' } = {}) {
    assertRows(rows, 'rollup');
    assertNulls(nulls, 'rollup');
    const byFields = Array.isArray(by) ? by : [by];
    if (byFields.length === 0) throw new TypeError('data.rollup: by must name at least one field');
    byFields.forEach(f => assertField(f, 'rollup', 'by'));
    const reducers = makeReducers(agg, nulls, 'rollup');

    const flat = d3.flatRollup(rows, groupRows => groupRows, ...byFields.map(f => r => r[f]));
    const out = flat.map(entry => {
        const groupRows = entry[entry.length - 1];
        const row = {};
        byFields.forEach((f, i) => { row[f] = entry[i]; });
        for (const [outField, reduce] of reducers) row[outField] = reduce(groupRows);
        return row;
    });
    out.sort((a, b) => {
        for (const f of byFields) {
            const c = keyCompare(a[f], b[f]);
            if (c !== 0) return c;
        }
        return 0;
    });
    return out;
}

// ============================================
// pivotWider / pivotLonger
// ============================================

/**
 * Long -> wide: spread `names` values into columns.
 *
 *   data.pivotWider(rows, { index: 'year', names: 'category', values: 'value', fill: 0 })
 *   // [{year, catA: v, catB: v, ...}, ...] — one row per index value
 *
 * `index` may be a string or array of strings. Missing (index, name)
 * combinations get `fill` (default null — pass fill: 0 explicitly for count
 * data; nulls never silently become 0). Column order is first-appearance
 * order of `names` values; rows sort ascending by `index`. Duplicate
 * (index, name) pairs keep the LAST value and log a console.warn (aggregate
 * with data.rollup first).
 */
function pivotWider(rows, { index, names, values, fill = null } = {}) {
    assertRows(rows, 'pivotWider');
    const indexFields = Array.isArray(index) ? index : [index];
    if (indexFields.length === 0) throw new TypeError('data.pivotWider: index must name at least one field');
    indexFields.forEach(f => assertField(f, 'pivotWider', 'index'));
    assertField(names, 'pivotWider', 'names');
    assertField(values, 'pivotWider', 'values');

    const JOIN = '�';
    const groups = new Map();      // composite index -> { keys: [], cells: Map(name -> value) }
    const nameOrder = [];          // first-appearance column order
    const seenNames = new Set();
    let dupes = 0;

    for (const r of rows) {
        const keys = indexFields.map(f => r[f]);
        const composite = keys.map(k => (isNil(k) ? 'null' : String(k)) ).join(JOIN);
        let g = groups.get(composite);
        if (!g) { g = { keys, cells: new Map() }; groups.set(composite, g); }
        const name = r[names];
        if (!seenNames.has(name)) { seenNames.add(name); nameOrder.push(name); }
        if (g.cells.has(name)) dupes++;
        g.cells.set(name, r[values]);
    }
    if (dupes > 0) {
        console.warn(`data.pivotWider: ${dupes} duplicate (index, names) pair${dupes === 1 ? '' : 's'} — kept the last value each time. Aggregate with data.rollup first.`);
    }

    const out = [...groups.values()].map(g => {
        const row = {};
        indexFields.forEach((f, i) => { row[f] = g.keys[i]; });
        for (const name of nameOrder) {
            row[name] = g.cells.has(name) ? g.cells.get(name) : fill;
        }
        return row;
    });
    out.sort((a, b) => {
        for (const f of indexFields) {
            const c = keyCompare(a[f], b[f]);
            if (c !== 0) return c;
        }
        return 0;
    });
    return out;
}

/**
 * Wide -> long: melt `cols` into (name, value) pairs.
 *
 *   data.pivotLonger(rows, { cols: ['catA', 'catB'], names: 'series', values: 'value' })
 *   // [{...otherFields, series: 'catA', value: v}, ...] — one row per input row per col
 *
 * Non-melted fields are carried through on every emitted row. `nulls`
 * governs null/undefined/NaN cell values: 'keep' (default — preserves gaps),
 * 'drop' (skip those cells), 'zero'. Output preserves input row order, cols
 * in the order given.
 */
function pivotLonger(rows, { cols, names = 'name', values = 'value', nulls = 'keep' } = {}) {
    assertRows(rows, 'pivotLonger');
    assertNulls(nulls, 'pivotLonger');
    if (!Array.isArray(cols) || cols.length === 0) {
        throw new TypeError('data.pivotLonger: cols must be a non-empty array of field names');
    }
    cols.forEach(c => assertField(c, 'pivotLonger', 'cols entry'));
    assertField(names, 'pivotLonger', 'names');
    assertField(values, 'pivotLonger', 'values');

    const colSet = new Set(cols);
    const out = [];
    for (const r of rows) {
        const rest = {};
        for (const k of Object.keys(r)) if (!colSet.has(k)) rest[k] = r[k];
        for (const col of cols) {
            let v = r[col];
            if (isNil(v)) {
                if (nulls === 'drop') continue;
                v = nulls === 'zero' ? 0 : null;
            }
            out.push({ ...rest, [names]: col, [values]: v });
        }
    }
    return out;
}

// ============================================
// topN
// ============================================

/**
 * Keep the top `n` rows by a numeric field, optionally collapsing the rest
 * into a single "Other" row.
 *
 *   data.topN(rows, 'budget', 5)                                  // top 5, descending
 *   data.topN(rows, 'gross', 5, { direction: 'asc' })             // bottom 5
 *   data.topN(rows, 'sales', 6, { by: 'region', other: 'Other' }) // + Other row
 *
 * With `other`, `by` names the label field that receives the `other` string;
 * the Other row aggregates the remainder's `key` with `agg` ('sum' default,
 * any agg shorthand or a function over the remainder rows) and carries only
 * those two fields. If n >= distinct rows there is no Other row. Rows whose
 * `key` is null/NaN sort last (and fold into Other when present). Output is
 * sorted by `key` in `direction` order, Other last. A summed Other row
 * (the default agg) carries the folded rows under `row[data.MEMBERS]`, which
 * the Bar and Donut tooltips list (`otherBreakdown`).
 */
function topN(rows, key, n, { other, by, agg = 'sum', direction = 'desc' } = {}) {
    assertRows(rows, 'topN');
    assertField(key, 'topN', 'key');
    if (!Number.isFinite(n) || n < 0) throw new TypeError(`data.topN: n must be a non-negative number (got ${n})`);
    if (direction !== 'asc' && direction !== 'desc') {
        throw new TypeError(`data.topN: direction must be 'asc' | 'desc' (got '${direction}')`);
    }
    const sorted = [...rows].sort((a, b) => {
        const av = a[key], bv = b[key];
        if (isNil(av)) return isNil(bv) ? 0 : 1;         // nulls last either way
        if (isNil(bv)) return -1;
        return direction === 'desc' ? d3.descending(av, bv) ?? 0 : d3.ascending(av, bv) ?? 0;
    });
    const kept = sorted.slice(0, n).map(r => ({ ...r }));
    const rest = sorted.slice(n);
    if (other === undefined || rest.length === 0) return kept;
    assertField(by, 'topN', "by (required with 'other')");
    const reduce = makeReducer(other, typeof agg === 'function' ? agg : [key, agg], 'drop', 'topN');
    const otherRow = { [by]: other, [key]: reduce(rest) };
    // A summed Other row remembers what it folded (copies, biggest first),
    // so a chart can list them in its tooltip. Symbol-keyed: invisible to
    // Object.keys / JSON / pivots, but it survives a row spread.
    if (agg === 'sum') otherRow[MEMBERS] = rest.map(r => ({ ...r }));
    kept.push(otherRow);
    return kept;
}

/**
 * The symbol under which data.topN's summed Other row carries the rows it
 * folded (`row[data.MEMBERS]`). Symbol.for, so every bundle shares it.
 */
const MEMBERS = Symbol.for('chart-factory.members');

// ============================================
// bin
// ============================================

/**
 * Numeric binning: histogram rows with `x0`/`x1`/`count` plus optional
 * rollup-style aggregations of each bin's rows.
 *
 *   data.bin(rows, 'year', { step: 5 })                       // bins aligned to multiples of 5
 *   data.bin(rows, 'score', { thresholds: 20 })               // ~20 d3-nice bins
 *   data.bin(rows, 'age', { extent: [20, 100], step: 10,
 *                           agg: { avg: ['salary', 'mean'] } })
 *
 * `step` produces uniform bins aligned to multiples of step (covering the
 * data or the given `extent`); `thresholds` (count hint or explicit array)
 * is passed to d3.bin. Empty in-range bins are kept (count 0, agg fields
 * null). `nulls` governs rows whose key is null/NaN: 'drop' (default) or
 * 'zero' (count as key 0); 'keep' is not meaningful for binning and throws.
 * Output is sorted by `x0`.
 */
function bin(rows, key, { step, thresholds, extent, agg, nulls = 'drop' } = {}) {
    assertRows(rows, 'bin');
    assertField(key, 'bin', 'key');
    assertNulls(nulls, 'bin', ['drop', 'zero']);
    if (step !== undefined && (!Number.isFinite(step) || step <= 0)) {
        throw new TypeError(`data.bin: step must be a positive number (got ${step})`);
    }

    const usable = nulls === 'zero'
        ? rows.map(r => (isNil(r[key]) ? { ...r, [key]: 0 } : r))
        : rows.filter(r => !isNil(r[key]));
    if (usable.length === 0) return [];

    const binner = d3.bin().value(r => r[key]);
    if (step !== undefined) {
        const [lo, hi] = extent || d3.extent(usable, r => r[key]);
        const start = Math.floor(lo / step) * step;
        // Floor semantics: a data value sitting exactly on the highest aligned
        // edge starts a new bin (d3.bin would otherwise fold it into the last
        // bin, which it closes at the domain max).
        let stop = Math.max(Math.ceil(hi / step) * step, start + step);
        if (d3.max(usable, r => r[key]) >= stop) stop += step;
        binner.domain([start, stop])
            .thresholds(d3.range(start + step, stop, step));
    } else {
        if (extent) binner.domain(extent);
        if (thresholds !== undefined) binner.thresholds(thresholds);
    }

    const reducers = agg ? makeReducers(agg, nulls === 'zero' ? 'zero' : 'drop', 'bin') : [];
    const out = binner(usable).map(b => {
        const row = { x0: b.x0, x1: b.x1, count: b.length };
        for (const [outField, reduce] of reducers) {
            row[outField] = b.length === 0 ? null : reduce(Array.from(b));
        }
        return row;
    });
    out.sort((a, b) => keyCompare(a.x0, b.x0));
    return out;
}

// ============================================
// toDate
// ============================================

/**
 * Coerce string date fields to Date objects (copies — inputs untouched).
 *
 *   data.toDate(rows, 'date')                                // ISO strings / epoch ms
 *   data.toDate(rows, ['start', 'end'], { format: '%m/%d/%y' })  // d3.timeParse format
 *   data.toDate(rows, 'date', { nulls: 'drop' })             // drop unparseable rows
 *
 * Existing Date values pass through; strings parse via the d3.timeParse
 * `format` when given, else ISO/`new Date` (the library's own time-axis
 * coercion); finite numbers are treated as epoch milliseconds. Anything
 * unparseable becomes null — never a silent epoch date. `nulls`: 'keep'
 * (default — invalid values become null, rows kept) or 'drop' (drop any row
 * where a coerced field is null).
 */
function toDate(rows, fields, { format, nulls = 'keep' } = {}) {
    assertRows(rows, 'toDate');
    assertNulls(nulls, 'toDate', ['keep', 'drop']);
    const fieldList = Array.isArray(fields) ? fields : [fields];
    if (fieldList.length === 0) throw new TypeError('data.toDate: fields must name at least one field');
    fieldList.forEach(f => assertField(f, 'toDate', 'fields'));
    const parse = format ? d3.timeParse(format) : null;

    const coerce = v => {
        if (isNil(v)) return null;
        if (v instanceof Date) return Number.isNaN(+v) ? null : v;
        let date = null;
        if (typeof v === 'string') {
            date = parse ? parse(v) : (d3.isoParse(v) || new Date(v));
        } else if (typeof v === 'number' && Number.isFinite(v)) {
            date = new Date(v);
        }
        return date && !Number.isNaN(+date) ? date : null;
    };

    const out = [];
    for (const r of rows) {
        const copy = { ...r };
        let anyNull = false;
        for (const f of fieldList) {
            copy[f] = coerce(r[f]);
            if (copy[f] === null) anyNull = true;
        }
        if (nulls === 'drop' && anyNull) continue;
        out.push(copy);
    }
    return out;
}

// ============================================
// derive
// ============================================

/**
 * Computed columns: add/overwrite fields via functions of the row.
 *
 *   data.derive(rows, {
 *       era: r => Math.floor(r.year / 5) * 5,
 *       share: r => r.part / r.total
 *   })
 *
 * Returns copies with each spec field set to fn(row, index) — the one place
 * functions are required, because computed columns need code. Specs evaluate
 * against the ORIGINAL row (order-independent). Typical use: derive a
 * computed group key, then data.rollup by it.
 */
function derive(rows, spec) {
    assertRows(rows, 'derive');
    if (!spec || typeof spec !== 'object' || Object.keys(spec).length === 0) {
        throw new TypeError('data.derive: spec must be an object of { field: fn }');
    }
    const entries = Object.entries(spec);
    for (const [field, fn] of entries) {
        if (typeof fn !== 'function') {
            throw new TypeError(`data.derive: '${field}' must be a function (got ${typeof fn})`);
        }
    }
    return rows.map((r, i) => {
        const copy = { ...r };
        for (const [field, fn] of entries) copy[field] = fn(r, i);
        return copy;
    });
}

// ============================================
// regrain
// ============================================

const REGRAIN_GRAINS = ['day', 'week', 'month', 'quarter', 'year'];
const REGRAIN_HOW = ['sum', 'mean', 'additive', 'level', 'ratio'];

/** A time cell as UTC ms: Dates, ISO strings ('2024-07', '2024-07-15', timestamps), epoch ms. Else null. */
function timeMs(v) {
    if (isNil(v)) return null;
    if (v instanceof Date) return Number.isNaN(+v) ? null : +v;
    if (typeof v === 'number') return Number.isFinite(v) ? v : null;
    if (typeof v === 'string' && v.trim()) {
        const s = v.trim();
        const d = d3.isoParse(s) || new Date(s);
        return d && !Number.isNaN(+d) ? +d : null;
    }
    return null;
}

/** The UTC start of the `grain` bucket holding `ms` (weeks start on Monday). */
function bucketStart(ms, grain) {
    const d = new Date(ms);
    const y = d.getUTCFullYear(), mo = d.getUTCMonth(), day = d.getUTCDate();
    if (grain === 'year') return Date.UTC(y, 0, 1);
    if (grain === 'quarter') return Date.UTC(y, Math.floor(mo / 3) * 3, 1);
    if (grain === 'month') return Date.UTC(y, mo, 1);
    if (grain === 'week') return Date.UTC(y, mo, day - ((d.getUTCDay() + 6) % 7));
    return Date.UTC(y, mo, day);
}

/** A measure cell as a number: numbers, and plain numeric strings ('1240', '1,240'). Anything else is missing. */
function measureValue(v) {
    if (typeof v === 'number') return Number.isFinite(v) ? v : null;
    if (typeof v === 'string' && v.trim()) {
        const n = Number(v.trim().replace(/,/g, ''));
        return Number.isFinite(n) ? n : null;
    }
    return null;
}

/**
 * Roll a time series up to a coarser grain: one output row per
 * (time bucket, combination of the other columns).
 *
 *   data.regrain(rows, { time: 'date', grain: 'month' })
 *   data.regrain(rows, {
 *       time: 'date', grain: 'quarter',
 *       measures: ['revenue', 'orders', 'aov', 'price'],
 *       how: {
 *           revenue: 'sum',                          // additive: summed (the default)
 *           price: 'mean',                           // a level: averaged
 *           aov: { num: 'revenue', den: 'orders' },  // a ratio: sum(num) / sum(den) [* scale]
 *       },
 *   })
 *
 * `grain`: 'day' | 'week' (Monday start) | 'month' | 'quarter' | 'year',
 * bucketed in UTC. `measures` defaults to every field (other than `time`)
 * whose present values are all numbers; every OTHER field is a grouping key,
 * kept as is. `how` per measure: 'sum' / 'additive' (the default),
 * 'mean' / 'level', or a ratio's parts `{ num, den, scale? }` — rebuilt as
 * scale * sum(num) / sum(den) over the bucket's rows, never a sum or mean of
 * the ratio itself. A ratio with no parts ('ratio') is AVERAGED per bucket,
 * which is right only when every row weighs the same — name its parts when
 * the rows have them (`suggest().affordances.measures[].parts`).
 *
 * The time value of an output row is its bucket's start, written like the
 * input: a Date stays a Date, a string becomes 'YYYY-MM-DD', epoch ms stay
 * ms. Missing values are skipped (never 0); a bucket with no value for a
 * measure gets null. Rows whose time does not parse are dropped. It NEVER
 * generates data: every bucket comes from input rows (no empty buckets
 * filled, no span extended). Output sorts by time, then the key fields.
 */
function regrain(rows, { time, grain, measures, how = {} } = {}) {
    assertRows(rows, 'regrain');
    assertField(time, 'regrain', 'time');
    if (!REGRAIN_GRAINS.includes(grain)) {
        throw new TypeError(`data.regrain: grain must be one of ${REGRAIN_GRAINS.map(g => `'${g}'`).join(' | ')} (got '${grain}')`);
    }
    const fieldSet = new Set();
    for (const r of rows) for (const k of Object.keys(r || {})) fieldSet.add(k);
    fieldSet.delete(time);
    let measureList;
    if (measures === undefined) {
        measureList = [...fieldSet].filter(f => {
            let seen = false;
            for (const r of rows) {
                const v = r[f];
                if (isNil(v)) continue;
                if (typeof v !== 'number') return false;
                seen = true;
            }
            return seen;
        });
    } else {
        if (!Array.isArray(measures)) throw new TypeError('data.regrain: measures must be an array of field names');
        measures.forEach(m => assertField(m, 'regrain', 'measures entry'));
        measureList = measures.filter(m => m !== time);
    }
    const plans = measureList.map(m => {
        const h = how[m] === undefined ? 'sum' : how[m];
        if (h && typeof h === 'object') {
            assertField(h.num, 'regrain', `how.${m}.num`);
            assertField(h.den, 'regrain', `how.${m}.den`);
            return { m, kind: 'ratio', num: h.num, den: h.den, scale: Number.isFinite(h.scale) ? h.scale : 1 };
        }
        if (!REGRAIN_HOW.includes(h)) {
            throw new TypeError(`data.regrain: how.${m} must be 'sum' | 'mean' | 'additive' | 'level' | 'ratio' | { num, den, scale? } (got '${h}')`);
        }
        return { m, kind: h === 'sum' || h === 'additive' ? 'sum' : 'mean' };
    });
    const measureSet = new Set(measureList);
    const keys = [...fieldSet].filter(f => !measureSet.has(f));

    const groups = new Map();
    for (const r of rows) {
        const raw = r[time];
        const ms = timeMs(raw);
        if (ms === null) continue;
        const b = bucketStart(ms, grain);
        const kv = keys.map(k => r[k]);
        const id = JSON.stringify([b, ...kv.map(v => (v instanceof Date ? +v : v === undefined ? null : v))]);
        let g = groups.get(id);
        if (!g) {
            g = { b, kv, like: raw, acc: plans.map(() => ({ sum: 0, n: 0, num: 0, den: 0 })) };
            groups.set(id, g);
        }
        plans.forEach((p, i) => {
            const a = g.acc[i];
            if (p.kind === 'ratio') {
                const nv = measureValue(r[p.num]), dv = measureValue(r[p.den]);
                if (nv !== null && dv !== null) { a.num += nv; a.den += dv; a.n++; }
            } else {
                const v = measureValue(r[p.m]);
                if (v !== null) { a.sum += v; a.n++; }
            }
        });
    }
    const writeTime = (b, like) => (like instanceof Date ? new Date(b)
        : typeof like === 'number' ? b : new Date(b).toISOString().slice(0, 10));
    const built = [...groups.values()].map(g => {
        const row = { [time]: writeTime(g.b, g.like) };
        keys.forEach((k, i) => { if (g.kv[i] !== undefined) row[k] = g.kv[i]; });
        plans.forEach((p, i) => {
            const a = g.acc[i];
            if (!a.n) row[p.m] = null;
            else if (p.kind === 'ratio') row[p.m] = a.den ? (p.scale * a.num) / a.den : null;
            else row[p.m] = p.kind === 'mean' ? a.sum / a.n : a.sum;
        });
        return { b: g.b, row };
    });
    built.sort((x, y) => {
        if (x.b !== y.b) return x.b - y.b;
        for (const k of keys) {
            const c = keyCompare(x.row[k], y.row[k]);
            if (c !== 0) return c;
        }
        return 0;
    });
    return built.map(x => x.row);
}

