import React, { useEffect, useMemo, useState } from 'react';
import { Game, Pick, TeamPick, User, WeatherData } from '../types';
import { getTeamLogo, getMascotName } from '../teamAssets';

interface PicksScreenProps {
  games: Game[];
  users: User[];
  selectedUser: string;
  currentWeek: number;
  currentPicks: TeamPick[];
  weatherData: WeatherData[];
  picks: Pick[];
  teamAbbreviations?: { [key: string]: string };
  onSavePicks: (picks: TeamPick[]) => Promise<boolean | undefined> | void;
  onSelectUser: (userId: string) => void;
  claimedUserIds: string[] | null;
}

const isGameLocked = (game: Game) => new Date(game.kickoff_et).getTime() <= Date.now();

const fmtSpread = (spread: number) => (spread > 0 ? `+${spread}` : `${spread}`);

const kickoffShort = (kickoffEt: string) =>
  new Date(kickoffEt).toLocaleDateString('en-US', {
    weekday: 'short',
    hour: 'numeric',
    minute: '2-digit',
  });

const slotLabel = (kickoffEt: string) => {
  const date = new Date(kickoffEt);
  const day = date.toLocaleDateString('en-US', { weekday: 'long' });
  const hour = date.getHours();
  if (day === 'Sunday') return hour < 15 ? 'Sunday early' : hour < 19 ? 'Sunday late' : 'Sunday night';
  return `${day}${hour >= 19 ? ' night' : ''}`;
};

// Compact weather chip from the forecast summary (home team keyed)
const weatherChip = (summary: string | undefined): string => {
  if (!summary || summary.startsWith('Forecast not yet')) return '';
  const parts: string[] = [];
  const temp = summary.match(/(\d+)°F/);
  if (temp) {
    const degrees = parseInt(temp[1], 10);
    parts.push(`${degrees < 32 ? '🥶 ' : degrees > 84 ? '☀️ ' : ''}${degrees}°`);
  }
  const rain = summary.match(/(\d+)% chance rain/);
  if (rain) parts.push(`🌧 ${rain[1]}%`);
  if (/snow/i.test(summary)) parts.push('❄️');
  const wind = summary.match(/Windy \((\d+)mph/);
  if (wind) parts.push(`💨 ${wind[1]}`);
  return parts.join(' · ');
};

// Name picker for visitors who aren't signed in. Claimed names are hidden —
// those players sign in instead (null = members list still loading).
export function WhoAreYouCard({
  users,
  claimedUserIds,
  onSelect,
}: {
  users: User[];
  claimedUserIds: string[] | null;
  onSelect: (userId: string) => void;
}) {
  const available =
    claimedUserIds === null ? null : users.filter((user) => !claimedUserIds.includes(user.id));
  return (
    <div className="sl-card" style={{ padding: '12px 16px', marginTop: 14 }}>
      <div style={{ fontWeight: 650, marginBottom: 8 }}>Who are you?</div>
      {available === null ? (
        <div style={{ color: 'var(--ink-soft)', fontSize: '0.85rem' }}>Loading names…</div>
      ) : available.length === 0 ? (
        <div style={{ color: 'var(--ink-soft)', fontSize: '0.85rem' }}>
          Every name is claimed — use <b>Sign in</b> (top right) to make picks.
        </div>
      ) : (
        <>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            {available.map((user) => (
              <button
                key={user.id}
                onClick={() => onSelect(user.id)}
                className="sl-ctx"
                style={{ fontSize: '0.85rem' }}
              >
                {user.name}
              </button>
            ))}
          </div>
          <div style={{ color: 'var(--ink-soft)', fontSize: '0.78rem', marginTop: 8 }}>
            Don't see your name? It's already claimed — use <b>Sign in</b> (top right) instead.
          </div>
        </>
      )}
    </div>
  );
}

export default function PicksScreen({
  games,
  users,
  selectedUser,
  currentWeek,
  currentPicks,
  weatherData,
  teamAbbreviations = {},
  onSavePicks,
  onSelectUser,
  claimedUserIds,
}: PicksScreenProps) {
  const [selectedPicks, setSelectedPicks] = useState<TeamPick[]>(currentPicks);
  const [justSaved, setJustSaved] = useState(false);
  const [celebratePicks, setCelebratePicks] = useState<TeamPick[] | null>(null);
  const [lineNotice, setLineNotice] = useState<string | null>(null);

  useEffect(() => {
    setSelectedPicks(currentPicks);
    setJustSaved(false);
    setLineNotice(null);
  }, [currentPicks, selectedUser]);

  const handleTeamToggle = (gameId: string, team: string, spread: number) => {
    const game = games.find((candidate) => candidate.id === gameId);
    if (!game || isGameLocked(game)) return;
    setJustSaved(false);
    setLineNotice(null);

    // A saved pick's number can only ever improve. If the line moved AGAINST
    // the member since they saved, re-picking the same team keeps the saved
    // (better) number — a tap must never trade +3 down to +2.5.
    const savedPick = currentPicks.find(
      (pick) => pick.gameId === gameId && pick.team === team
    );
    const bestSpread =
      savedPick && savedPick.spread > spread ? savedPick.spread : spread;

    const sameIndex = selectedPicks.findIndex(
      (pick) => pick.gameId === gameId && pick.team === team
    );
    if (sameIndex >= 0) {
      // Same team at a better number: re-lock at that number (line shopping).
      // Otherwise the tap is a plain deselect — never a downgrade.
      if (bestSpread > selectedPicks[sameIndex].spread) {
        const next = [...selectedPicks];
        next[sameIndex] = { gameId, team, spread: bestSpread };
        setSelectedPicks(next);
      } else {
        setSelectedPicks(selectedPicks.filter((_, index) => index !== sameIndex));
      }
      return;
    }

    if (bestSpread !== spread) {
      setLineNotice(
        `${getMascotName(team)} moved to ${fmtSpread(spread)} — that's a worse number, so you keep your saved ${fmtSpread(bestSpread)}.`
      );
    }

    const otherIndex = selectedPicks.findIndex(
      (pick) => pick.gameId === gameId && pick.team !== team
    );
    if (otherIndex >= 0) {
      const next = [...selectedPicks];
      next[otherIndex] = { gameId, team, spread: bestSpread };
      setSelectedPicks(next);
      return;
    }
    if (selectedPicks.length < 3) {
      setSelectedPicks([...selectedPicks, { gameId, team, spread: bestSpread }]);
    }
  };

  const picksModified = useMemo(() => {
    if (selectedPicks.length !== currentPicks.length) return true;
    return selectedPicks.some((pick) => {
      const original = currentPicks.find((candidate) => candidate.gameId === pick.gameId);
      return !original || original.team !== pick.team || original.spread !== pick.spread;
    });
  }, [selectedPicks, currentPicks]);

  // Normally 3 picks, but a late member may have fewer than 3 games left to
  // choose from — then a full card is every pick still possible.
  const lockedPickCount = selectedPicks.filter((pick) => {
    const game = games.find((candidate) => candidate.id === pick.gameId);
    return !!game && isGameLocked(game);
  }).length;
  const openGameCount = games.filter((game) => !isGameLocked(game)).length;
  const picksNeeded = Math.min(3, lockedPickCount + openGameCount);
  const canSave =
    Boolean(selectedUser) && selectedPicks.length > 0 &&
    selectedPicks.length >= picksNeeded && picksModified;

  const grouped = useMemo(() => {
    const bySlot = new Map<string, Game[]>();
    for (const game of [...games].sort(
      (a, b) => +new Date(a.kickoff_et) - +new Date(b.kickoff_et)
    )) {
      const label = slotLabel(game.kickoff_et);
      bySlot.set(label, [...(bySlot.get(label) || []), game]);
    }
    return Array.from(bySlot.entries());
  }, [games]);

  const sideButton = (game: Game, team: string, spread: number) => {
    const picked = selectedPicks.some(
      (pick) => pick.gameId === game.id && pick.team === team
    );
    const locked = isGameLocked(game);
    const opening = team === game.away ? game.opening_spread_away : game.opening_spread_home;
    const moved = opening !== undefined && !Number.isNaN(opening) && opening !== spread;
    const savedPick = currentPicks.find(
      (pick) => pick.gameId === game.id && pick.team === team
    );
    const pendingPick = selectedPicks.find(
      (pick) => pick.gameId === game.id && pick.team === team
    );
    // The line moved in your favor since you saved — clicking the team again
    // re-locks the pick at the better number.
    const betterLine =
      !locked &&
      !!savedPick &&
      spread > savedPick.spread &&
      !(pendingPick && pendingPick.spread === spread);
    // The line moved AGAINST you since you saved — your better number stays
    // locked in, and tapping can never trade it down.
    const keptLine = !locked && !!savedPick && savedPick.spread > spread;
    return (
      <button
        className="pick-side"
        onClick={() => handleTeamToggle(game.id, team, spread)}
        disabled={locked}
        style={{
          flex: 1,
          display: 'flex',
          alignItems: 'center',
          gap: 8,
          border: `1.5px solid ${picked ? 'var(--accent)' : 'var(--line)'}`,
          borderRadius: 8,
          padding: '7px 10px',
          cursor: locked ? 'default' : 'pointer',
          background: picked ? 'var(--accent-soft)' : 'none',
          color: 'var(--ink)',
          fontSize: '0.88rem',
          fontWeight: 600,
          opacity: locked && !picked ? 0.45 : 1,
          minWidth: 0,
        }}
      >
        <img src={getTeamLogo(team)} alt="" style={{ width: 24, height: 24, flexShrink: 0 }} />
        <span className="team-full" style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
          {getMascotName(team)}
        </span>
        <span className="team-abbr">
          {teamAbbreviations[team] || getMascotName(team).substring(0, 3).toUpperCase()}
        </span>
        <span
          className="tnum"
          style={{
            marginLeft: 'auto',
            fontWeight: 700,
            color: picked ? 'var(--ink)' : 'var(--ink-soft)',
            textAlign: 'right',
            lineHeight: 1.15,
          }}
        >
          {spread > 0 ? `+${spread}` : spread}
          {moved && (
            <small
              style={{
                display: 'block',
                fontWeight: 500,
                fontSize: '0.62rem',
                color: 'var(--push)',
              }}
            >
              open {opening! > 0 ? `+${opening}` : opening}
            </small>
          )}
          {betterLine && (
            <small
              style={{
                display: 'block',
                fontWeight: 650,
                fontSize: '0.62rem',
                color: 'var(--win)',
              }}
            >
              ▲ yours {savedPick!.spread > 0 ? `+${savedPick!.spread}` : savedPick!.spread}
            </small>
          )}
          {keptLine && (
            <small
              style={{
                display: 'block',
                fontWeight: 650,
                fontSize: '0.62rem',
                color: 'var(--win)',
              }}
            >
              ✓ yours {fmtSpread(savedPick!.spread)}
            </small>
          )}
        </span>
      </button>
    );
  };

  const fetchedAt = games.find((game) => game.fetched_at)?.fetched_at;
  const linesAge = (() => {
    if (!fetchedAt) return null;
    const then = new Date(fetchedAt);
    if (Number.isNaN(then.getTime())) return null;
    const hours = Math.floor((Date.now() - then.getTime()) / 3_600_000);
    return hours < 1 ? 'just now' : hours < 24 ? `${hours}h ago` : `${Math.floor(hours / 24)}d ago`;
  })();

  // No name chosen yet: the picker is the whole screen — no browsing games
  // or making picks until you say who you are.
  if (!selectedUser) {
    return <WhoAreYouCard users={users} claimedUserIds={claimedUserIds} onSelect={onSelectUser} />;
  }

  return (
    <div>
      {linesAge && (
        <p style={{ color: 'var(--ink-soft)', fontSize: '0.78rem', margin: '12px 2px 0' }}>
          Lines updated {linesAge} · odds move during the week, and your number locks
          in when you save — shop wisely
        </p>
      )}
      <div className="sl-card" style={{
        position: 'sticky', top: 8, zIndex: 20, display: 'flex', alignItems: 'center',
        gap: 10, padding: '10px 12px', margin: '14px 0',
      }}>
        {[0, 1, 2].map((slotIndex) => {
          const pick = selectedPicks[slotIndex];
          const pickGame = pick ? games.find((game) => game.id === pick.gameId) : undefined;
          const pickLocked = !!pickGame && isGameLocked(pickGame);
          const chipSideSpread = !pickGame
            ? undefined
            : pick.team === pickGame.home
              ? pickGame.spread_home
              : pick.team === pickGame.away
                ? pickGame.spread_away
                : undefined;
          const chipBetterLine =
            !pickLocked && chipSideSpread !== undefined && chipSideSpread > pick.spread;
          return (
            <div
              key={slotIndex}
              style={{
                flex: 1,
                border: `1.5px ${
                  pick ? (pickLocked ? 'solid var(--line)' : 'solid var(--accent)') : 'dashed var(--line)'
                }`,
                borderRadius: 8,
                padding: '5px 8px',
                fontSize: '0.78rem',
                color: pick && !pickLocked ? 'var(--ink)' : 'var(--ink-soft)',
                background: pick ? (pickLocked ? 'var(--chip)' : 'var(--accent-soft)') : 'none',
                fontWeight: pick ? 650 : 400,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 6,
                minHeight: 36,
                minWidth: 0,
              }}
            >
              {pick ? (
                <>
                  {pickLocked && <span style={{ fontSize: '0.72rem' }}>🔒</span>}
                  <img
                    src={getTeamLogo(pick.team)}
                    alt=""
                    style={{ width: 20, height: 20, ...(pickLocked ? { filter: 'grayscale(1)', opacity: 0.7 } : {}) }}
                  />
                  <span className="tnum" style={{ whiteSpace: 'nowrap' }}>
                    {pick.spread > 0 ? `+${pick.spread}` : pick.spread}
                  </span>
                  {chipBetterLine && (
                    <span style={{ color: 'var(--win)', fontSize: '0.72rem', fontWeight: 700 }}>▲</span>
                  )}
                </>
              ) : (
                `Pick ${slotIndex + 1}`
              )}
            </div>
          );
        })}
        <button
          onClick={async () => {
            if (canSave) {
              setLineNotice(null);
              const snapshot = [...selectedPicks];
              const ok = await onSavePicks(snapshot);
              if (ok) {
                setCelebratePicks(snapshot);
                setJustSaved(true);
              }
            }
          }}
          disabled={!canSave}
          style={{
            background: justSaved && !picksModified ? 'var(--win-bg)' : 'var(--accent)',
            color: justSaved && !picksModified ? 'var(--win)' : 'var(--accent-ink)',
            border: 'none',
            borderRadius: 8,
            fontWeight: 700,
            padding: '10px 14px',
            fontSize: '0.82rem',
            cursor: canSave ? 'pointer' : 'default',
            opacity: canSave || (justSaved && !picksModified) ? 1 : 0.45,
            whiteSpace: 'nowrap',
          }}
        >
          {justSaved && !picksModified
            ? 'Saved ✓'
            : currentPicks.length > 0
            ? 'Update picks'
            : 'Save picks'}
        </button>
      </div>

      {lineNotice && (
        <div
          className="sl-card"
          role="status"
          onClick={() => setLineNotice(null)}
          style={{
            position: 'fixed',
            left: 12,
            right: 12,
            bottom: 84,
            zIndex: 95,
            border: '1.5px solid var(--push)',
            padding: '10px 12px',
            fontSize: '0.82rem',
            color: 'var(--ink)',
            boxShadow: '0 4px 14px rgba(0,0,0,0.18)',
            cursor: 'pointer',
          }}
        >
          ⚠️ {lineNotice}
        </div>
      )}

      {celebratePicks && (
        <div
          onClick={() => setCelebratePicks(null)}
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 100,
            background: 'var(--paper)',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: 26,
            padding: 20,
          }}
        >
          <div className="disp" style={{ fontSize: '0.85rem', letterSpacing: '0.2em', color: 'var(--accent)', fontWeight: 700 }}>
            WEEK {currentWeek} · PICKS ARE IN
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 22 }}>
            {celebratePicks.map((pick, index) => (
              <div key={index} style={{ display: 'flex', alignItems: 'center', gap: 18 }}>
                <img src={getTeamLogo(pick.team)} alt="" style={{ width: 72, height: 72 }} />
                <div>
                  <div className="disp" style={{ fontSize: '1.7rem', fontWeight: 700, lineHeight: 1.1 }}>
                    {getMascotName(pick.team)}
                  </div>
                  <div className="tnum" style={{ fontSize: '1.15rem', fontWeight: 700, color: 'var(--ink)' }}>
                    {pick.spread > 0 ? `+${pick.spread}` : pick.spread}
                  </div>
                </div>
              </div>
            ))}
          </div>
          <div style={{ color: 'var(--ink-soft)', fontSize: '0.85rem' }}>
            Locked to your numbers. Good luck. 🍀
          </div>
          <button
            onClick={() => setCelebratePicks(null)}
            style={{
              background: 'var(--accent)',
              color: 'var(--accent-ink)',
              border: 'none',
              borderRadius: 10,
              fontWeight: 700,
              padding: '12px 34px',
              fontSize: '0.95rem',
              cursor: 'pointer',
            }}
          >
            Done
          </button>
        </div>
      )}

      {grouped.map(([label, slotGames]) => (
        <React.Fragment key={label}>
          <h2 className="sl-sec">{label}</h2>
          <div className="sl-card">
            {slotGames.map((game) => {
              const weather = weatherData.find((row) => row.team === game.home);
              const chip = weatherChip(weather?.weather_summary);
              const locked = isGameLocked(game);
              return (
                <div
                  key={game.id}
                  className="pick-row"
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    padding: '11px 14px',
                    borderBottom: '1px solid var(--line)',
                  }}
                >
                  {sideButton(game, game.away, game.spread_away)}
                  {sideButton(game, game.home, game.spread_home)}
                  <div
                    className="pick-meta"
                    style={{
                      width: 92,
                      textAlign: 'center',
                      fontSize: '0.7rem',
                      color: 'var(--ink-soft)',
                      lineHeight: 1.35,
                      flexShrink: 0,
                    }}
                  >
                    <b style={{ color: 'var(--ink)', display: 'block', fontSize: '0.74rem' }}>
                      {locked ? '🔒 locked' : kickoffShort(game.kickoff_et)}
                    </b>
                    <span style={{ display: 'block' }}>O/U {game.total}</span>
                    {chip && <span style={{ display: 'block' }}>{chip}</span>}
                  </div>
                </div>
              );
            })}
          </div>
        </React.Fragment>
      ))}
    </div>
  );
}
