/**
 * Intent for ChartFactory.suggest — the question behind the chart.
 *
 * The same rows answer different questions, and each question needs its own
 * aggregation, grain and chart: revenue by country on order rows is a bar of
 * totals for "how much", a boxplot for "how big is a typical order", a donut
 * for "what share". Intent makes the question an input.
 *
 * Sources, in precedence order (the result says which one it used):
 *   1. explicit   suggest(rows, { intent: 'magnitude', show: 'summary' })
 *   2. ask        suggest(rows, { ask: 'how much revenue by country?' }) — a
 *                 small deterministic keyword grammar, never a model call
 *   3. assumed    inferred from the data's shape (today's behavior), flagged
 *
 * `show` is the second half of intent: whether the reader wants the
 * aggregate ('summary': totals, boxes, a mean line) or the actual data
 * points ('individuals': dots, swarms, labeled points) — or 'both'.
 */

export const INTENTS = {
    magnitude: 'how much — totals or values compared across categories',
    ranking: 'top / bottom — the order of the items is the point',
    trend: 'how it moved over time',
    change: 'what changed between two points (before / after, this year vs last)',
    composition: 'parts of one whole — share, mix, breakdown',
    distribution: 'spread, typical value, outliers',
    relationship: 'how two measures move together',
    deviation: 'above / below a reference (zero, the average, a target)',
    flow: 'from → to, funnels, drop-off',
    lookup: 'exact values, a list to read',
};
export const intentNames = Object.keys(INTENTS);

// Ordered: the first matching rule wins (flow before change, deviation
// before magnitude, …). Patterns run on the lower-cased ask.
const ASK_RULES = [
    ['flow', /\b(funnel|drop-?off|conversion funnel|pipeline|journey|flows?|where do .+ go|from .+ (to|into) )/],
    ['deviation', /\b(above|below|over|under|beat|missed?)\s+(the\s+)?(average|avg|mean|median|target|plan|budget|goal|forecast|quota)\b|\bvs\.?\s+(target|plan|budget|goal|forecast)\b|\bdeviat|\bvariance (to|from|vs)/],
    ['composition', /\b(share|mix|breakdown|break(s)? down|percent(age)? of|% of|proportion|split (by|of|between)|make ?up|composition|part of (the )?(total|whole))\b/],
    ['distribution', /\b(distribut\w*|spread|typical|range of|variab\w*|histogram|outliers?|how (big|large|long|high|fast|old) (is|are|was|were) (a |the )?typical|median|percentile)/],
    ['relationship', /\b(relat\w*|correlat\w*|drives?|affects?|impacts?|associated|depends? on|against)\b/],
    ['change', /\b(vs\.?|versus|compared? (to|with)|change[ds]?|improv\w*|declin\w*|grew|growth|before|after|last (year|season|month|quarter|week)|year over year|yoy|from \d{4} to \d{4})\b/],
    ['trend', /\b(over time|trend\w*|by (day|week|month|quarter|year|date|season|hour)|daily|weekly|monthly|quarterly|yearly|annual\w*|since|history|historical|pace|timeline|over the (years|season|months|weeks))\b/],
    ['ranking', /\b(top|bottom|best|worst|highest|lowest|leaders?|leaderboard|rank\w*|most|least|biggest|smallest)\b/],
    ['lookup', /\b(list|table of|exact|details?|look ?up|show (me )?all)\b/],
    ['magnitude', /\b(how (much|many)|totals?|sum|amount|count|volume|compare|by)\b/],
];
const SHOW_RULES = [
    ['individuals', /\b(which ones|who|individual\w*|outliers?|every single|each (player|customer|order|person|item|row|transaction)|show me the (players|customers|orders|people|items|rows|points))\b/],
    ['summary', /\b(typical|average|avg|overall|in general|on average|median|spread)\b/],
];

const words = name => String(name).replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 1);

/** The field names an ask mentions (a field matches when one of its words — or its plural/singular — appears). */
function mentioned(ask, fields) {
    const text = ` ${ask.toLowerCase().replace(/[^a-z0-9]+/g, ' ')} `;
    const hits = [];
    for (const f of fields) {
        const ws = words(f.name);
        const forms = ws.flatMap(w => [w, w.endsWith('s') ? w.slice(0, -1) : `${w}s`, w.endsWith('y') ? `${w.slice(0, -1)}ies` : null]).filter(Boolean);
        const at = forms.map(w => text.indexOf(` ${w} `)).filter(i => i >= 0);
        if (at.length) hits.push({ name: f.name, at: Math.min(...at) });
    }
    return hits.sort((a, b) => a.at - b.at).map(h => h.name);
}

/** Parse a plain-English question into { intent, show, subject, matched }. */
export function parseAsk(ask, fields = []) {
    const text = String(ask || '').toLowerCase();
    let intent = null, matched = null;
    for (const [name, re] of ASK_RULES) {
        const m = re.exec(text);
        if (m) { intent = name; matched = m[0].trim(); break; }
    }
    let show = null;
    for (const [name, re] of SHOW_RULES) if (re.test(text)) { show = name; break; }
    if (intent === 'distribution' && !show) show = 'summary';
    return { intent, show, matched, subject: mentioned(text, fields) };
}

/**
 * The intent a call runs under: { value, show, source, subject, matched }.
 * value is null when nothing set one (the shape decides, flagged 'assumed').
 */
export function resolveIntent(opts = {}, fields = []) {
    const explicit = opts.intent && INTENTS[opts.intent] ? opts.intent : null;
    if (opts.intent && !explicit) console.warn(`ChartFactory.suggest: unknown intent '${opts.intent}' — one of ${intentNames.join(', ')}`);
    const parsed = opts.ask ? parseAsk(opts.ask, fields) : null;
    const show = ['summary', 'individuals', 'both'].includes(opts.show) ? opts.show : (parsed && parsed.show) || null;
    if (explicit) return { value: explicit, show, source: 'explicit', subject: parsed ? parsed.subject : [], matched: null };
    if (parsed && parsed.intent) return { value: parsed.intent, show, source: 'ask', subject: parsed.subject, matched: parsed.matched };
    return { value: null, show, source: 'assumed', subject: parsed ? parsed.subject : [], matched: null };
}

/** Which intents a candidate answers, by builder (rules may override per candidate). */
export const INTENT_OF = {
    'Line.createBasic': ['trend'],
    'Line.createMulti': ['trend', 'change'],
    'Line.createYoY': ['trend', 'change'],
    'Line.createBumpChart': ['ranking', 'trend'],
    'Line.createBand': ['trend', 'deviation'],
    'Area.createStacked': ['composition', 'trend'],
    'Calendar.createHeatmap': ['trend', 'distribution'],
    'Slope.createBasic': ['change'],
    'Dot.createDumbbell': ['change', 'deviation'],
    'Bar.createBasic': ['magnitude', 'ranking'],
    'Bar.createVertical': ['magnitude', 'trend'],
    'Bar.createStacked': ['composition', 'magnitude'],
    'Bar.createGrouped': ['magnitude'],
    'Bar.createVerticalStacked': ['composition', 'trend'],
    'Bar.createLikert': ['distribution', 'composition'],
    'Bar.createGantt': ['lookup', 'trend'],
    'Bar.createRange': ['distribution', 'magnitude'],
    'Bar.createWaterfall': ['composition', 'change'],
    'Bar.createDiverging': ['deviation'],
    'Donut.createBasic': ['composition'],
    'Donut.createPie': ['composition'],
    'Treemap.createBasic': ['composition', 'magnitude'],
    'Funnel.createBasic': ['flow'],
    'Sankey.createBasic': ['flow', 'composition'],
    'Sankey.createFunnelFlow': ['flow'],
    'BoxPlot.createBasic': ['distribution'],
    'BoxPlot.createViolin': ['distribution'],
    'Dot.createConfidence': ['magnitude', 'deviation'],
    'Radar.createBasic': ['magnitude'],
    'Histogram.createBasic': ['distribution'],
    'Histogram.createOverlay': ['distribution'],
    'Scatter.createBeeswarm': ['distribution'],
    'Scatter.createBeeswarmHorizontal': ['distribution'],
    'Scatter.createBasic': ['relationship'],
    'Scatter.createDensity': ['relationship', 'distribution'],
    'Scatter.createContour': ['relationship', 'distribution'],
    'Scatter.createHeatmap': ['magnitude', 'distribution'],
    'Table.createWithBars': ['lookup', 'ranking', 'magnitude'],
    'facet': ['trend', 'magnitude'],
};
