// Standings/records math shared by the screens. Everything routes through
// calcRecord (the house push rule: pushes count in the denominator only).
import { Pick, TeamPick, User } from './types';
import { calcRecord, isPlayoffWeek } from './seasonConfig';

export const gradeOf = (pick: TeamPick): 'W' | 'L' | 'P' | null => {
  if (pick.result === 'W' || pick.result === 'L' || pick.result === 'P') return pick.result;
  if (pick.correct === true) return 'W';
  if (pick.correct === false) return 'L';
  return null;
};

export const regularSeason = (picks: Pick[]) =>
  picks.filter((userWeek) => !isPlayoffWeek(userWeek.week));

export function userTeamPicks(picks: Pick[], userId: string, throughWeek?: number): TeamPick[] {
  return regularSeason(picks)
    .filter(
      (userWeek) =>
        userWeek.userId === userId &&
        (throughWeek === undefined || userWeek.week <= throughWeek)
    )
    .sort((a, b) => a.week - b.week)
    .flatMap((userWeek) => userWeek.picks);
}

export function recordString(record: { wins: number; losses: number; pushes: number }): string {
  const base = `${record.wins}–${record.losses}`;
  return record.pushes > 0 ? `${base}–${record.pushes}` : base;
}

export interface StandingRow {
  rank: number;
  movement: number; // + up, - down vs one week earlier
  userId: string;
  name: string;
  wins: number;
  losses: number;
  pushes: number;
  record: string;
  winPct: number;
  isLeader: boolean;
  isLast: boolean;
}

function rankUsers(picks: Pick[], users: User[], throughWeek?: number) {
  return users
    .map((user) => {
      const teamPicks = userTeamPicks(picks, user.id, throughWeek);
      const record = calcRecord(teamPicks);
      return { user, teamPicks, record };
    })
    .sort(
      (a, b) =>
        b.record.wins - a.record.wins || b.record.pct - a.record.pct
    );
}

export function computeStandings(picks: Pick[], users: User[]): StandingRow[] {
  const now = rankUsers(picks, users);

  // Movement: compare to the ranking with the latest graded week removed
  const gradedWeeks = regularSeason(picks)
    .filter((userWeek) => userWeek.picks.some((pick) => gradeOf(pick) !== null))
    .map((userWeek) => userWeek.week);
  const latestGraded = gradedWeeks.length ? Math.max(...gradedWeeks) : 0;
  const before = rankUsers(picks, users, latestGraded - 1);
  const rankBefore = new Map(before.map((entry, index) => [entry.user.id, index + 1]));

  const anyGraded = now.some((entry) => entry.record.graded > 0);

  return now.map((entry, index) => ({
    rank: index + 1,
    movement: (rankBefore.get(entry.user.id) ?? index + 1) - (index + 1),
    userId: entry.user.id,
    name: entry.user.name,
    wins: entry.record.wins,
    losses: entry.record.losses,
    pushes: entry.record.pushes,
    record: recordString(entry.record),
    winPct: entry.record.pct,
    isLeader: anyGraded && index === 0,
    isLast: anyGraded && index === now.length - 1,
  }));
}

// Stable per-player colors (Paul Tol "bright" — 7 distinct, CVD-safe).
// Index-aligned with the users array so every chart agrees.
export const PLAYER_COLORS = [
  '#4477AA', // blue
  '#EE6677', // rose
  '#228833', // green
  '#CCBB44', // gold
  '#66CCEE', // sky
  '#AA3377', // plum
  '#EE7733', // orange
];

export const playerColor = (index: number) => PLAYER_COLORS[index % PLAYER_COLORS.length];

// Avatar identity: same color as the player's chart line, everywhere.
const PLAYER_IDS = ['jacob', 'cam', 'connor', 'nathan', 'shane', 'max', 'john'];

export const playerColorById = (id: string) =>
  playerColor(Math.max(0, PLAYER_IDS.indexOf(id)));

// Light text on most palette colors; dark on the two light ones (gold, sky)
export const playerInkById = (id: string) => {
  const index = Math.max(0, PLAYER_IDS.indexOf(id));
  return index === 3 || index === 4 ? '#1a1c1e' : '#ffffff';
};

// Two-letter initials where single letters collide (Ja/Jo, Ca/Co)
const INITIALS: { [name: string]: string } = {
  Jacob: 'Ja',
  John: 'Jo',
  Cam: 'Ca',
  Connor: 'Co',
};
export const playerInitials = (name: string) => INITIALS[name] ?? name[0];

// Rank standings after each graded week, for the bump chart.
export function rankHistory(picks: Pick[], users: User[]) {
  const weeks = Array.from(
    new Set(
      regularSeason(picks)
        .filter((userWeek) => userWeek.picks.some((pick) => gradeOf(pick) !== null))
        .map((userWeek) => userWeek.week)
    )
  ).sort((a, b) => a - b);

  const rankings = new Map<string, Array<{ period: string; rank: number }>>(
    users.map((user) => [user.id, []])
  );

  for (const week of weeks) {
    const ordered = users
      .map((user) => ({ user, record: calcRecord(userTeamPicks(picks, user.id, week)) }))
      .sort((a, b) => b.record.wins - a.record.wins || b.record.pct - a.record.pct);
    ordered.forEach((entry, index) => {
      rankings.get(entry.user.id)!.push({ period: `W${week}`, rank: index + 1 });
    });
  }

  return users.map((user, index) => ({
    name: user.name,
    color: playerColor(index),
    rankings: rankings.get(user.id)!,
  }));
}

// Cumulative win% by week per user, for the trend chart.
export function cumulativeTrend(picks: Pick[], users: User[]) {
  const weeks = Array.from(
    new Set(
      regularSeason(picks)
        .filter((userWeek) => userWeek.picks.some((pick) => gradeOf(pick) !== null))
        .map((userWeek) => userWeek.week)
    )
  ).sort((a, b) => a - b);

  return users.map((user, index) => ({
    name: user.name,
    color: playerColor(index),
    data: weeks
      .map((week) => {
        const record = calcRecord(userTeamPicks(picks, user.id, week));
        return record.graded > 0 ? { x: week, y: Math.round(record.pct * 10) / 10 } : null;
      })
      .filter(Boolean) as Array<{ x: number; y: number }>,
  }));
}

// ---- Trends: picks joined to final scores ----

export interface GameResult {
  week: number;
  gameId: string;
  away: string;
  home: string;
  awayScore: number;
  homeScore: number;
}

export interface TrendPick {
  userId: string;
  name: string;
  week: number;
  gameId: string;
  team: string;
  opponent: string;
  spread: number;
  teamScore: number;
  oppScore: number;
  cover: number; // points the pick beat (+) or missed (−) its own saved spread by
  result: 'W' | 'L' | 'P';
  favorite: boolean;
  home: boolean;
}

export function trendPicks(picks: Pick[], users: User[], results: GameResult[]): TrendPick[] {
  const byGame = new Map(results.map((game) => [`${game.week}|${game.gameId}`, game]));
  const nameOf = new Map(users.map((user) => [user.id, user.name]));
  return regularSeason(picks).flatMap((userWeek) =>
    userWeek.picks.flatMap((pick) => {
      const result = gradeOf(pick);
      const game = byGame.get(`${userWeek.week}|${pick.gameId}`);
      if (!result || !game || (pick.pickType && pick.pickType !== 'spread')) return [];
      const home = pick.team === game.home;
      if (!home && pick.team !== game.away) return [];
      const teamScore = home ? game.homeScore : game.awayScore;
      const oppScore = home ? game.awayScore : game.homeScore;
      return [{
        userId: userWeek.userId,
        name: nameOf.get(userWeek.userId) ?? userWeek.userId,
        week: userWeek.week,
        gameId: pick.gameId,
        team: pick.team,
        opponent: home ? game.away : game.home,
        spread: pick.spread,
        teamScore,
        oppScore,
        cover: teamScore - oppScore + pick.spread,
        result,
        favorite: pick.spread < 0,
        home,
      }];
    })
  );
}

export interface SplitStat {
  record: string;
  pct: number; // 0–100, house push rule
  graded: number;
  margin: number; // summed cover margin
}

export function splitStat(rows: Array<{ result: 'W' | 'L' | 'P'; cover: number }>): SplitStat {
  const record = calcRecord(rows);
  return {
    record: recordString(record),
    pct: record.pct,
    graded: record.graded,
    margin: rows.reduce((sum, row) => sum + row.cover, 0),
  };
}

export const SPREAD_BUCKETS = [
  { label: '0–3', test: (abs: number) => abs <= 3 },
  { label: '3.5–6.5', test: (abs: number) => abs > 3 && abs <= 6.5 },
  { label: '7+', test: (abs: number) => abs > 6.5 },
];

// Games where 3+ players took the same side, one row per game-side.
export function consensusPicks(rows: TrendPick[], minPlayers = 3) {
  const groups = new Map<string, TrendPick[]>();
  rows.forEach((row) => {
    const key = `${row.week}|${row.gameId}|${row.team}`;
    groups.set(key, [...(groups.get(key) ?? []), row]);
  });
  return Array.from(groups.values())
    .filter((group) => group.length >= minPlayers)
    .map((group) => ({ ...group[0], players: group.map((row) => row.name) }))
    .sort((a, b) => a.week - b.week || b.players.length - a.players.length);
}

export const signed = (value: number) => `${value > 0 ? '+' : ''}${value.toFixed(1)}`;
export const fmtSpread = (spread: number) => (spread > 0 ? `+${spread}` : spread === 0 ? 'PK' : `${spread}`);
