/**
 * ChartFactory.suggest(rows, options?) — runtime chart recommendation.
 *
 * Applies the chart-selection layer (docs/chart-guide.md) to real rows:
 *   1. PROFILE  each field: kind (temporal | numeric | categorical | boolean |
 *               id), distinct count, null count, numeric/temporal extent.
 *   2. SIGNATURE from the profiles: measures, dimensions, temporal fields,
 *               an entity/name field, rows-per-group shape.
 *   3. RULES    the guide's signature table as scored rules, adjusted by each
 *               builder's cardinality comfort ranges from the conformance
 *               metadata (builder-metadata.generated.mjs).
 *   4. SYNTHESIZE a render-ready { data, config } per candidate in the
 *               builder's canonical record shape (mapped/grouped/pivoted from
 *               the input rows — inputs are never mutated).
 *
 * Returns { fields, signature, candidates } — candidates sorted by score
 * (0..1), each { builder, score, why[], caveats[], data, config, transform,
 * create(selector, overrides?) }, plus result-level `affordances`: facts
 * about the rows (time grain and span, dimensions, how each measure
 * aggregates, what is missing) for the caller to ask its next question from.
 * It is an advisor: the library does what is deterministic and checkable;
 * the question, what is interesting and what to fetch next are the caller's.
 *
 * This is a heuristic assistant, not an oracle: it can read shape and
 * cardinality, but not intent. It cannot know that values are parts of one
 * whole, that a center is defensible, or that two same-scale measures are the
 * same unit — those judgments surface as caveats on the affected candidates.
 * Tables are never suggested (they require Table.register()); when precision
 * beats perception, a caveat says so.
 */

import { BUILDER_METADATA } from './builder-metadata.generated.mjs';
import { ISO_DATE_RE, detectDateFormat, parseNumber, numberOf, timeOf, emitTime } from './suggest-parse.js';
import { resolveIntent, INTENT_OF, intentNames } from './suggest-intent.js';

const PROFILE_SAMPLE = 1000;
const EXACT_DISTINCT_MAX = 200000;

// ---------------------------------------------------------------------------
// 1. Field profiling
// ---------------------------------------------------------------------------

/**
 * Rows the profiler reads for KIND: the whole table up to PROFILE_SAMPLE
 * rows, past that a stratified sample (head, tail and evenly spaced rows), so
 * a file sorted by a column shows the profiler every part of it.
 */
function sampleRows(rows) {
    if (rows.length <= PROFILE_SAMPLE) return rows;
    const out = [];
    const step = rows.length / PROFILE_SAMPLE;
    for (let i = 0; i < PROFILE_SAMPLE; i++) out.push(rows[Math.floor(i * step)]);
    out[PROFILE_SAMPLE - 1] = rows[rows.length - 1];
    return out;
}

const blank = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');

function profileField(name, values, allRows) {
    const nonNull = values.filter(v => !blank(v));
    const nulls = values.length - nonNull.length;
    // DISTINCT and COUNT are exact over every row (the kind is read from the
    // sample): a 1,500-row table of unique names has 1,500 names, not 1,000.
    const exact = new Set();
    let count = 0, allNulls = 0;
    const rowsToScan = allRows.length <= EXACT_DISTINCT_MAX ? allRows : allRows.slice(0, EXACT_DISTINCT_MAX);
    for (const r of rowsToScan) {
        const v = (r || {})[name];
        if (blank(v)) { allNulls++; continue; }
        count++;
        exact.add(v instanceof Date ? `d${v.getTime()}` : typeof v === 'string' ? v.trim() : v);
    }
    const distinct = exact.size;
    if (nonNull.length === 0) return { name, kind: 'empty', distinct: 0, nulls: allNulls, count: 0 };
    const base = { name, distinct, nulls: allNulls, count };
    const share = c => c / nonNull.length;

    // Dates: Date objects, or strings in one shared written format.
    const dateObjs = nonNull.filter(v => v instanceof Date).length;
    const strings = nonNull.filter(v => typeof v === 'string').map(v => v.trim());
    let dateFormat = null;
    if (strings.length >= 0.9 * nonNull.length && strings.length > 0) dateFormat = detectDateFormat(strings);
    if (share(dateObjs) >= 0.9 || dateFormat) {
        const field = { name, dateFormat };
        const times = nonNull.map(v => timeOf(v, field)).filter(Number.isFinite).sort((a, b) => a - b);
        if (times.length >= 0.9 * nonNull.length) {
            const gaps = [];
            const uniq = [...new Set(times)];
            for (let i = 1; i < Math.min(uniq.length, 400); i++) gaps.push(uniq[i] - uniq[i - 1]);
            gaps.sort((a, b) => a - b);
            const medianGapMs = gaps.length ? gaps[Math.floor(gaps.length / 2)] : null;
            return { ...base, kind: 'temporal', min: times[0], max: times[times.length - 1], medianGapMs,
                dateFormat: dateFormat || null, repeats: times.length > uniq.length };
        }
    }

    // Styling and media columns (hex colors, image URLs) describe how to draw
    // a row, never what to chart.
    if (strings.length === nonNull.length && strings.every(v => /^(#[0-9a-f]{3,8}|rgba?\(.*\)|hsla?\(.*\))$/i.test(v))) return { ...base, kind: 'style' };
    if (strings.length === nonNull.length && strings.every(v => /^(https?:\/\/|\/|\.\.?\/)\S+$/i.test(v) || /\.(png|jpe?g|svg|gif|webp)$/i.test(v))) return { ...base, kind: 'media' };

    const booleans = nonNull.filter(v => typeof v === 'boolean').length;
    if (share(booleans) >= 0.9) return { ...base, kind: 'boolean' };

    // Numbers, including the way spreadsheets write them ('1,240', '$3.2M',
    // '4.7%'). A leading-zero integer is a code, so a column of them is text.
    let numbers = 0, codes = 0;
    const nums = [];
    const units = new Map();
    let currency = false;
    for (const v of nonNull) {
        const p = parseNumber(typeof v === 'number' ? v : typeof v === 'string' ? v : null);
        if (!p) continue;
        if (p.code) { codes++; continue; }
        numbers++;
        nums.push(p.value);
        if (p.unit) units.set(p.unit, (units.get(p.unit) || 0) + 1);
        if (p.currency) currency = true;
    }
    if (share(numbers) >= 0.9 && codes === 0) {
        let min = Infinity, max = -Infinity;
        for (const n of nums) { if (n < min) min = n; if (n > max) max = n; }
        const allInt = nums.every(Number.isInteger);
        const sampleDistinct = new Set(nums).size;
        // Year-like integers (1500..2100, several distinct values) can serve
        // as the temporal axis when no true date field exists.
        const yearLike = allInt && min >= 1500 && max <= 2100 && distinct >= 3 && sampleDistinct >= 3;
        let unit = null;
        for (const [u, c] of units) if (c >= 0.5 * numbers) unit = u;
        const written = nonNull.some(v => typeof v === 'string' && !Number.isFinite(Number(v.trim())));
        return { ...base, kind: 'numeric', min, max, allInt, yearLike, unit, currency, written };
    }
    // Strings: id-like when unique per row, categorical otherwise.
    // Near-unique (90%) names a row; `unique` (every value once) is kept for
    // the small tables where a 5-row team column is both the category axis
    // and the label of each row.
    const unique = distinct === count;
    if (distinct >= 0.9 * count && count > 6) return { ...base, kind: 'id', unique, codes: codes > 0 };
    return { ...base, kind: 'categorical', unique, codes: codes > 0 };
}

export function profileFields(rows) {
    const sample = sampleRows(rows);
    const keys = new Set();
    for (const r of sample) for (const k of Object.keys(r || {})) keys.add(k);
    return [...keys].map(k => profileField(k, sample.map(r => (r || {})[k]), rows));
}

// ---------------------------------------------------------------------------
// 2. Signature
// ---------------------------------------------------------------------------

const DAY_MS = 24 * 3600 * 1000;
const PAIR_PATTERNS = [
    [/^(before|prev|previous|last|old|start|from|open|low|min)$/i, /^(after|next|current|new|end|to|close|high|max)$/i],
    [/^(budget|budgeted|plan|planned|target|goal|forecast|expected|estimate|estimated|quota)$/i, /^(actual|actuals|real|result|achieved|spent)$/i],
]; 

// ---- Identifiers -----------------------------------------------------------
// An identifier NAMES a thing (team_id, playerID, user.id); it never measures
// or orders anything. The word "id" must stand at a word boundary — the whole
// name, after a separator, or camelCase after a lowercase letter — so a word
// that merely ends in those letters (PAID, TOTAL_PAID, COVID, VALID, AVOID)
// is not one.
const ID_WORD = /(^|[_\s.-])id$/i;
const ID_CAMEL = /[a-z](Id|ID)$/;
const idNamed = name => ID_WORD.test(name) || ID_CAMEL.test(name);

const YEAR_NAME = /(^|[_\s.-])(year|yr|yy|yyyy|season|fy|fiscal_?year)s?($|[_\s.-])|^(year|yr|season|fy)/i;
const CODE_NAME = /(^|[_\s.-])(zip|zipcode|postal|postcode|fips|sku|upc|isbn|ean|phone|area_?code|code)$/i;
const present = v => v !== null && v !== undefined && !(typeof v === 'string' && v.trim() === '');
const cellKey = v => (v instanceof Date ? String(v.getTime()) : String(v));

/** Whether a column GROUPS the rows: 2+ values, 2+ rows per value on average. */
function groupsRows(rows, name) {
    const values = new Set();
    let n = 0;
    for (const r of rows) {
        if (!present(r[name])) continue;
        n++;
        values.add(cellKey(r[name]));
    }
    return values.size >= 2 && values.size * 2 <= n;
}

/**
 * Whether the values in `rows[name]` are distinct within each group of the
 * column `group` (every value when `group` is null). Missing values — and
 * rows missing their group — are skipped: they name nothing.
 */
function distinctWithin(rows, name, group) {
    const seen = new Map();
    for (const r of rows) {
        const v = r[name];
        if (!present(v) || (group && !present(r[group]))) continue;
        const g = group ? cellKey(r[group]) : '';
        if (!seen.has(g)) seen.set(g, new Set());
        const s = seen.get(g), k = String(Number(v));
        if (s.has(k)) return false;
        s.add(k);
    }
    return true;
}

/**
 * A numeric column is an IDENTIFIER when it is named as one AND its values
 * look like one: whole numbers, all distinct — overall, or within each group
 * of another column that groups the rows (a team_id recurs every season, once
 * per season). Either test alone is not enough: COVID cases and TOTAL_PAID
 * are measures by name, and a pipe's inner diameter `id` (12.5 mm) or a
 * foreign key repeated inside every group is a measure by value. A year held
 * under such a name (yearID) is a year.
 */
function isIdentifier(rows, f, fields) {
    if (!idNamed(f.name) || !f.allInt || (yearish(f) && YEAR_NAME.test(f.name))) return false;
    if (distinctWithin(rows, f.name, null)) return true;
    return fields.some(g => g !== f && groupsRows(rows, g.name) && distinctWithin(rows, f.name, g.name));
}

// ---- Year-over-year rows ----------------------------------------------------
// suggest() reads rows as YEAR-OVER-YEAR only when they are clearly shaped so:
// a wrong reading draws a wrong chart, while a missed one only falls back to
// the ordinary suggestion. yearOverYear() says what counts.
//
// A within-year position is NAMED as one, never read from the values alone:
// counts, ranks, codes and ids are whole numbers unique inside a year too.
// The name is a position word (day, doy, day_of_year, week, wk, month, mo,
// quarter, qtr, q), either the whole name or a word of a name split at `_`,
// `-` and spaces whose other words only qualify it (game_day, week_num,
// fiscal_month, day_of_week; never day_high or sales_per_day). Each word
// allows the values its unit spans, counted from 1 or from 0.
//
// The name only nominates: the values decide. A short name is judged like
// any other, so a `q` or `mo` of decimals (a discharge, months of supply) or
// out of its unit's range (q = 1..6) is no position. A `q` of 1..4 that
// numbers something else (four survey questions, a fund's quartile) cannot
// be told from quarters by its values: alone beside the year and a measure
// it reads as a quarter; the text it numbers (the question, the fund) is a
// key, so beside it the rows are a panel.
const POSITION_NAME = /^(day|doy|day_?of_?year|week|wk|month|mo|mnth|mth|quarter|qtr|q)$/i;
const POSITION_RANGES = {
    day: [[1, 366], [0, 365]], doy: [[1, 366], [0, 365]], dayofyear: [[1, 366], [0, 365]],
    week: [[1, 53], [0, 53]], wk: [[1, 53], [0, 53]],
    month: [[1, 12], [0, 11]], mo: [[1, 12], [0, 11]], mnth: [[1, 12], [0, 11]], mth: [[1, 12], [0, 11]],
    quarter: [[1, 4], [0, 3]], qtr: [[1, 4], [0, 3]], q: [[1, 4], [0, 3]],
};
const POSITION_QUALIFIERS = new Set(['of', 'in', 'the', 'year', 'yr', 'num', 'number', 'no', 'nr', 'idx',
    'fiscal', 'fy', 'cal', 'calendar', 'iso', 'season', 'game']);
const own = (o, k) => Object.prototype.hasOwnProperty.call(o, k);

/** The position word a column's name holds (a POSITION_RANGES key), or null. */
function positionWord(name) {
    const whole = POSITION_NAME.exec(String(name));
    if (whole) return whole[1].toLowerCase().replace(/_/g, '');
    const words = String(name).toLowerCase().split(/[_\s-]+/).filter(Boolean);
    const word = words.find(w => own(POSITION_RANGES, w));
    return word && words.every(w => own(POSITION_RANGES, w) || POSITION_QUALIFIERS.has(w)) ? word : null;
}

// An integer column that can hold years (the profile's `yearLike` also
// needs 3+ distinct values: what a time axis needs, not a group).
const yearish = f => f.kind === 'numeric' && f.allInt && f.min >= 1500 && f.max <= 2100;
// A cell's value for comparing cells: numbers by value ('5', ' 5' and 5 are
// one value), anything else as text.
const valueKey = v => (typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v)) ? String(Number(v)) : cellKey(v));

/** Whether rows[c] is one value within each group of rows[g] (rows missing either are skipped). */
function constantWithin(rows, c, g) {
    const seen = new Map();
    for (const r of rows) {
        if (!present(r[c]) || !present(r[g])) continue;
        const k = valueKey(r[g]), v = valueKey(r[c]);
        if (seen.has(k) && seen.get(k) !== v) return false;
        seen.set(k, v);
    }
    return true;
}

/** Whether column `l` renames column `p` one-to-one (month names beside month numbers). */
function renames(rows, p, l) {
    const fwd = new Map(), back = new Map();
    for (const r of rows) {
        if (!present(r[p]) || !present(r[l])) continue;
        const a = valueKey(r[p]), b = valueKey(r[l]);
        if ((fwd.has(a) && fwd.get(a) !== b) || (back.has(b) && back.get(b) !== a)) return false;
        fwd.set(a, b);
        back.set(b, a);
    }
    return fwd.size > 0;
}

// The calendar's own names for a within-year position: month names or their
// abbreviations, weekday names or theirs, and the quarter labels Q1–Q4.
const CALENDAR_NAMES = [
    /^(?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)\.?$|^(?:january|february|march|april|june|july|august|september|october|november|december)$/i,
    /^(?:mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)\.?$|^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)$/i,
    /^q ?[1-4]$/i,
];

/** Whether every present value of rows[c] is a calendar name from ONE of the vocabularies. */
function calendarNames(rows, c) {
    return CALENDAR_NAMES.some(re => {
        let n = 0;
        for (const r of rows) {
            if (!present(r[c])) continue;
            if (typeof r[c] !== 'string' || !re.test(r[c].trim())) return false;
            n++;
        }
        return n > 0;
    });
}

/**
 * Whether `f` is a within-year position of the rows grouped by year: named
 * as one, present in 90% of the rows, with whole numbers inside one of its
 * word's ranges, UNIQUE within every year, and SHARED by the years (at least
 * half of every year's values fall inside the fullest year's span, so a
 * count running on across the years is not one). A missing cell is no value.
 */
function isPosition(years, f) {
    const word = positionWord(f.name);
    if (!word) return false;
    const perYear = [];
    let rows = 0;
    for (const rs of years) {
        rows += rs.length;
        const vs = [];
        for (const r of rs) {
            if (!present(r[f.name])) continue;
            const v = Number(r[f.name]);
            if (!Number.isInteger(v)) return false;
            vs.push(v);
        }
        if (new Set(vs).size !== vs.length) return false;
        perYear.push(vs);
    }
    const all = perYear.flat();
    if (all.length < 0.9 * rows || !POSITION_RANGES[word].some(([lo, hi]) => all.every(v => v >= lo && v <= hi))) return false;
    const fullest = perYear.reduce((a, vs) => (vs.length > a.length ? vs : a), []);
    const lo = Math.min(...fullest), hi = Math.max(...fullest);
    return perYear.every(vs => vs.filter(v => v >= lo && v <= hi).length * 2 >= vs.length);
}

/**
 * The year-over-year reading of the rows, { position, label, years }, or
 * null. `year` is the first yearish column. The rows must hold
 *   - the YEAR in 90% of the rows: whole numbers 1500..2100 wherever
 *     present, 2–12 distinct years counted over every row BY VALUE ('2021'
 *     and '2021 ' are one year), and 3+ rows a year on average;
 *   - exactly one numeric column named as a within-year POSITION
 *     (positionWord), and it qualifies (isPosition);
 *   - MEASURES to plot along it: numeric, not a second year, not named as an
 *     identifier, and none constant within the groups of another column
 *     (the year, another measure): a key's attribute (a team number, a FIPS
 *     code) or a per-year figure (a target, a total, a constant) means
 *     keyed data;
 *   - and nothing else, save an all-empty column and one LABEL of the
 *     position: a categorical of calendar names (calendarNames: month or
 *     weekday names, Q1–Q4) that renames it one-to-one (month names beside
 *     month numbers).
 * Any other categorical, boolean or text-id column means a panel (a team,
 * a state or a player measured each year) or keyed data — even one that
 * renames the position one-to-one: a survey question beside its number `q`
 * is the entity and `q` its attribute, and so is a team beside its fixed
 * weekday `day`.
 */
function yearOverYear(rows, fields, year) {
    const byYear = new Map();
    for (const r of rows) {
        if (!present(r[year.name])) continue;
        const y = Number(r[year.name]);
        if (!Number.isInteger(y) || y < 1500 || y > 2100) return null;
        if (!byYear.has(y)) byYear.set(y, []);
        byYear.get(y).push(r);
    }
    const years = [...byYear.values()];
    const yearRows = years.reduce((s, rs) => s + rs.length, 0);
    if (years.length < 2 || years.length > 12 || yearRows < 3 * years.length || yearRows < 0.9 * rows.length) return null;

    const others = fields.filter(f => f !== year);
    const named = others.filter(f => f.kind === 'numeric' && positionWord(f.name));
    if (named.length !== 1 || !isPosition(years, named[0])) return null;
    const position = named[0];

    let label = null;
    const measures = [];
    for (const f of others) {
        if (f === position || f.kind === 'empty') continue;
        if (idNamed(f.name)) return null;
        // A year-valued column not named as one, with more values than a
        // table has years (kcal 1501..2092), is a measure that happens to fall
        // in the year range.
        if (f.kind === 'numeric' && (!yearish(f) || (!YEAR_NAME.test(f.name) && f.distinct > 12))) measures.push(f);
        else if (f.kind === 'categorical' && !label && calendarNames(rows, f.name) && renames(rows, position.name, f.name)) label = f;
        else return null;
    }
    if (measures.length === 0) return null;
    // The position (and its label) are exempt: a measure that repeats at a
    // position every year is still plotted along it.
    const keys = fields.filter(g => g !== position && g !== label && groupsRows(rows, g.name));
    if (measures.some(m => keys.some(g => g !== m && constantWithin(rows, m.name, g.name)))) return null;
    return { position, label, years: years.length };
}

function buildSignature(rows, fields) {
    const byKind = (k) => fields.filter(f => f.kind === k);
    // A date that is the same in every row (a load or export stamp) is
    // metadata about the file, not the rows' time axis.
    let temporal = byKind('temporal').filter(f => !(f.distinct === 1 && rows.length >= 3));
    let measures = byKind('numeric');
    const dimensions = byKind('categorical').concat(byKind('boolean'));
    const idFields = byKind('id');

    // A constant column (one value in every row) says nothing to plot.
    if (rows.length >= 3) measures = measures.filter(f => !(f.distinct === 1 && !yearish(f)));

    // A numeric CODE (a zip, a SKU, an area code) names a place or a thing:
    // it is a text dimension, never a measure.
    for (const f of measures.filter(f => f.allInt && CODE_NAME.test(f.name))) {
        measures = measures.filter(m => m !== f);
        dimensions.push({ ...f, kind: 'categorical', code: true });
    }

    // An identifier is not a measure (isIdentifier: named as one AND valued
    // as one): it labels rows, and plotted it is a meaningless line or axis.
    // A year held under such a name (yearID) stays — it is the time axis.
    measures = measures.filter(f => !isIdentifier(rows, f, fields));

    // A year DERIVED from a real date field (the same year in nearly every
    // row) is not a measure: the date already carries it.
    if (temporal.length > 0) {
        const t0 = temporal[0];
        const yearOf = v => {
            const ms = timeOf(v, t0);
            if (!Number.isFinite(ms)) return [];
            const d = new Date(ms);
            return [d.getUTCFullYear(), d.getFullYear()];
        };
        const derived = f => {
            let hit = 0, seen = 0;
            for (const r of rows) {
                const y = Number(r[f.name]), tv = r[t0.name];
                if (tv === null || tv === undefined || tv === '' || !Number.isFinite(y)) continue;
                seen++;
                if (yearOf(tv).includes(y)) hit++;
            }
            return seen > 0 && hit / seen >= 0.9;
        };
        measures = measures.filter(f => !(yearish(f) && derived(f)));
        // A month / quarter / week / day column that is the date's own
        // month (quarter, …) is a part of the date, not a measure.
        const partOf = (f, unit) => {
            let hit = 0, seen = 0;
            for (const r of rows) {
                const v = numberOf(r[f.name]), ms = timeOf(r[t0.name], t0);
                if (v === null || !Number.isFinite(ms)) continue;
                seen++;
                const d = new Date(ms);
                const want = unit === 'month' ? d.getUTCMonth() + 1 : unit === 'quarter' ? Math.floor(d.getUTCMonth() / 3) + 1
                    : unit === 'day' ? d.getUTCDate() : unit === 'week' ? Math.floor((ms - Date.UTC(d.getUTCFullYear(), 0, 1)) / (7 * DAY_MS)) + 1 : null;
                if (want !== null && (v === want || v === want - 1)) hit++;
            }
            return seen > 0 && hit / seen >= 0.9;
        };
        measures = measures.filter(f => { const u = UNIT_OF[positionWord(f.name)]; return !(u && f.allInt && partOf(f, u)); });
        // A column NAMED as a year beside a real date (a load year, a
        // reporting year) labels the rows; it is never a quantity to plot.
        measures = measures.filter(f => !(yearish(f) && YEAR_NAME.test(f.name)));
    }

    // Year-over-year rows (yearOverYear says what counts): the year becomes
    // a GROUPING dimension, not the time axis, the within-year position the
    // time axis (a stand-in, like a year column below) and each year a
    // series. Two years are enough here (this year against last is the
    // commonest comparison), although a two-point year column is too short
    // to stand in as a time axis. The years are counted over EVERY row, not
    // the profile's sample: a file sorted by year shows its first 1,000 rows
    // only a few of its years.
    let yearGroup = null;
    if (temporal.length === 0) {
        const candidate = measures.find(f => yearish(f) && YEAR_NAME.test(f.name)) || measures.find(yearish);
        const yoy = candidate && yearOverYear(rows, fields, candidate);
        if (yoy) {
            yearGroup = { ...candidate, kind: 'categorical', yearGroup: true, distinct: yoy.years };
            dimensions.push(yearGroup);
            measures = measures.filter(f => f !== candidate && f !== yoy.position);
            temporal = [{ ...yoy.position, kind: 'temporal', positionStandin: true }];
        }
    }

    // A year column holding exactly TWO years, beside something that names
    // the rows (a product, a team), is a pair of periods: this year against
    // last. It is the time axis of a two-point change (Slope / Dumbbell),
    // never a measure plotted against the other measure.
    if (temporal.length === 0 && (dimensions.length > 0 || idFields.length > 0)) {
        const two = measures.find(f => yearish(f) && f.distinct === 2 && YEAR_NAME.test(f.name)) || measures.find(f => yearish(f) && f.distinct === 2);
        if (two) {
            temporal = [{ ...two, kind: 'temporal', yearStandin: true, periods: 2 }];
            measures = measures.filter(f => f !== two);
        }
    }

    // A year-like numeric stands in as the temporal axis when no real one exists.
    if (temporal.length === 0) {
        const named = fields.some(f => f.kind === 'numeric' && yearish(f) && YEAR_NAME.test(f.name));
        // An identifier in the year range (playerID 1501..1540) is never a year.
        const year = measures.find(f => f.yearLike && YEAR_NAME.test(f.name)) || (!named && measures.find(f => f.yearLike && !idNamed(f.name)));
        if (year) {
            temporal = [{ ...year, kind: 'temporal', yearStandin: true }];
            measures = measures.filter(f => f !== year);
        }
    }

    // A rank is the last measure to plot when a quantity is beside it.
    measures.sort((a, b) => (/(^|_)rank(ing)?s?($|_)/i.test(a.name) ? 1 : 0) - (/(^|_)rank(ing)?s?($|_)/i.test(b.name) ? 1 : 0));

    // Same-unit measure pairs (before/after, start/end, low/high, 2023/2024):
    // name patterns, or a year-pair of column names, with overlapping ranges.
    let pair = null;
    for (let i = 0; i < measures.length && !pair; i++) {
        for (let j = 0; j < measures.length && !pair; j++) {
            if (i === j) continue;
            const [a, b] = [measures[i], measures[j]];
            const named = PAIR_PATTERNS.some(([ra, rb]) => ra.test(a.name) && rb.test(b.name));
            const years = /^\d{4}$/.test(a.name) && /^\d{4}$/.test(b.name) && +a.name < +b.name;
            if (named || years) pair = [a, b];
        }
    }
    if (!pair && measures.length === 2) {
        // Range overlap as a weak same-unit proxy (never for named mismatches).
        const [a, b] = measures;
        const lo = Math.max(a.min, b.min), hi = Math.min(a.max, b.max);
        const span = Math.max(a.max, b.max) - Math.min(a.min, b.min);
        if (span > 0 && (hi - lo) / span > 0.5) pair = null; // note only — do not assert pairing
    }

    // One row per unique string + a single measure IS a category axis (teams →
    // wins): the id/categorical distinction collapses, so promote the id field
    // to the grouping dimension when it's the only candidate.
    let nameField = idFields[0] || null;
    if (dimensions.length === 0 && temporal.length === 0 && measures.length === 1 && nameField &&
        nameField.distinct >= nameField.count * 0.98) {
        dimensions.push({ ...nameField, kind: 'categorical', promoted: true });
        nameField = idFields[1] || null;
    }

    // Year-over-year rows group by the year (the only other dimension they
    // may hold is the position's label); otherwise the dimension with the
    // fewest values groups.
    const primaryDim = yearGroup || dimensions.slice().sort((a, b) => a.distinct - b.distinct)[0] || null;
    const rowsPerGroup = primaryDim ? rows.length / primaryDim.distinct : rows.length;
    const t = temporal[0] || null;
    // Daily = the median gap is about one day; sub-daily (hourly) data must
    // NOT read as daily, or Calendar would aggregate-by-accident.
    const daily = !!(t && !t.yearStandin && !t.positionStandin && t.medianGapMs !== null &&
        t.medianGapMs >= 0.5 * DAY_MS && t.medianGapMs <= 1.5 * DAY_MS);

    return {
        rowCount: rows.length,
        temporal, measures, dimensions, idFields,
        nameField,
        primaryDim, rowsPerGroup, pair, daily,
    };
}

// ---------------------------------------------------------------------------
// 2b. Semantics: what kind of measure, which dimensions are ordered, which
//     shapes (funnel, hierarchy, period pair) the rows hold.
// ---------------------------------------------------------------------------

const tokens = name => String(name).replace(/([a-z])([A-Z])/g, '$1_$2').toLowerCase().split(/[^a-z0-9%]+/).filter(Boolean);
// An AVERAGE is a ratio whatever its range (an AOV of 45.20, a GDP per capita).
const AVG_TOKENS = new Set(['avg', 'average', 'mean', 'median', 'aov', 'per', 'ppg', 'era', 'whip', 'obp', 'slg', 'ops', 'ba', 'arpu']);
// A RATE is a ratio when its values look like one (0–1, or a percent).
const RATE_TOKENS = new Set(['rate', 'ratio', 'pct', 'percent', 'percentage', 'share', 'margin', 'cvr', 'ctr', '%', 'yield', 'roi', 'roas']);
// A LEVEL is a state, not a quantity: its typical value is the mean, never a sum.
const LEVEL_TOKENS = new Set(['price', 'temp', 'temperature', 'close', 'open', 'high', 'low', 'balance', 'level', 'score',
    'rating', 'stars', 'velo', 'velocity', 'speed', 'age', 'weight', 'height', 'duration', 'latency', 'salary', 'wage',
    'elevation', 'pressure', 'humidity', 'index', 'nps', 'rank', 'days', 'minutes', 'seconds', 'lead', 'tenure', 'mph', 'angle', 'distance']);
// VOLUME measures sum to a meaningful whole (revenue by channel adds up to revenue).
const VOLUME_TOKENS = new Set(['revenue', 'sales', 'units', 'orders', 'sessions', 'visits', 'views', 'pageviews', 'clicks',
    'impressions', 'signups', 'users', 'customers', 'count', 'n', 'total', 'amount', 'spend', 'cost', 'costs', 'budget', 'actual',
    'profit', 'income', 'expense', 'expenses', 'volume', 'quantity', 'qty', 'gmv', 'mrr', 'arr', 'bookings', 'tickets', 'population',
    'traffic', 'downloads', 'installs', 'conversions', 'leads', 'deals', 'fans', 'attendance', 'headcount', 'employees', 'payroll',
    'visitors', 'shipments', 'transactions', 'subscribers', 'purchases', 'trials']);

/**
 * The measure's kind: 'ratio' (an average, rate or percent — never summed
 * or averaged across rows; only sum(numerator) / sum(denominator) is right),
 * 'level' (a state — its group summary is the mean) or 'additive' (a
 * quantity — groups sum). Names nominate; values decide where they can.
 */
function measureKind(f) {
    const tk = tokens(f.name);
    const has = set => tk.some(t => set.has(t));
    const unitRate = f.min >= 0 && f.max <= 1 && !f.allInt;
    if (has(AVG_TOKENS)) return 'ratio';
    if (f.unit === '%') return 'ratio';
    if (has(RATE_TOKENS) && (unitRate || (f.min >= 0 && f.max <= 100))) return 'ratio';
    if (has(VOLUME_TOKENS)) return 'additive';
    if (has(LEVEL_TOKENS)) return 'level';
    if (unitRate) return 'ratio';
    return 'additive';
}
// Only named volumes: a competitor's wins or a player's runs add up, but
// the teams' total is not a whole anyone reads as parts.
const COUNT_TOKENS = new Set(['hr', 'runs', 'hits', 'goals', 'wins', 'losses', 'points', 'events', 'incidents', 'errors', 'bugs', 'count', 'n', 'number', 'num', 'cases', 'deaths', 'births', 'arrivals', 'calls', 'alerts', 'outages']);
const countNamed = f => tokens(f.name).some(t => VOLUME_TOKENS.has(t) || COUNT_TOKENS.has(t));
const isVolume = f => tokens(f.name).some(t => VOLUME_TOKENS.has(t));
// Stocks: a level at a point in time (recurring revenue, a balance, a
// headcount) — they add up across categories but never across periods, so
// they are never drawn as per-period columns.
const STOCK_TOKENS = new Set(['mrr', 'arr', 'balance', 'inventory', 'stock', 'headcount', 'backlog', 'subscribers', 'members', 'population', 'aum', 'outstanding']);
const isStock = f => tokens(f.name).some(t => STOCK_TOKENS.has(t));
/** A flow: an amount that happens IN a period (orders, revenue, signups) — summable across periods. */
const isFlow = f => (isVolume(f) || countNamed(f)) && !isStock(f);

/** For a ratio measure, two additive columns whose quotient it is (revenue / orders = aov). */
function findParts(rows, r, measures) {
    const cands = measures.filter(m => m !== r && m.kind === 'numeric' && measureKind(m) === 'additive');
    for (const a of cands) for (const b of cands) {
        if (a === b) continue;
        for (const scale of [1, 100]) {
            let hit = 0, seen = 0;
            for (const row of rows) {
                const va = numberOf(row[a.name]), vb = numberOf(row[b.name]), vr = numberOf(row[r.name]);
                if (va === null || vb === null || vr === null || vb === 0) continue;
                seen++;
                if (Math.abs(scale * va / vb - vr) <= 0.02 * Math.max(Math.abs(vr), 1e-9) + 0.005) hit++;
            }
            if (seen >= 3 && hit / seen >= 0.9) return { num: a, den: b, scale };
        }
    }
    return null;
}

const ORDINAL_TOKENS = new Set(['inning', 'round', 'level', 'tier', 'grade', 'rank', 'rating', 'stars', 'stage', 'step',
    'phase', 'size', 'bucket', 'bin', 'band', 'decile', 'quintile', 'quartile', 'cohort', 'priority', 'floor', 'lane',
    'num', 'no', 'number', 'class', 'period', 'set', 'game', 'lap', 'hole', 'chapter', 'version', 'age']);
/** A whole-number column with few values that may be a CATEGORY axis (inning 1–9, tier 1–4). */
function ordinalReading(f, rowCount) {
    if (f.kind !== 'numeric' || !f.allInt || yearish(f) || f.distinct < 2 || f.distinct > 12) return null;
    if (rowCount < 2 * f.distinct || f.min < 0 || f.max > 100) return null;
    const named = tokens(f.name).some(t => ORDINAL_TOKENS.has(t));
    const dense = f.max - f.min + 1 <= f.distinct * 1.5;
    if (!named && !dense) return null;
    return { named, dense };
}

const STAGE_NAME = /(^|_)(stage|step|phase|funnel)s?($|_)/i;
const FUNNEL_WORDS = /\b(visit|visits|visitor|view|viewed|session|landing|lead|leads|signup|sign[- ]?up|register|registered|account|trial|trials|activate|activated|cart|checkout|purchase|purchased|paid|order|ordered|subscribe|subscribed|opportunit|proposal|won|closed|qualified|demo|install|onboard|engaged|retained|converted)/i;
const RANGE_BIN = /^\s*(?:[<>≤≥]\s*)?[$€£]?\d+(?:\.\d+)?\s*(?:[kKmM%])?\s*(?:(?:[-–]|to)\s*[$€£]?\d+(?:\.\d+)?\s*(?:[kKmM%])?|\+)?\s*(?:yrs?|years?|days?|mph|%)?\s*$/i;
const ORDER_NAME = /(^|_)(stage|step|phase|level|tier|grade|size|bucket|bin|band|priority|rank|cohort|age_group|agegroup|quarter|month|weekday|day|period|round|inning|half)s?($|_)/i;

/** Whether a text dimension's values have an ORDER (time, sequence, magnitude): never re-rank, never a donut. */
function orderedDimension(rows, f) {
    if (f.yearGroup) return true;
    if (f.kind !== 'categorical' && f.kind !== 'id') return false;
    if (calendarNames(rows, f.name)) return true;
    if (STAGE_NAME.test(f.name) || ORDER_NAME.test(f.name)) return true;
    const vals = [...new Set(rows.map(r => r[f.name]).filter(present).map(String))];
    if (vals.length >= 2 && vals.every(v => RANGE_BIN.test(v))) return true;
    if (vals.length >= 2 && vals.length <= 60 && vals.every(v => /^(?:FY|H|Q|W|Tier|Level|Stage|Step|Phase|Grade|Week|Day|Month|Round|Period)\s?-?\d+$/i.test(v.trim()))) return true;
    return false;
}

/** Funnel stages: an ordered stage column, one row each, a measure that never grows along the source order. */
function funnelReading(rows, dim, m) {
    if (!dim || !m || rows.length < 3 || rows.length > 12 || dim.distinct !== rows.length) return null;
    const stageLike = STAGE_NAME.test(dim.name) ||
        rows.filter(r => FUNNEL_WORDS.test(String(r[dim.name]))).length >= 0.6 * rows.length;
    if (!stageLike) return null;
    const vs = rows.map(r => numberOf(r[m.name]));
    if (vs.some(v => v === null || v < 0)) return null;
    for (let i = 1; i < vs.length; i++) if (vs[i] > vs[i - 1]) return null;
    return vs[0] > vs[vs.length - 1] ? { stages: rows.length } : null;
}

/** Two text columns where every child sits under exactly one parent (section → page). */
function hierarchyReading(rows, texts) {
    for (const parent of texts) for (const child of texts) {
        if (parent === child || parent.distinct < 2 || parent.distinct >= child.distinct || child.distinct > 100 || idNamed(child.name)) continue;
        const up = new Map();
        let ok = true;
        for (const r of rows) {
            const c = r[child.name], p = r[parent.name];
            if (!present(c) || !present(p)) continue;
            if (up.has(c) && up.get(c) !== p) { ok = false; break; }
            up.set(c, p);
        }
        if (ok && up.size >= 4 && child.distinct > parent.distinct) return { parent, child };
    }
    return null;
}

/**
 * A two-value text column beside an entity, each entity once per value
 * (H1/H2, pre/post, FY24/FY25): a pair of periods, the slope signature.
 */
function periodPairReading(rows, texts) {
    for (const per of texts) {
        if (per.distinct !== 2) continue;
        for (const ent of texts) {
            if (ent === per || ent.distinct < 2) continue;
            const seen = new Map();
            for (const r of rows) {
                const e = r[ent.name], p = r[per.name];
                if (!present(e) || !present(p)) continue;
                if (!seen.has(e)) seen.set(e, new Map());
                const m = seen.get(e);
                m.set(p, (m.get(p) || 0) + 1);
            }
            const good = [...seen.values()].filter(m => m.size === 2 && [...m.values()].every(c => c === 1)).length;
            if (seen.size >= 2 && good >= 0.8 * seen.size) {
                const values = [...new Set(rows.map(r => r[per.name]).filter(present))].map(String)
                    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
                return { period: per, entity: ent, values };
            }
        }
    }
    return null;
}

// ---- An estimate and its bounds ---------------------------------------------
// A lower and an upper bound named as such (ci_low / ci_high, lower / upper,
// revenue_low / revenue_high) with an estimate between them in most rows: a
// point estimate with its interval (per named row) or an actual inside its
// expected band (over time). min / max name a range, not bounds.
const LOW_TOKENS = new Set(['low', 'lower', 'lo', 'lcl', 'lb']);
const HIGH_TOKENS = new Set(['high', 'upper', 'hi', 'ucl', 'ub']);
const BOUND_WORDS = new Set(['ci', 'bound', 'bounds', 'interval', 'conf', 'band']);
// Bound names that only an interval uses (low / high also name a day's range).
const CI_TOKENS = new Set(['ci', 'lower', 'upper', 'lcl', 'ucl', 'lb', 'ub', 'bound', 'interval', 'conf']);
const ESTIMATE_TOKENS = new Set(['estimate', 'est', 'point', 'effect', 'lift', 'forecast', 'predicted', 'prediction', 'observed', 'actual', 'fitted']);
// What happened, as opposed to what was expected: beside both, the band's line is the actual.
const ACTUAL_TOKENS = new Set(['actual', 'actuals', 'observed', 'measured', 'realized']);
// A forecast column beside the actual: the band chart draws it dashed (forecastAccessor).
const FORECAST_TOKENS = new Set(['forecast', 'predicted', 'prediction', 'projected', 'projection', 'expected', 'fitted', 'plan', 'planned']);
const LOOSE_ESTIMATE_TOKENS = new Set(['value', 'mean', 'median', 'avg', 'average', 'rate', 'score', 'expected']);

/** { estimate, low, high, strong } — strong when the names can only mean an interval — or null. */
function boundsReading(rows, measures) {
    const stem = (f, side) => tokens(f.name).filter(t => !side.has(t) && !BOUND_WORDS.has(t)).join('_');
    for (const lo of measures) {
        if (!tokens(lo.name).some(t => LOW_TOKENS.has(t))) continue;
        for (const hi of measures) {
            if (hi === lo || !tokens(hi.name).some(t => HIGH_TOKENS.has(t))) continue;
            const s = stem(lo, LOW_TOKENS);
            if (s !== stem(hi, HIGH_TOKENS)) continue;
            const others = measures.filter(m => m !== lo && m !== hi);
            const est = others.find(m => s && tokens(m.name).join('_') === s) ||
                others.find(m => tokens(m.name).some(t => ACTUAL_TOKENS.has(t))) ||
                others.find(m => tokens(m.name).some(t => ESTIMATE_TOKENS.has(t))) ||
                others.find(m => tokens(m.name).some(t => LOOSE_ESTIMATE_TOKENS.has(t))) ||
                (others.length === 1 ? others[0] : null);
            if (!est) continue;
            let seen = 0, ordered = 0, inside = 0;
            for (const r of rows) {
                const l = numberOf(r[lo.name]), h = numberOf(r[hi.name]), e = numberOf(r[est.name]);
                if (l === null || h === null || e === null) continue;
                seen++;
                if (l <= h) ordered++;
                if (e >= l && e <= h) inside++;
            }
            if (seen < 2 || ordered / seen < 0.95 || inside / seen < 0.6) continue;
            const strong = tokens(lo.name).concat(tokens(hi.name)).some(t => CI_TOKENS.has(t)) ||
                tokens(est.name).some(t => ESTIMATE_TOKENS.has(t)) || (s !== '' && tokens(est.name).join('_') === s);
            return { estimate: est, low: lo, high: hi, strong };
        }
    }
    return null;
}

// ---- An agreement (Likert) scale ----------------------------------------------
// Columns that name the points of one ordinal response scale (strongly
// disagree … strongly agree, very dissatisfied … very satisfied, or the
// digits 1..5 / 1..7), one row per question: each row a distribution over
// the scale, centered on neutral.
const SCALE_NEUTRAL = /\b(neutral|neither|undecided|no opinion|indifferent|unsure|mixed)\b/;
const SCALE_NEG = /\b(disagree|dissatisfied|unsatisfied|unlikely|oppose|unfavou?rable|unhappy|unimportant|poor|bad|negative|worse)\b/;
const SCALE_POS = /\b(agree|satisfied|likely|support|favou?rable|happy|important|good|excellent|positive|better)\b/;
const SCALE_STRONG = /\b(strongly|very|extremely|completely|totally|highly)\b/;
const SCALE_WEAK = /\b(somewhat|slightly|mostly|moderately|rather|tend to)\b/;
const phraseOf = name => String(name).replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

/** { keys (negative → positive), labels, named } over the measures that form one response scale, or null. */
function scaleReading(measures) {
    const pole = m => {
        const w = phraseOf(m.name);
        if (SCALE_NEUTRAL.test(w)) return 0;
        const sign = SCALE_NEG.test(w) ? -1 : SCALE_POS.test(w) ? 1 : null;
        if (sign === null) return null;
        return sign * (SCALE_STRONG.test(w) ? 2 : SCALE_WEAK.test(w) ? 0.5 : 1);
    };
    const nonNeg = m => m.min >= 0;
    const named = measures.filter(nonNeg).map(m => ({ m, p: pole(m) })).filter(x => x.p !== null);
    const ps = new Set(named.map(x => x.p));
    if (named.length >= 3 && named.length <= 7 && ps.size === named.length && [...ps].some(p => p < 0) && [...ps].some(p => p > 0)) {
        const keys = named.sort((a, b) => a.p - b.p).map(x => x.m.name);
        return { keys, named: true, measures: named.map(x => x.m) };
    }
    // The digits of a 4- to 7-point scale as column names ('1' … '5').
    const digits = measures.filter(m => nonNeg(m) && /^\d$/.test(String(m.name).trim()))
        .sort((a, b) => Number(a.name) - Number(b.name));
    const ds = digits.map(m => Number(m.name));
    if (digits.length >= 4 && digits.length <= 7 && (ds[0] === 0 || ds[0] === 1) && ds.every((d, i) => d === ds[0] + i)) {
        return { keys: digits.map(m => m.name), named: false, measures: digits };
    }
    return null;
}

/** A whole number that only counts the rows in time order (day 0..59 beside the date): an index, not a measure. */
function isRowIndex(sortedRows, m) {
    if (!m.allInt || m.distinct !== m.count || m.max - m.min + 1 !== m.count) return false;
    let prev = -Infinity;
    for (const r of sortedRows) {
        const v = numberOf(r[m.name]);
        if (v === null) continue;
        if (v <= prev) return false;
        prev = v;
    }
    return true;
}

/**
 * A whole-number measure that is a RANK by structure: within every period
 * the entities' values are 1..k, each once (k = the entities ranked then).
 * Needs 3+ periods and 3+ entities, so counts that happen to be small never
 * read as one, and some entity's value must change: a number no entity ever
 * changes (a region number, a question's position) labels the entity.
 */
function ranksByStructure(rows, t, dim, m) {
    if (!t || !dim || !m || !m.allInt || m.min !== 1 || m.max > 40 || dim.distinct < 3) return false;
    const byPeriod = new Map(), byEntity = new Map();
    for (const r of rows) {
        const p = keyOf(r, t), v = numberOf(r[m.name]), e = r[dim.name];
        if (p === null || v === null || !present(e)) continue;
        if (!byPeriod.has(p)) byPeriod.set(p, []);
        byPeriod.get(p).push(v);
        if (!byEntity.has(e)) byEntity.set(e, new Set());
        byEntity.get(e).add(v);
    }
    if (byPeriod.size < 3 || ![...byEntity.values()].some(vs => vs.size > 1)) return false;
    for (const vs of byPeriod.values()) {
        if (vs.length < 3) return false;
        const sorted = vs.slice().sort((a, b) => a - b);
        if (sorted.some((v, i) => v !== i + 1)) return false;
    }
    return true;
}

function enrichSignature(rows, fields, sig) {
    for (const m of sig.measures) {
        m.measureKind = measureKind(m);
        if (m.measureKind === 'ratio') m.parts = findParts(rows, m, sig.measures);
        m.ordinal = ordinalReading(m, rows.length);
    }
    for (const d of sig.dimensions.concat(sig.idFields)) d.ordered = orderedDimension(rows, d);
    const texts = sig.dimensions.filter(d => d.kind === 'categorical' && !d.yearGroup).concat(sig.idFields);
    sig.hierarchy = sig.temporal.length === 0 ? hierarchyReading(rows, texts) : null;
    sig.periodPair = sig.temporal.length === 0 ? periodPairReading(rows, texts) : null;
    // A small table whose one text column names every row (5 teams): with
    // two or more measures that column is the rows' NAME, not a color group.
    if (!sig.nameField && sig.temporal.length === 0 && sig.measures.length >= 2) {
        const uniq = sig.dimensions.find(d => d.kind === 'categorical' && d.unique && d.count >= 2);
        if (uniq) {
            sig.nameField = uniq;
            sig.dimensions = sig.dimensions.filter(d => d !== uniq);
            sig.primaryDim = sig.dimensions.slice().sort((a, b) => a.distinct - b.distinct)[0] || null;
            sig.rowsPerGroup = sig.primaryDim ? rows.length / sig.primaryDim.distinct : rows.length;
        }
    }
    const t = sig.temporal[0];
    sig.xRepeats = !!(t && !sig.primaryDim && t.distinct < rows.filter(r => present(r[t.name])).length);
    sig.bounds = sig.measures.length >= 3 ? boundsReading(rows, sig.measures) : null;
    sig.scale = sig.measures.length >= 3 && !t ? scaleReading(sig.measures) : null;
    return sig;
}

// ---------------------------------------------------------------------------
// Helpers: transforms (pure — inputs never mutated) + cardinality scoring
// ---------------------------------------------------------------------------

/** A cell as the builder sees it: numbers parsed, dates in a builder-readable form, text as is. */
const val = (row, f) => {
    const v = row[f.name];
    if (f.kind === 'temporal') return f.yearStandin || f.positionStandin ? (present(v) ? Number(v) : null) : emitTime(v, f);
    if (f.kind === 'numeric') return numberOf(v, f);
    return v;
};
const keyOf = (row, f) => {
    const v = row[f.name];
    if (f.kind === 'temporal' && (f.yearStandin || f.positionStandin)) return numberOf(v);
    if (f.kind === 'temporal') { const ms = timeOf(v, f); return Number.isFinite(ms) ? ms : null; }
    if (f.kind === 'numeric' || f.yearGroup) { const n = numberOf(v); return n === null ? null : n; }
    return present(v) ? v : null;
};

/** Rows ordered by a field; rows missing it keep their place at the end (a builder drops them, never draws them at 0). */
function sortByField(rows, f) {
    const has = rows.filter(r => keyOf(r, f) !== null).sort((a, b) => keyOf(a, f) - keyOf(b, f));
    return has.concat(rows.filter(r => keyOf(r, f) === null));
}

function groupBy(rows, f) {
    const m = new Map();
    for (const r of rows) {
        const k = f.yearGroup ? keyOf(r, f) : r[f.name];
        if (k === null || k === undefined) continue;
        if (!m.has(k)) m.set(k, []);
        m.get(k).push(r);
    }
    return m;
}

/**
 * How a measure collapses when a key repeats: 'sum' (a quantity), 'mean' (a
 * level), 'ratio' (a rate rebuilt from its numerator and denominator), or
 * null — a rate or average with no parts is never collapsed at all (the mean
 * of averages is wrong whenever the groups differ in size).
 */
function aggregationOf(m) {
    if (m.measureKind === 'ratio') return m.parts ? 'ratio' : null;
    if (m.measureKind === 'level') return 'mean';
    return 'sum';
}

/**
 * One entry per key tuple, in first-seen order. `how` from aggregationOf.
 * A missing value is skipped, never counted as 0 — a key with no value at all
 * stays null. `repeated` says whether any key repeated.
 */
function aggregate(rows, keyFields, m, how) {
    const out = new Map();
    let repeated = false;
    for (const r of rows) {
        const keys = keyFields.map(f => keyOf(r, f));
        if (keys.some(k => k === null)) continue;
        const k = JSON.stringify(keys);
        if (out.has(k)) repeated = true;
        else out.set(k, { keys: keyFields.map(f => (f.kind === 'temporal' ? val(r, f) : r[f.name])), sum: 0, n: 0, num: 0, den: 0 });
        const e = out.get(k);
        if (how === 'ratio') {
            const a = numberOf(r[m.parts.num.name]), b = numberOf(r[m.parts.den.name]);
            if (a !== null && b !== null) { e.num += a; e.den += b; e.n++; }
        } else if (how === 'count') {
            e.n++;
        } else {
            const v = numberOf(r[m.name]);
            if (v !== null) { e.sum += v; e.n++; }
        }
    }
    const rowsOut = [...out.values()].map(e => {
        let value = null;
        if (how === 'count') value = e.n;
        else if (how === 'ratio') value = e.den ? (m.parts.scale * e.num) / e.den : null;
        else if (e.n) value = how === 'mean' ? e.sum / e.n : e.sum;
        return { keys: e.keys, value, n: e.n };
    });
    return { rows: rowsOut, repeated };
}

const AGG_WORD = { sum: 'summed', mean: 'averaged', ratio: 'recomputed', count: 'counted' };
function aggText(how, m, keyText, nIn, nOut, unit = '') {
    const counts = `(${nIn} rows → ${nOut}${unit ? ` ${unit}` : ''})`;
    if (how === 'ratio') return `${m.name} recomputed per ${keyText} as ${m.parts.scale === 100 ? '100 × ' : ''}sum(${m.parts.num.name}) / sum(${m.parts.den.name}) ${counts}`;
    return `${AGG_WORD[how]} ${m.name} per ${keyText} ${counts}`;
}

/** The caveat every summing candidate carries: a sum is not always the answer. */
function sumCaveat(keyText, measure) {
    return `${keyText} repeats across rows, so ${measure.name} is SUMMED per ${keyText} — for a rate or an average, pass its numerator and denominator (or aggregate first with data.rollup)`;
}

function fitRange(n, range) {
    if (!range) return 0;
    const [min, max] = range;
    if ((min === null || n >= min) && (max === null || n <= max)) return 1;
    return -1;
}

function fmtRange([min, max]) {
    if (min !== null && max !== null) return `${min}–${max}`;
    if (min !== null) return `${min}+`;
    return `up to ${max}`;
}

const metaOf = b => BUILDER_METADATA[b] || {};
const cardOf = b => metaOf(b).cardinality || {};

/** Adjust a candidate by the builder's metadata cardinality ranges; returns the adjustment. */
function applyCardinality(cand, dims) {
    const card = cardOf(cand.metaBuilder || cand.builder);
    let adj = 0;
    for (const [dim, n] of Object.entries(dims)) {
        const fit = fitRange(n, card[dim]);
        if (fit === 1) {
            adj += 0.03;
            cand.why.push(`${n} ${dim} fits the comfortable ${fmtRange(card[dim])}`);
        } else if (fit === -1) {
            adj -= 0.25;
            cand.caveats.push(`${n} ${dim} is outside the comfortable ${fmtRange(card[dim])} — reshape (data.topN / data.rollup / facet) or pick another form`);
        }
    }
    return adj;
}

function rangeOverlap(a, b) {
    const lo = Math.max(a.min, b.min), hi = Math.min(a.max, b.max);
    const span = Math.max(a.max, b.max) - Math.min(a.min, b.min);
    return span > 0 ? Math.max(0, hi - lo) / span : 0;
}

function spanRatio(measures) {
    const spans = measures.map(m => Math.max(Math.abs(m.max), Math.abs(m.min))).filter(s => s > 0);
    return spans.length ? Math.max(...spans) / Math.min(...spans) : 1;
}

/** Measures grouped by scale: each group's spans lie within 10× of each other. */
function scaleGroups(measures) {
    const sorted = measures.slice().sort((a, b) => Math.max(Math.abs(a.max), Math.abs(a.min)) - Math.max(Math.abs(b.max), Math.abs(b.min)));
    const groups = [];
    for (const m of sorted) {
        const s = Math.max(Math.abs(m.max), Math.abs(m.min));
        const g = groups[groups.length - 1];
        if (g && s <= 10 * g.base) g.ms.push(m);
        else groups.push({ base: s || 1, ms: [m] });
    }
    return groups.map(g => g.ms);
}

/**
 * Line y domain: a line encodes POSITION, not length from zero, so a narrow
 * range far from zero zooms in ('padded'); zero stays in for counts and
 * totals that start near it.
 */
const yModeCfg = ms => (lineYMode(ms) === 'padded' ? { yMode: 'padded' } : {});
function lineYMode(ms) {
    const lo = Math.min(...ms.map(m => m.min)), hi = Math.max(...ms.map(m => m.max));
    if (lo <= 0 || hi <= 0) return 'zero';
    return (hi - lo) / hi < 0.5 ? 'padded' : 'zero';
}

/** Whether a builder takes an option (its own key, or a supported universal one) — gates rules on the metadata. */
function accepts(builder, key) {
    const m = metaOf(builder);
    return (m.options || []).includes(key) || (m.universal || {})[key] === 'supported';
}

// ---------------------------------------------------------------------------
// Measure-aware number formats. The library's defaults already shorten big
// numbers (600K axes, 1.24M labels, full-precision tooltips); what it cannot
// know is the unit, so suggest passes formats only for the three it reads off
// the rows: a 0–1 rate (percent), a written percent, a written currency.
// ---------------------------------------------------------------------------

/** Short form, 3 significant digits, trailing zeros trimmed: 1.24M, 600K, 18.2K. */
function shortNumber(v) {
    const a = Math.abs(v);
    for (const [d, sfx] of [[1e12, 'T'], [1e9, 'B'], [1e6, 'M'], [1e3, 'K']]) {
        if (a >= d) return `${Number((v / d).toPrecision(3))}${sfx}`;
    }
    return String(Number(v.toPrecision(3)));
}

const onNumber = fn => v => (typeof v === 'number' && Number.isFinite(v) ? fn(v) : v);

/** { kind, axis, label, tip } formatters for a measure, or null when the defaults already fit. */
function measureFormats(m) {
    if (!m || m.kind !== 'numeric') return null;
    if (m.unit === '%') {
        return { kind: 'a percent', axis: onNumber(v => `${Number(v.toFixed(1))}%`), label: onNumber(v => `${Number(v.toFixed(1))}%`), tip: onNumber(v => `${Number(v.toFixed(2))}%`) };
    }
    if ((m.measureKind || measureKind(m)) === 'ratio' && m.min >= 0 && m.max <= 1 && !m.allInt) {
        const pct = d => onNumber(v => `${Number((v * 100).toFixed(d))}%`);
        return { kind: 'a percent (from a 0–1 rate)', axis: pct(1), label: pct(1), tip: pct(2) };
    }
    if (m.currency && m.unit) {
        const sym = m.unit;
        const sign = v => (v < 0 ? '−' : '');
        const short = onNumber(v => `${sign(v)}${sym}${Math.abs(v) >= 1000 ? shortNumber(Math.abs(v)) : Number(Math.abs(v).toFixed(2)).toLocaleString('en-US')}`);
        return { kind: `${sym} currency`, axis: short, label: short,
            tip: onNumber(v => `${sign(v)}${sym}${Math.abs(v).toLocaleString('en-US', { maximumFractionDigits: 2 })}`) };
    }
    return null;
}

/** The one measure whose formats stand for all of them (same unit), else null. */
function sharedFormatMeasure(ms) {
    const kinds = ms.map(m => (measureFormats(m) || {}).kind || null);
    return kinds.every(k => k && k === kinds[0]) ? ms[0] : null;
}

/** Write a candidate's measure formats into its config (a caller-style key already there wins). */
function applyFormats(cand, fmt) {
    const cfg = cand.config;
    if (!cfg || !fmt) return;
    const b = cand.builder;
    const set = (key, fn) => { if (fn && cfg[key] === undefined && accepts(b, key)) cfg[key] = fn; };
    const notes = [];
    const note = (m, f) => notes.push(`${m.name} as ${f.kind}`);
    const fy = measureFormats(fmt.y), fy2 = measureFormats(fmt.y2), fx = measureFormats(fmt.x), fv = measureFormats(fmt.value);
    if (fy) {
        set('yFormat', fy.axis);
        if (b === 'Bar.createVertical') set('valueFormat', fy.label);
        set('tooltipValueFormat', fy.tip);
        note(fmt.y, fy);
    }
    if (fy2) { set('y2Format', fy2.axis); set('y2ValueFormat', fy2.tip); note(fmt.y2, fy2); }
    if (fx) { set('xFormat', fx.axis); note(fmt.x, fx); }
    if (fv) { set('valueFormat', fv.label); set('tooltipValueFormat', fv.tip); note(fmt.value, fv); }
    if (notes.length) cand.why.push(`formats: ${notes.join(', ')}`);
}

/** A band x value for a time axis: ISO strings stay as written, so date-valued bands get calendar labels. */
const bandValueOf = v => (v instanceof Date ? v.toISOString().slice(0, 10) : String(v));

const DUAL_CAVEAT = "the two axes' alignment is arbitrary — a line crossing the other axis's line (or sitting above it) means nothing; read each measure against its own axis";

/** Estimated share of scatter dots that overlap, on a nominal 560×320 plot. */
function overlapOpacity(n, r = 4) {
    const coverage = (n * Math.PI * r * r) / (560 * 320);
    const share = Math.min(1, coverage * 1.8);           // ≈ share of dots touching a neighbor (uniform cloud)
    const opacity = Math.max(0.3, Math.min(1, 1 - 0.7 * share));
    return { share, opacity: Math.round(opacity * 100) / 100 };
}

const legendFor = keys => (keys.length > 1 ? { legend: true } : {});

// ---------------------------------------------------------------------------
// 3+4. Rules with config synthesis
// ---------------------------------------------------------------------------

/**
 * Each rule pushes candidates; each candidate names the intents it answers
 * and whether it shows the aggregate ('summary') or the rows ('individuals').
 * The trace records every rule's gate for the lab and for agents.
 */
function suggestCandidates(rows, sig, ctx) {
    const out = [];
    const trace = [];
    const push = (builder, base, why, cfg, dims = {}, caveats = [], transform = null, meta = {}) => {
        const cand = {
            builder, score: 0, why: [].concat(why), caveats: [].concat(caveats).filter(Boolean), transform,
            answers: meta.answers || INTENT_OF[builder] || [], show: meta.show || null,
            variants: meta.variants || [], unencoded: meta.unencoded || [], rule: ctx.rule,
            metaBuilder: meta.metaBuilder || null, setup: meta.setup || null, facet: meta.facet || null,
            ...cfg,
        };
        applyFormats(cand, meta.fmt);
        const card = applyCardinality(cand, dims);
        cand.scoreParts = { base, cardinality: Math.round(card * 100) / 100, intent: 0, show: 0, context: 0 };
        out.push(cand);
        return cand;
    };
    const rule = (id, title, gates) => {
        const on = gates.every(([, pass]) => !!pass);
        trace.push({ id, title, on, gates: gates.map(([label, pass]) => ({ label, pass: !!pass })) });
        ctx.rule = id;
        return on;
    };

    const t = sig.temporal[0] || null;
    const M = sig.measures, D = sig.dimensions, n = sig.rowCount;
    const m1 = M[0], m2 = M[1];
    const dim = sig.primaryDim;
    const name = sig.nameField;
    const standin = !!(t && (t.yearStandin || t.positionStandin));
    const tx = r => val(r, t);
    const unusedMeasures = used => M.filter(m => !used.includes(m)).map(m => m.name);

    // --- trend: time + measure(s), no grouping ------------------------------
    if (rule('trend', 'Trend: time + measure, no grouping', [['time axis', t], ['a measure', m1], ['no grouping dimension', !dim], ['no interval pair', sig.temporal.length < 2 || M.length > 0]])) {
        const sorted = sortByField(rows, t);
        // A time axis that repeats with nothing grouping the rows (one row per
        // pitch, per transaction): aggregate per x first, or the line zigzags
        // through every row at every date.
        const trendFor = (m) => {
            if (!sig.xRepeats) return { data: sorted.map(r => ({ ...r, [t.name]: tx(r), [m.name]: val(r, m) })), transform: null };
            const how = aggregationOf(m) || 'mean';
            const agg = aggregate(sorted, [t], m, how);
            return {
                data: agg.rows.map(e => ({ [t.name]: e.keys[0], [m.name]: e.value })),
                transform: aggText(how, m, t.name, n, agg.rows.length),
                how,
            };
        };
        // An actual with its upper and lower bounds: the line inside its
        // expected band. Leads only when the names can mean nothing else
        // (lower / upper, ci_*, an actual or a forecast); a day's high / low
        // around its average is a band too, but Line.createMulti stays first.
        const B = sig.bounds;
        if (B && !sig.xRepeats) {
            const core = [B.estimate, B.low, B.high];
            // A forecast column (beside an actual) is the band's dashed
            // forecast line; when the actual stops and the forecast runs on,
            // the divider marks the handoff.
            const fc = !tokens(B.estimate.name).some(t => FORECAST_TOKENS.has(t))
                ? M.find(m => !core.includes(m) && tokens(m.name).some(t => FORECAST_TOKENS.has(t))) : null;
            // Other measures on the band's scale (disapproval beside approval)
            // ride along as labeled lines; a 0..n row index beside the date
            // is no measure, and a measure on another scale stays out.
            const bandLo = Math.min(B.low.min, B.estimate.min), bandHi = Math.max(B.high.max, B.estimate.max);
            const rest = M.filter(m => !core.includes(m) && m !== fc);
            const span = bandHi - bandLo;
            const extras = rest.filter(m => !isRowIndex(sorted, m) && m.min >= bandLo - span && m.max <= bandHi + span).slice(0, 2);
            const dropped = rest.filter(m => !extras.includes(m));
            const drawn = core.concat(fc ? [fc] : [], extras);
            const bandRows = sorted.map(r => Object.fromEntries([[t.name, tx(r)], ...drawn.map(m => [m.name, val(r, m)])]));
            const cfg = { x: t.name, actualAccessor: B.estimate.name, lowerAccessor: B.low.name, upperAccessor: B.high.name };
            let handoff = null;
            if (fc) {
                cfg.forecastAccessor = fc.name;
                let last = -1;
                bandRows.forEach((r, i) => { if (r[B.estimate.name] !== null && r[B.estimate.name] !== undefined) last = i; });
                const after = bandRows.slice(last + 1).filter(r => r[fc.name] !== null && r[fc.name] !== undefined);
                if (last >= 0 && after.length) { handoff = bandRows[last][t.name]; cfg.forecastStart = handoff; }
            }
            if (extras.length) {
                cfg.extraLayers = extras.map(m => ({ type: 'line', y: m.name, label: m.name }));
                // The band's y domain covers the actual, the bounds and the
                // forecast, never a layer: widen it when an extra runs outside.
                const all = drawn.concat(fc ? [fc] : []);
                const lo = Math.min(...all.map(m => m.min)), hi = Math.max(...all.map(m => m.max));
                const coreLo = Math.min(...core.concat(fc ? [fc] : []).map(m => m.min)), coreHi = Math.max(...core.concat(fc ? [fc] : []).map(m => m.max));
                if (lo < coreLo || hi > coreHi) { const pad = (hi - lo) * 0.05 || 1; cfg.yDomain = [lo - pad, hi + pad]; }
            }
            if (fc || extras.length) {
                const items = [[B.estimate.name, 'var(--chart-actual, #3b82f6)']];
                if (fc) items.push([fc.name, 'var(--chart-forecast, #3b82f6)']);
                for (const m of extras) items.push([m.name, 'var(--chart-neutral, #6b7280)']);
                cfg.legend = { items: items.map(i => i[0]), colors: items.map(i => i[1]) };
            }
            const why = [`${B.estimate.name} with its bounds (${B.low.name} – ${B.high.name}) over ${t.name} — the line inside its expected band`];
            if (fc) why.push(`${fc.name} drawn dashed as the forecast${handoff !== null ? `, handing off after the last ${B.estimate.name}` : ''}`);
            if (extras.length) why.push(`${extras.map(m => m.name).join(', ')} on the same scale, drawn as labeled lines`);
            push('Line.createBand', B.strong ? 0.95 : 0.8, why,
                { data: bandRows, config: cfg },
                { points: bandRows.length, series: 1 },
                [].concat(B.strong ? [] : [`reads ${B.low.name} / ${B.high.name} as bounds around ${B.estimate.name} — if they are a separate range, chart them as their own series`],
                    dropped.length ? `also measured but not drawn: ${dropped.map(m => (isRowIndex(sorted, m) ? `${m.name} (a row index)` : m.name)).join(', ')}` : []),
                `mapped to { x: ${t.name}, actual: ${B.estimate.name}, lower: ${B.low.name}, upper: ${B.high.name}${fc ? `, forecast: ${fc.name}` : ''} } in time order${extras.length ? `; ${extras.map(m => m.name).join(', ')} as line layers` : ''}`,
                { answers: ['trend', 'deviation'], show: 'summary', fmt: { y: B.estimate }, unencoded: dropped.map(m => m.name) });
        }
        if (M.length === 1) {
            const tr = trendFor(m1);
            const counts = m1.allInt && m1.min >= 0 && m1.max <= 25 && aggregationOf(m1) === 'sum' && !standin && countNamed(m1) && t.distinct <= 60;
            const caveats = [];
            if (sig.xRepeats && m1.measureKind === 'ratio' && !m1.parts) caveats.push(`${m1.name} is a rate with no numerator/denominator: the line shows the MEAN per ${t.name}, which is only right when every row weighs the same`);
            push('Line.createBasic', counts ? 0.84 : 0.9,
                `1 temporal (${t.name}) + 1 measure (${m1.name}) — the default trend chart`,
                { data: tr.data, config: { x: t.name, y: m1.name, ...yModeCfg([m1]) } },
                { points: tr.data.length, series: 1 }, caveats, tr.transform,
                { show: 'summary', variants: [{ name: 'gradient fill', config: { fill: 'gradient' } }], fmt: { y: m1 } });
            if (counts && tr.data.length <= 60) {
                push('Bar.createVertical', 0.9,
                    `small whole-number counts per ${t.name} (${m1.name}) — one column per period reads as events`,
                    { data: tr.data.map(r => ({ x: String(r[t.name]), y: r[m1.name] })), config: {} },
                    { categories: tr.data.length }, [], `${tr.transform ? `${tr.transform}, ` : ''}mapped to { x: ${t.name}, y: ${m1.name} } in time order`,
                    { answers: ['trend', 'magnitude'] });
            }
            if (sig.xRepeats) {
                // Both: the per-period summary line with every row behind it.
                const raw = sorted.map(r => ({ x: tx(r), y: val(r, m1) })).filter(d => d.x !== null && d.y !== null);
                push('Line.createBasic', 0.7,
                    `the ${tr.how || 'mean'} line with every row of ${m1.name} behind it — the summary and the spread together`,
                    { data: tr.data, config: { x: t.name, y: m1.name,
                        // The axis spans the raw rows, not just the summary, so no dot is clipped.
                        yDomain: (() => { const ys = raw.map(d => d.y); const lo = Math.min(...ys), hi = Math.max(...ys), pad = (hi - lo) * 0.05 || 1; return lineYMode([m1]) === 'padded' ? [lo - pad, hi + pad] : [Math.min(0, lo), hi + pad]; })(),
                        extraLayers: [{ type: 'points', data: raw, x: 'x', y: 'y', behind: true, opacity: 0.35, r: 2 }] } },
                    { points: tr.data.length, series: 1 }, [], `${tr.transform}; the raw rows as a points layer behind it`,
                    { answers: ['trend', 'distribution'], show: 'both', fmt: { y: m1 } });
            }
            if (sig.daily && t.distinct >= 60) {
                push('Calendar.createHeatmap', 0.7,
                    `daily grain over ${t.distinct} days — weekday/streak rhythm`,
                    { data: tr.data.map(r => ({ date: r[t.name], value: r[m1.name] })), config: {} },
                    { days: t.distinct }, [], `mapped to { date: ${t.name}, value: ${m1.name} }`);
            }
        } else {
            // 2+ measures over one time axis. On one shared axis a measure in
            // the thousands flattens one in the tens; group the measures by
            // scale and give each scale its own chart.
            const ratio = spanRatio(M);
            const groups = scaleGroups(M);
            const series = M.map(m => ({ name: m.name, data: sig.xRepeats
                ? aggregate(sorted, [t], m, aggregationOf(m) || 'mean').rows.map(e => ({ x: e.keys[0], y: e.value }))
                : sorted.map(r => ({ x: tx(r), y: val(r, m) })) }));
            const mixed = ratio > 100 || groups.length > 1;
            const names = ms => ms.map(m => m.name).join(', ');
            push('Line.createMulti', mixed ? 0.5 : 0.9,
                `${M.length} measures over one temporal axis (${t.name}) — compare as series`,
                { data: rows, config: { series, showPoints: false, ...yModeCfg(M), ...legendFor(series) } },
                { series: M.length, pointsPerSeries: sorted.length },
                mixed ? `measure ranges differ by ~${Math.round(ratio)}× — on one axis the smaller ${names(groups[0])} lie flat; the dual-axis and facet candidates give each scale its own axis` : [],
                `built series[] from measures [${names(M)}]`, { show: 'summary', fmt: { y: sharedFormatMeasure(M) } });
            // Parts of one whole per period (wide): 2–6 same-scale amounts
            // that add up (channel revenue columns), few enough periods to
            // read as columns. Below the lines unless the question is the mix.
            const parts = M.length <= 6 && !mixed && !B && M.every(m => (m.measureKind || measureKind(m)) === 'additive' && !isStock(m) && m.min >= 0);
            const periodsW = series[0].data.length;
            if (parts && periodsW >= 2 && periodsW <= 30) {
                const cols = series[0].data.map((pt, i) => (pt.x === null || pt.x === undefined ? null
                    : Object.fromEntries([['x', bandValueOf(pt.x)], ...series.map(sr => [sr.name, (sr.data[i] || {}).y ?? null])]))).filter(Boolean);
                push('Bar.createVerticalStacked', periodsW <= 12 ? 0.74 : 0.6,
                    `${names(M)} as parts of each ${t.name}'s total — the mix and the total per period`,
                    { data: cols, config: { x: 'x', keys: M.map(m => m.name), legend: true } },
                    { categories: cols.length, series: M.length },
                    ['stacking assumes the columns are parts of one whole — their sum must mean something'],
                    `${sig.xRepeats ? 'aggregated per period, ' : ''}one column per ${t.name}, one segment per measure [${names(M)}]`,
                    { answers: ['composition', 'trend'], show: 'summary', fmt: { y: sharedFormatMeasure(M) } });
            }
            // Dual axis: two scales over one time axis, the larger on the
            // right. It answers trend / relationship (the shapes side by
            // side); magnitude per measure is the facet's (each its own
            // chart). Gated on the metadata so it degrades without y2.
            if (mixed && groups.length === 2 && accepts('Line.createMulti', 'y2Format')) {
                const [lo, hi] = groups;
                const far = ratio > 100;
                const both = lineYMode(lo) === 'padded' && lineYMode(hi) === 'padded';
                push('Line.createMulti', far ? (M.length === 2 ? 0.92 : 0.91) : 0.8,
                    `${M.length === 2 ? 'two measures' : `${M.length} measures in two scale groups`} ~${Math.round(ratio)}× apart — ${names(lo)} on the left axis, ${names(hi)} on its own right axis`,
                    { data: rows, config: { series: series.map((sr, i) => (hi.includes(M[i]) ? { ...sr, axis: 'right' } : sr)), showPoints: false, ...(both ? { yMode: 'padded' } : {}) } },
                    { series: M.length, pointsPerSeries: sorted.length }, [DUAL_CAVEAT],
                    `built series[] from measures [${names(M)}]; ${names(hi)} on the right axis (axis: 'right')`,
                    { answers: ['trend', 'relationship'], show: 'summary', fmt: { y: sharedFormatMeasure(lo), y2: sharedFormatMeasure(hi) } });
            }
            // Bar + line combo: a FLOW that adds up per period (columns from
            // zero) and a rate (a line on the right axis) — orders and
            // conversion, attendance and runs per game.
            const vol = M.find(m => (m.measureKind || measureKind(m)) === 'additive' && m.min >= 0 && isFlow(m));
            const rate = M.find(m => (m.measureKind || measureKind(m)) === 'ratio');
            if (M.length === 2 && vol && rate && !sig.xRepeats && sorted.length <= 60 && accepts('Bar.createVertical', 'y2Format')) {
                const cols = sorted.map(r => ({ x: bandValueOf(r[t.name]), [vol.name]: val(r, vol), [rate.name]: val(r, rate) }));
                push('Bar.createVertical', 0.96,
                    `${vol.name} adds up per ${t.name} (columns from zero) and ${rate.name} is a rate (a line on its own right axis) — the bar + line combo`,
                    { data: cols, config: { x: 'x', y: vol.name, extraLayers: [{ type: 'line', y: rate.name, axis: 'right', label: rate.name }] } },
                    { categories: cols.length }, [DUAL_CAVEAT],
                    `mapped to { x: ${t.name}, ${vol.name}, ${rate.name} }; ${rate.name} as a right-axis line layer`,
                    { answers: ['trend', 'magnitude', 'relationship'], show: 'summary', fmt: { y: vol, y2: rate } });
            }
            if (mixed) {
                const long = series.flatMap(sr => sr.data.map(pt => ({ x: pt.x, measure: sr.name, value: pt.y })));
                push('facet', 0.9,
                    `${M.length} measures on different scales — one line per measure, own y axis each, shared x, linked hover`,
                    { data: long, config: { by: 'measure', chart: { family: 'Line', method: 'createBasic', config: { x: 'x', y: 'value', linkGroup: 'suggest-measures', yMode: 'padded' } }, sharedY: false, columns: 1, axes: 'all' } },
                    {}, [], `pivoted long: one row per ${t.name} × measure (data.pivotLonger), faceted by measure with independent y`,
                    { answers: ['trend', 'magnitude'], show: 'summary', metaBuilder: 'Line.createBasic' });
                // Indexed: every measure as % of its first value — "which grew fastest".
                const firsts = Object.fromEntries(M.map(m => [m.name, (sorted.map(r => val(r, m)).find(v => v !== null && v !== 0)) || null]));
                const idx = M.filter(m => firsts[m.name]).map(m => ({ name: m.name, data: sorted.map(r => { const v = val(r, m); return { x: tx(r), y: v === null ? null : (100 * v) / firsts[m.name] }; }) }));
                if (idx.length >= 2) {
                    push('Line.createMulti', 0.62,
                        `indexed to 100 at the first ${t.name} — every measure on one axis as relative growth`,
                        { data: rows, config: { series: idx, showPoints: false, yMode: 'padded', legend: true } },
                        { series: idx.length, pointsPerSeries: sorted.length },
                        ['shows relative change only — the levels are gone'], 'each measure divided by its first value × 100',
                        { answers: ['trend', 'change'], show: 'summary' });
                }
            }
        }
    }

    // --- panel: time + measure + grouping dimension -------------------------
    if (rule('panel', 'Panel: time + measure + grouping dimension', [['time axis', t], ['a measure', m1], ['grouping dimension', dim]])) {
        const sorted = sortByField(rows, t);
        const groups = groupBy(sorted, dim);
        const yearGroups = !!dim.yearGroup || [...groups.keys()].every(k => /^\d{4}$/.test(String(k)));
        const entries = [...groups.entries()];
        if (yearGroups) entries.sort((a, b) => Number(a[0]) - Number(b[0]));
        // Repeated (x, group) cells aggregate first (orders per day per country).
        const how = aggregationOf(m1);
        const cellAgg = aggregate(sorted, [t, dim], m1, how || 'mean');
        const repeated = cellAgg.repeated;
        const seriesData = rs => (repeated
            ? aggregate(rs, [t], m1, how || 'mean').rows.map(e => ({ x: e.keys[0], y: e.value }))
            : rs.map(r => ({ x: tx(r), y: val(r, m1) })));
        const series = entries.map(([g, rs]) => ({ name: String(g), data: seriesData(rs) }));
        const aggNote = repeated ? `${aggText(how || 'mean', m1, `${t.name} × ${dim.name}`, n, cellAgg.rows.length)}, ` : '';
        const unused = unusedMeasures([m1]);
        const unusedCaveat = unused.length ? `also measured but not drawn: ${unused.join(', ')} — chart them separately (or facet by measure)` : [];
        const periods = t.periods || t.distinct;
        const rank = /(^|_)rank(ing)?s?($|_)/i.test(m1.name) && m1.allInt && m1.min >= 1;
        // Or a rank by structure, whatever its name (place, position, seed):
        // every period's values are 1..k, one per entity.
        const rankShape = !rank && periods >= 3 && !repeated && ranksByStructure(sorted, t, dim, m1);
        if (periods === 2) {
            const slopeRows = twoPointRows(sorted, t, dim, m1);
            if (slopeRows) {
                const [a, b] = [...new Set(sorted.map(r => String(tx(r))))];
                const labels = { leftLabel: String(a), rightLabel: String(b) };
                push('Slope.createBasic', 0.94,
                    `exactly two ${t.name} values (${a}, ${b}) — every ${dim.name}'s change in one glance`,
                    { data: slopeRows, config: labels },
                    { rows: slopeRows.length, periods: 2 }, unusedCaveat, `reshaped to { name: ${dim.name}, before: ${a}, after: ${b} }`,
                    { show: 'individuals', unencoded: unused });
                push('Dot.createDumbbell', 0.9,
                    `the two-point change as gap-focused rows — scales past slope's label limit`,
                    { data: slopeRows.map(r => ({ name: r.name, start: r.before, end: r.after })), config: {} },
                    { rows: slopeRows.length }, unusedCaveat, `reshaped to { name: ${dim.name}, start: ${a}, end: ${b} }`,
                    { show: 'individuals', unencoded: unused });
                const deltas = slopeRows.filter(r => r.before !== null && r.after !== null)
                    .map(r => ({ category: r.name, value: r.after - r.before })).sort((x, y) => y.value - x.value);
                push('Bar.createBasic', 0.7,
                    `the change itself (${b} − ${a}) per ${dim.name} — who improved most`,
                    { data: deltas, config: { signColors: true } },
                    { rows: deltas.length }, [], `computed ${m1.name} ${b} − ${a} per ${dim.name}, sorted desc`,
                    { answers: ['change', 'deviation', 'ranking'] });
            }
        } else if (rank || rankShape) {
            const bump = entries.map(([g, rs]) => ({ name: String(g), rankings: rs.map(r => ({ period: String(tx(r)), rank: val(r, m1) })) }));
            push('Line.createBumpChart', rank ? 0.95 : 0.92, rank ? `${m1.name} is a rank per ${t.name} — rank changes as a bump chart`
                : `${m1.name} runs 1..k in every ${t.name}, one value per ${dim.name} — a rank by structure, so rank changes as a bump chart`,
                { data: bump, config: {} }, { series: bump.length, periods: t.distinct }, [], `grouped rows by ${dim.name} into { name, rankings[] }`,
                { answers: ['ranking', 'trend'] });
        }
        if (periods !== 2) {
            push('Line.createMulti', yearGroups ? 0.75 : 0.9,
                `1 temporal (${t.name}) + 1 measure (${m1.name}) grouped by ${dim.name} (${dim.distinct} series)`,
                { data: rows, config: { series, showPoints: false, ...yModeCfg([m1]), legend: true } },
                { series: dim.distinct, pointsPerSeries: Math.round(sig.rowsPerGroup) },
                [].concat(yearGroups ? 'the series are years — Line.createYoY draws the same lines on the oldest → newest recency ramp' : [], unusedCaveat),
                `${aggNote}grouped rows by ${dim.name} into series[]`, { show: 'summary', unencoded: unused, fmt: { y: m1 } });
            if (dim.distinct > 6 && !yearGroups && dim.distinct <= 30) {
                const flat = entries.flatMap(([g, rs]) => seriesData(rs).map(p => ({ x: p.x, y: p.y, [dim.name]: g })));
                push('facet', dim.distinct <= 16 ? 0.86 : 0.6,
                    `${dim.distinct} ${dim.name} values — small multiples, one line each on shared axes`,
                    { data: flat, config: { by: dim.name, chart: { family: 'Line', method: 'createBasic', config: { x: 'x', y: 'y', ...yModeCfg([m1]) } }, sharedY: true, axes: 'outer' } },
                    {}, unusedCaveat, `${aggNote}one panel per ${dim.name}`,
                    { answers: ['trend'], show: 'summary', metaBuilder: 'Line.createBasic', unencoded: unused });
            }
            if (yearGroups) {
                push('Line.createYoY', 0.9,
                    `the grouping dimension is years — the same measure compared across years (along ${t.name}) wants the recency ramp`,
                    { data: rows, config: { series, x: 'x', y: 'y', legend: true } },
                    { series: dim.distinct }, unusedCaveat, `${aggNote}grouped rows by ${dim.name} (years, oldest first) into series[] along ${t.name}`,
                    { unencoded: unused });
            }
            // Stacking says the series are parts of one whole: only volumes
            // (revenue by channel adds up to revenue), never years or ranks.
            if (M.length === 1 && m1.min >= 0 && !yearGroups && !rank && !rankShape && m1.measureKind === 'additive') {
                const wideMap = new Map();
                for (const s of series) for (const p of s.data) {
                    const k = p.x instanceof Date ? p.x.getTime() : p.x;
                    if (!wideMap.has(k)) wideMap.set(k, { x: p.x });
                    wideMap.get(k)[s.name] = p.y;
                }
                const keys = series.map(s => s.name);
                const volume = isVolume(m1);
                push('Area.createStacked', volume ? 0.72 : 0.42,
                    `composition over time — total and mix together`,
                    { data: [...wideMap.values()], config: { x: 'x', keys, legend: true } },
                    { series: dim.distinct, points: wideMap.size },
                    [volume ? 'stacking assumes the series are parts of one whole' : `stacking adds ${m1.name} across ${dim.name} — only if that total means something`],
                    `${aggNote}pivoted wide: one row per ${t.name}, one column per ${dim.name}`, { answers: ['composition', 'trend'] });
                // The same parts as stacked columns: few periods read as
                // discrete totals better than a continuous area.
                if (dim.distinct >= 2 && dim.distinct <= 6 && wideMap.size >= 2 && wideMap.size <= 30) {
                    const cols = [...wideMap.values()].map(r => ({ ...r, x: bandValueOf(r.x) }));
                    push('Bar.createVerticalStacked', volume ? (wideMap.size <= 12 ? 0.74 : 0.62) : 0.4,
                        `each ${t.name}'s total split by ${dim.name} — the mix per period as stacked columns`,
                        { data: cols, config: { x: 'x', keys, legend: true } },
                        { categories: cols.length, series: dim.distinct },
                        [volume ? 'stacking assumes the series are parts of one whole' : `stacking adds ${m1.name} across ${dim.name} — only if that total means something`],
                        `${aggNote}pivoted wide: one column per ${t.name}, one segment per ${dim.name}`,
                        { answers: ['composition', 'trend'], show: 'summary', unencoded: unused, fmt: { y: m1 } });
                }
            }
        }
    }

    // --- categories: no time axis, one measure, one grouping dimension -------
    const funnel = !t && M.length === 1 && dim && funnelReading(rows, dim, m1);
    if (rule('funnel', 'Funnel: ordered stages, each smaller than the last', [['no time axis', !t], ['exactly 1 measure', M.length === 1], ['a stage dimension', dim], ['stages never grow', funnel]])) {
        const stages = rows.map(r => ({ name: String(r[dim.name]), value: val(r, m1) }));
        push('Funnel.createBasic', 0.95, `${dim.name} reads as funnel stages (${stages.length}) and ${m1.name} never grows along them`,
            { data: stages, config: {} }, { stages: stages.length }, [], `mapped to { name: ${dim.name}, value: ${m1.name} } in stage order`,
            { answers: ['flow', 'magnitude'] });
        const links = [];
        const dropped = 'Dropped off';
        for (let i = 0; i < stages.length - 1; i++) {
            const a = stages[i], b = stages[i + 1];
            links.push({ source: a.name, target: b.name, value: b.value });
            if (a.value - b.value > 0) links.push({ source: a.name, target: `${dropped} (${a.name})`, value: a.value - b.value });
        }
        push('Sankey.createFunnelFlow', 0.8, `the same funnel as flow — the drop-off at each stage drawn as its own ribbon`,
            { data: links, config: { nodeValues: Object.fromEntries(stages.map(s => [s.name, s.value])) } },
            { nodes: stages.length * 2 - 1, links: links.length }, [], `built links stage → next stage and stage → drop-off`, { answers: ['flow'] });
    }

    const oneMeasureCats = !t && m1 && dim && M.length === 1;
    const ordered = !!(dim && dim.ordered);
    if (rule('cat', 'Categories: one measure, one row per category', [['no time axis', !t], ['exactly 1 measure', M.length === 1], ['a dimension', dim], [`rows per group ≤ 1.5 (${sig.rowsPerGroup.toFixed(2)})`, dim && sig.rowsPerGroup <= 1.5], ['not funnel stages', !funnel]])) {
        const how = aggregationOf(m1);
        const agg = aggregate(rows, [dim], m1, how || 'sum');
        const blocked = agg.repeated && !how;           // a rate repeated with no parts
        const mapped = blocked ? [] : agg.rows.map(e => ({ category: e.keys[0], value: e.value }));
        const aggNote = agg.repeated && !blocked ? `${aggText(how, m1, dim.name, n, mapped.length, 'categories')}, ` : '';
        const signed = mapped.some(r => r.value < 0) && mapped.some(r => r.value > 0);
        const k = mapped.length;
        const sumCav = agg.repeated && how === 'sum' ? [sumCaveat(dim.name, m1)] : agg.repeated && how === 'mean' ? [`${dim.name} repeats across rows, so ${m1.name} (a level) is AVERAGED per ${dim.name}`] : [];
        const ranked = mapped.slice().sort((a, b) => (b.value ?? -Infinity) - (a.value ?? -Infinity));
        const cap = 20;
        if (!blocked && ordered) {
            // Ordered categories keep their order: columns, never re-ranked, no donut.
            push('Bar.createVertical', 0.9, `${dim.name} has an order (${k} values) — columns in that order`,
                { data: mapped.map(r => ({ x: String(r.category), y: r.value })), config: {} },
                { categories: k }, sumCav, `${aggNote}mapped to { x: ${dim.name}, y: ${m1.name} } in source order`, { answers: ['magnitude', 'trend'], fmt: { y: m1 } });
            push('Bar.createBasic', 0.72, `the same values as rows, in ${dim.name} order (labels read horizontally)`,
                { data: mapped, config: signed ? { signColors: true } : {} }, { rows: k }, [], `${aggNote}mapped to { category: ${dim.name}, value: ${m1.name} } in source order`, { fmt: { value: m1 } });
        } else if (!blocked) {
            const big = k > 200;
            // Past the comfortable cap, a MODEST leftover (up to the cap again)
            // folds: every row is drawn, the first `cap` show and "Show all k"
            // opens the rest (maxRows — the axis already spans every row). A
            // longer tail buckets into "Other" instead.
            const fold = k > cap && k <= cap * 2;
            const shown = k > cap && !fold ? ranked.slice(0, cap) : ranked;
            const rest = ranked.slice(cap);
            const otherValue = how === 'sum' ? rest.reduce((s, r) => s + (r.value || 0), 0) : null;
            const capped = k > cap && !fold ? shown.concat(otherValue !== null ? [{ category: 'Other', value: otherValue }] : []) : shown;
            const capNote = fold ? `, the first ${cap} shown (maxRows: ${cap}, "Show all ${k}")`
                : k > cap ? `, top ${cap}${otherValue !== null ? ` + "Other" (${rest.length} more summed)` : ` of ${k}`}` : '';
            const capCaveat = fold ? [`${k} categories — the first ${cap} shown; "Show all ${k}" opens the other ${k - cap}`]
                : k > cap ? [`${k} categories — showing the top ${cap}; the full list belongs in a table or a histogram`] : [];
            const variants = signed ? [{ name: 'Bar.createDiverging', builder: 'Bar.createDiverging', note: 'labels at the center line — the more designed look' }] : [];
            push('Bar.createBasic', big ? 0.6 : 0.9,
                `1 categorical (${dim.name}) + 1 measure (${m1.name}), one row per category — ranked bars${signed ? ' colored by sign' : ''}`,
                { data: capped, config: { ...(signed ? { signColors: true } : {}), ...(fold ? { maxRows: cap } : {}) } },
                { rows: fold ? cap : capped.length }, capCaveat.concat(sumCav),
                `${aggNote}mapped to { category: ${dim.name}, value: ${m1.name} }, sorted desc${capNote}`, { variants, fmt: { value: m1 } });
            // Deviation: each category against the average of all of them.
            if (k >= 3 && k <= 20 && how !== null) {
                const vals = mapped.map(r => r.value).filter(v => v !== null);
                const mean = vals.reduce((a, v) => a + v, 0) / vals.length;
                const dev = mapped.map(r => ({ category: r.category, value: r.value === null ? null : roundFor(r.value - mean, m1) })).sort((a, b) => b.value - a.value);
                push('Bar.createBasic', 0.55, `each ${dim.name} above or below the average (${roundFor(mean, m1).toLocaleString('en-US')})`,
                    { data: dev, config: { signColors: true } }, { rows: Math.min(k, 20) }, k > 20 ? [`${k} rows — cap them before drawing`] : [],
                    `${aggNote}computed ${m1.name} − its mean across ${dim.name}, sorted desc`, { answers: ['deviation'], fmt: { value: m1 } });
            }
            // The table takes the context a bar chart leaves out.
            const extras = sig.dimensions.filter(d => d !== dim).concat(sig.idFields.filter(f => f !== dim && !f.promoted && f.name !== dim.name));
            push('Table.createWithBars', 0.84 + (k > cap * 2 && k <= 200 ? 0.08 : 0) + (extras.length ? 0.06 : 0) + (ctx.intent === 'lookup' ? 0.1 : 0),
                `a sortable table with an in-cell bar per row — exact values, ${k > cap ? `all ${k} rows, ` : ''}room for more columns`,
                { data: (agg.repeated ? mapped.map(r => ({ [dim.name]: r.category, [m1.name]: r.value })) : rows.map(r => ({ ...r, [m1.name]: val(r, m1) })))
                    .map(r => ({ ...r, [m1.name]: roundFor(r[m1.name], m1) })),
                    config: tableConfig(dim, m1, agg.repeated ? [] : extras, k) },
                { rows: Math.min(k, 40) }, [], `${aggNote}one row per ${dim.name}${k > 40 ? `, ${Math.min(k, 40)} shown with "Show all"` : ''}`,
                { answers: ['lookup', 'ranking', 'magnitude'], setup: TABLE_SETUP });
            if (big) {
                push('Histogram.createBasic', 0.92, `${k} ${dim.name} values are too many to read one by one — the distribution of ${m1.name} across them`,
                    { data: mapped.map(r => ({ value: r.value })), config: { valueAccessor: 'value' } }, { points: k }, [], `${aggNote}mapped to { value: ${m1.name} }`,
                    { answers: ['distribution', 'magnitude'], show: 'summary' });
            }
            if (k <= 8) {
                push('Bar.createVertical', 0.32, `columns — weaker here: ${dim.name} has no order, and vertical labels crowd`,
                    { data: mapped.map(r => ({ x: String(r.category), y: r.value })), config: {} }, { categories: k },
                    ['horizontal bars read better for unordered categories'].concat(sumCav), `${aggNote}mapped to { x: ${dim.name}, y: ${m1.name} }`, { fmt: { y: m1 } });
            }
            // Part of a whole needs parts that never overlap and add up to a
            // meaningful total: a volume, all ≥ 0, few slices, unordered.
            if (mapped.every(r => r.value === null || r.value >= 0) && how === 'sum' && k <= 8) {
                const shareRows = mapped.map(r => ({ label: String(r.category), value: r.value }));
                const volume = isVolume(m1);
                push('Donut.createBasic', volume ? 0.5 : 0.3, `part-of-whole reading of the same signature`,
                    { data: shareRows, config: {} }, { slices: k },
                    ['only if the values are parts of one whole — suggest() cannot verify that'].concat(sumCav), `${aggNote}mapped to { label: ${dim.name}, value: ${m1.name} }`);
                if (k <= 4) {
                    push('Donut.createPie', volume ? 0.44 : 0.26, `the same part-of-whole with ${k} slices, as the pie readers expect`,
                        { data: shareRows, config: {} }, { slices: k },
                        ['same encoding as Donut.createBasic — pick the donut if you want a total in the middle'].concat(sumCav), `${aggNote}mapped to { label: ${dim.name}, value: ${m1.name} }`);
                }
            }
            if (how === 'sum' && k >= 2 && mapped.every(r => r.value === null || r.value >= 0)) shareBars(push, mapped, dim, m1, aggNote.replace(/, $/, ''));
            // A bridge: signed deltas between a start and an end total.
            let totals = mapped.filter(r => /^(start|begin|beginning|opening|end|ending|closing|total|net|final)\b/i.test(String(r.category)));
            if (signed && !totals.length && k >= 4 && !agg.repeated) {
                // By value: the first row plus every step between lands on the last row.
                const first = mapped[0].value, last = mapped[k - 1].value;
                const mid = mapped.slice(1, -1).reduce((a, r) => a + (r.value || 0), 0);
                if (first > 0 && last > 0 && Math.abs(first + mid - last) <= 0.02 * Math.abs(last)) totals = [mapped[0], mapped[k - 1]];
            }
            if (signed && totals.length >= 1 && k <= 20) {
                const steps = mapped.map(r => (totals.includes(r) ? { name: String(r.category), total: r.value } : { name: String(r.category), value: r.value }));
                push('Bar.createWaterfall', 0.95, `signed steps between named totals (${totals.map(r => r.category).join(', ')}) — a bridge`,
                    { data: steps, config: {} }, { rows: k }, [], `mapped to { name, value | total } in source order`, { answers: ['composition', 'change'] });
            }
        }
        if (blocked) {
            const pts = rows.map(r => ({ category: r[dim.name], value: val(r, m1) }));
            push('Scatter.createBeeswarm', 0.82, `${m1.name} is a rate or an average and ${dim.name} repeats — each row as a dot (rates are never summed or averaged across rows)`,
                { data: pts, config: {} }, { categories: dim.distinct, points: Math.max(n, 10) }, [], `mapped to { category: ${dim.name}, value: ${m1.name} }, one dot per row`,
                { answers: ['magnitude', 'distribution'], show: 'individuals', fmt: { value: m1 } });
            ctx.questions.push({ field: m1.name, ask: `${m1.name} is a rate or an average and ${dim.name} repeats — which columns are its numerator and denominator?`,
                why: 'a sum or a mean of averages is wrong whenever the groups differ in size' });
        }
    }

    if (rule('dist-group', 'Per-category values: many rows per category', [['no time axis', !t], ['exactly 1 measure', M.length === 1], ['a dimension', dim], ['rows per group > 1.5', dim && sig.rowsPerGroup > 1.5], ['one dimension', D.length === 1]])) {
        const how = aggregationOf(m1);
        const per = Math.round(sig.rowsPerGroup);
        const mappedRows = rows.map(r => ({ category: r[dim.name], value: val(r, m1), name: name ? String(r[name.name]) : undefined }));
        const groupCounts = [...groupBy(rows, dim).values()].map(rs => rs.length);
        const minPer = Math.min(...groupCounts);
        // The aggregate per category (total, mean, or a rate rebuilt from its parts).
        if (how) {
            const agg = aggregate(rows, [dim], m1, how);
            const mapped = agg.rows.map(e => ({ category: e.keys[0], value: e.value }));
            const note = aggText(how, m1, dim.name, n, mapped.length, 'categories');
            const sorted = ordered ? mapped : mapped.slice().sort((a, b) => b.value - a.value);
            const total = how === 'sum';
            push(ordered ? 'Bar.createVertical' : 'Bar.createBasic', total && isVolume(m1) ? 0.88 : total ? 0.74 : 0.78,
                `${how === 'sum' ? 'total' : how === 'mean' ? 'average' : 'overall'} ${m1.name} per ${dim.name} — the aggregate`,
                { data: ordered ? sorted.map(r => ({ x: String(r.category), y: r.value })) : sorted, config: {} },
                ordered ? { categories: mapped.length } : { rows: mapped.length },
                how === 'mean' ? [`${m1.name} is a level, so the bar is its mean per ${dim.name}`] : [], `${note}${ordered ? ' in order' : ', sorted desc'}`,
                { answers: ['magnitude', 'ranking'], show: 'summary' });
            if (total) ctx.questions.push({ field: m1.name, ask: `total ${m1.name} per ${dim.name}, or the typical row?`, ifA: 'bars of the sum', ifB: 'a boxplot of the rows' });
            // Part of a whole: the totals as shares (named volumes; few slices; unordered).
            if (total && m1.min >= 0 && !ordered && mapped.length <= 8) {
                push('Donut.createBasic', isVolume(m1) ? 0.5 : 0.3, `each ${dim.name}'s share of total ${m1.name}`,
                    { data: mapped.map(r => ({ label: String(r.category), value: r.value })), config: {} }, { slices: mapped.length },
                    ['only if the values are parts of one whole — suggest() cannot verify that'], `${note}, as shares`,
                    { answers: ['composition'], show: 'summary' });
            }
            if (total && m1.min >= 0 && !ordered) shareBars(push, mapped, dim, m1, note);
        } else if (m1.measureKind === 'ratio') {
            ctx.questions.push({ field: m1.name, ask: `${m1.name} is a rate or an average: which columns are its numerator and denominator?`,
                why: 'without them it can only be shown row by row, never summed or averaged' });
        }
        // The rows themselves.
        if (minPer >= 5) {
            push('BoxPlot.createBasic', how === 'sum' && isVolume(m1) ? 0.8 : 0.86,
                `${per} records per ${dim.name} — the spread per category`,
                { data: mappedRows.map(({ category, value }) => ({ category, value })), config: {} },
                { categories: dim.distinct, points: per }, [], `mapped to { category: ${dim.name}, value: ${m1.name} }`,
                { answers: ['distribution'], show: 'summary' });
        }
        // Enough rows per group for a density to be honest (and few groups):
        // the violin shows the shape (two peaks, a long tail) a box hides.
        if (minPer >= 50 && dim.distinct <= 8) {
            push('BoxPlot.createViolin', 0.72,
                `${minPer}+ records in every ${dim.name} — enough for the distribution's shape (peaks, skew, tails), not just its quartiles`,
                { data: mappedRows.map(({ category, value }) => ({ category, value })), config: {} },
                { categories: dim.distinct, points: minPer },
                ['a smoothed density — its bandwidth shapes the outline; the box plot states the quartiles exactly'],
                `mapped to { category: ${dim.name}, value: ${m1.name} }`,
                { answers: ['distribution'], show: 'summary', fmt: { value: m1 } });
        }
        const strip = per < 10;
        if (n <= 400 && per <= 150) {
            push('Scatter.createBeeswarm', strip ? 0.84 : 0.76,
                strip ? `only ${per} per ${dim.name} — every point labeled, a dot plot` : `every ${m1.name} visible per ${dim.name}`,
                { data: mappedRows.map(({ category, value, name: nm }) => (nm !== undefined ? { category, value, name: nm } : { category, value })), config: {} },
                { categories: dim.distinct, points: strip ? Math.max(n, 10) : n }, [], `mapped to { category: ${dim.name}, value: ${m1.name}${name ? `, name: ${name.name}` : ''} }`,
                { answers: ['distribution'], show: 'individuals', fmt: { value: m1 } });
        }
        if (dim.distinct <= 4 && n >= 60) {
            const series = [...groupBy(rows, dim).entries()].map(([g, rs]) => ({ name: String(g), data: rs.map(r => ({ value: val(r, m1) })) }));
            push('Histogram.createOverlay', 0.6, `${dim.distinct} groups — distribution shape on shared bins`,
                { data: rows, config: { series, legend: true } }, { series: dim.distinct, points: n }, [], `grouped rows by ${dim.name} into series[] of { value: ${m1.name} }`,
                { show: 'summary' });
        }
    }

    // --- one bare measure ----------------------------------------------------
    if (rule('dist', 'One bare measure', [['no time axis', !t], ['exactly 1 measure', M.length === 1], ['no dimension', !dim]])) {
        push('Histogram.createBasic', n >= 30 ? 0.9 : 0.6,
            `a single measure (${m1.name}) across ${n} records — distribution shape`,
            { data: rows.map(r => ({ ...r, [m1.name]: val(r, m1) })), config: { valueAccessor: m1.name } }, { points: n }, [], null, { show: 'summary' });
        if (n <= 150) {
            push('Scatter.createBeeswarmHorizontal', n < 30 ? 0.84 : 0.62, `the same distribution with every record visible`,
                { data: rows.map(r => ({ value: val(r, m1), name: name ? String(r[name.name]) : undefined })), config: {} },
                { points: n }, [], `mapped to { value: ${m1.name} }`, { show: 'individuals', fmt: { value: m1 } });
        }
    }

    // --- named rows with a shaped set of measures (no time axis) -------------
    // The row label: the rows' name, or a dimension holding one row per value.
    const rowLabel = name || (dim && sig.rowsPerGroup <= 1.5 ? dim : null);
    const bounds = sig.bounds, S = sig.scale;
    const unusedOf = used => M.filter(m => !used.includes(m));

    // An estimate with its interval per named row (experiment arms, survey
    // estimates, model coefficients).
    if (rule('interval', 'Estimates with bounds, one per named row', [['no time axis', !t], ['an estimate with low/high bounds', bounds], ['a row label', rowLabel]])) {
        const control = v => /^(control|baseline|holdout|placebo)\b/i.test(String(v).trim());
        const data = rows.map(r => {
            const o = { name: String(r[rowLabel.name]), value: val(r, bounds.estimate), ci_low: val(r, bounds.low), ci_high: val(r, bounds.high) };
            if (control(r[rowLabel.name])) o.isControl = true;
            return o;
        });
        const rest = unusedOf([bounds.estimate, bounds.low, bounds.high]);
        // With a control row the rows are colored by significance against it
        // (the builder's rule: the two intervals do not overlap), so the
        // legend names the colors the chart actually uses.
        const ctl = data.find(d => d.isControl);
        const legend = (() => {
            if (!ctl || ctl.ci_low === null || ctl.ci_high === null) return null;
            const sig = d => !d.isControl && d.ci_low !== null && d.ci_high !== null && (d.ci_low > ctl.ci_high || d.ci_high < ctl.ci_low);
            const items = [['Control', 'var(--color-text-muted, #666)']];
            if (data.some(sig)) items.push(['Significant vs control', 'var(--chart-green, #22c55e)']);
            if (data.some(d => !d.isControl && !sig(d))) items.push(['Not significant', 'var(--chart-primary, #3b82f6)']);
            return { items: items.map(i => i[0]), colors: items.map(i => i[1]) };
        })();
        push('Dot.createConfidence', bounds.strong ? 0.95 : 0.78,
            `${bounds.estimate.name} with its interval (${bounds.low.name} – ${bounds.high.name}) per ${rowLabel.name} — each estimate and its uncertainty`,
            { data, config: { rowLabel: headerOf(rowLabel.name), valueLabel: headerOf(bounds.estimate.name), ...(legend ? { legend } : {}) } },
            { rows: data.length },
            [].concat(data.some(d => d.isControl) ? [] : ['no control row (a name like "Control") — every row is drawn as a treatment; mark one with isControl to color rows by significance against it'],
                bounds.strong ? [] : [`reads ${bounds.low.name} / ${bounds.high.name} as an interval around ${bounds.estimate.name} — draw only real intervals`],
                rest.length ? `also measured but not drawn: ${rest.map(m => m.name).join(', ')}` : []),
            `mapped to { name: ${rowLabel.name}, value: ${bounds.estimate.name}, ci_low: ${bounds.low.name}, ci_high: ${bounds.high.name} }${data.some(d => d.isControl) ? ', the control row flagged' : ''}`,
            { answers: ['magnitude', 'deviation'], show: 'individuals', fmt: { value: bounds.estimate }, unencoded: rest.map(m => m.name) });
    }

    // Survey responses: one row per question, one column per point of an
    // ordinal response scale — a diverging stack centered on neutral.
    if (rule('likert', 'Response scale per question', [['no time axis', !t], ['3–7 columns naming one response scale', S], ['a question label', rowLabel]])) {
        const keys = S.keys;
        const sums = rows.map(r => keys.reduce((a, k) => a + (numberOf(r[k]) || 0), 0));
        const scaleBy = sums.every(v => Math.abs(v - 100) <= 1.5) ? 1 : sums.every(v => Math.abs(v - 1) <= 0.015) ? 100 : null;
        const data = rows.map((r, i) => Object.fromEntries([['question', String(r[rowLabel.name])], ...keys.map(k => {
            const v = numberOf(r[k]);
            return [k, v === null ? null : scaleBy ? Math.round(v * scaleBy * 10) / 10 : sums[i] ? Math.round((1000 * v) / sums[i]) / 10 : null];
        })]));
        const labels = Object.fromEntries(keys.map(k => [k, headerOf(k)]));
        const mid = keys.length % 2 ? labels[keys[(keys.length - 1) / 2]] : '';
        const rest = unusedOf(S.measures);
        push('Bar.createLikert', S.named ? 0.95 : 0.8,
            `${keys.length} columns name the points of one response scale (${labels[keys[0]]} … ${labels[keys[keys.length - 1]]}) per ${rowLabel.name} — a diverging stack centered on ${mid ? `"${mid}"` : 'the middle'}`,
            { data, config: { keys, labels, contextLabels: { left: `← ${labels[keys[0]]}`, center: mid, right: `${labels[keys[keys.length - 1]]} →` } } },
            { rows: data.length, series: keys.length },
            [].concat(S.named ? [] : [`reads the columns ${keys.join(', ')} as an ordered response scale, lowest = most negative — check the scale's direction`],
                rest.length ? `also measured but not drawn: ${rest.map(m => m.name).join(', ')}` : []),
            `${scaleBy === 1 ? '' : scaleBy === 100 ? 'shares × 100, ' : `each ${rowLabel.name}'s counts as % of its responses, `}mapped to { question: ${rowLabel.name}, ${keys.join(', ')} } (negative → positive)`,
            { answers: ['distribution', 'composition'], show: 'summary', unencoded: rest.map(m => m.name) });
    }

    // Profiles: a few entities scored on 3–8 measures that share one scale.
    const maxes = M.map(m => m.max);
    const sameScale = M.length >= 3 && M.length <= 8 && M.every(m => m.min >= 0) && Math.min(...maxes) > 0 && Math.max(...maxes) <= 2.5 * Math.min(...maxes);
    if (rule('profile', 'Profiles: 2–5 entities × 3–8 same-scale measures', [['no time axis', !t], ['2–5 named rows', rowLabel && n >= 2 && n <= 5], ['3–8 measures on one scale', sameScale], ['not a response scale or an estimate with bounds', !S && !bounds]])) {
        const data = rows.map(r => Object.fromEntries([['name', String(r[rowLabel.name])], ...M.map(m => [m.name, val(r, m)])]));
        const lo = Math.min(...M.map(m => m.min)), hi = Math.max(...maxes);
        push('Radar.createBasic', 0.55,
            `${n} ${rowLabel.name} values scored on ${M.length} measures that share one range (${roundFor(lo, M[0])}–${roundFor(hi, M[0])}) — each profile's shape`,
            { data, config: { axes: M.map(m => ({ key: m.name, label: headerOf(m.name) })) } },
            { series: n, axes: M.length },
            ['bars or a table read each value more precisely — a radar shows the overall shape of each profile, and its area exaggerates differences',
                'one radial scale for every axis: honest only while the measures share a unit'],
            `mapped to { name: ${rowLabel.name}, ${M.map(m => m.name).join(', ')} }`,
            { answers: ['magnitude'], show: 'individuals' });
    }

    // Two populations per binned category (an age pyramid: male / female per
    // age band): mirrored wings, the shape's asymmetry the message. Bins or a
    // band-named axis only — two channels per quarter are not two wings.
    const partCols = M.length >= 2 && M.length <= 6 && scaleGroups(M).length === 1 && M.every(m => (m.measureKind || measureKind(m)) === 'additive' && !isStock(m) && m.min >= 0);
    const WING_PAIRS = [/^(male|males|men|man|boys?)$/i, /^(female|females|women|woman|girls?)$/i];
    const binned = rowLabel && rowLabel.ordered && (
        rows.every(r => RANGE_BIN.test(String(r[rowLabel.name]))) || /(^|_)(age|ages|age_?group|age_?band|cohort|band|bucket|bin|size|grade|tier|level)s?($|_)/i.test(rowLabel.name));
    const wings = M.length === 2 && partCols && binned;
    if (rule('pyramid', 'Two populations per binned category', [['no time axis', !t], ['a binned, ordered row label', binned], ['exactly 2 additive same-scale measures', wings], ['3–25 rows', n >= 3 && n <= 25], ['not a response scale or an estimate with bounds', !S && !bounds]])) {
        const sexed = WING_PAIRS[0].test(M[0].name.trim()) || WING_PAIRS[1].test(M[0].name.trim()) ? WING_PAIRS.every(re => M.some(m => re.test(m.name.trim()))) : false;
        // Male conventionally on the left; otherwise the columns' order.
        const keys = sexed ? [M.find(m => WING_PAIRS[0].test(m.name.trim())), M.find(m => WING_PAIRS[1].test(m.name.trim()))].map(m => m.name) : M.map(m => m.name);
        // The first row is drawn at the top: put the highest bin there.
        const lead = v => { const x = /\d+(?:\.\d+)?/.exec(String(v)); return x ? Number(x[0]) : null; };
        const first = lead(rows[0][rowLabel.name]), last = lead(rows[rows.length - 1][rowLabel.name]);
        const flip = first !== null && last !== null && first < last;
        const src = flip ? rows.slice().reverse() : rows;
        const data = src.map(r => Object.fromEntries([[rowLabel.name, String(r[rowLabel.name])], ...keys.map(k => [k, val(r, M.find(m => m.name === k))])]));
        push('Bar.createPyramid', sexed ? 0.88 : 0.8,
            `${keys.join(' / ')} per ${rowLabel.name} — two populations mirrored around one axis, so the shape's asymmetry reads at a glance`,
            { data, config: { keys, labels: Object.fromEntries(keys.map(k => [k, headerOf(k)])), categoryAccessor: rowLabel.name } },
            { rows: data.length, series: 2 }, [],
            `mapped to { ${rowLabel.name}, ${keys.join(', ')} }${flip ? `, highest ${rowLabel.name} first (drawn on top)` : ' in source order'}`,
            { answers: ['distribution', 'composition', 'magnitude'], show: 'summary', fmt: { value: sharedFormatMeasure(M) } });
    }

    // Parts per ORDERED category (an age band, a stage, a quarter label): 2–6
    // additive same-scale columns stacked into each category's total.
    if (rule('stack-cols', 'Parts per ordered category', [['no time axis', !t], ['an ordered row label', rowLabel && rowLabel.ordered], ['2–6 additive same-scale measures', partCols], ['2–30 rows', n >= 2 && n <= 30], ['not a response scale or an estimate with bounds', !S && !bounds]])) {
        const cols = rows.map(r => Object.fromEntries([['x', String(r[rowLabel.name])], ...M.map(m => [m.name, val(r, m)])]));
        push('Bar.createVerticalStacked', 0.66,
            `${rowLabel.name} has an order and ${M.map(m => m.name).join(', ')} add up within it — each column's total and its mix`,
            { data: cols, config: { x: 'x', keys: M.map(m => m.name), legend: true } },
            { categories: cols.length, series: M.length },
            ['stacking assumes the columns are parts of one whole — their sum must mean something'],
            `mapped to { x: ${rowLabel.name}, ${M.map(m => m.name).join(', ')} } in source order`,
            { answers: ['composition', 'magnitude'], show: 'summary', fmt: { y: sharedFormatMeasure(M) } });
    }

    // --- two+ measures, no time axis -----------------------------------------
    if (rule('xy', 'Two+ measures, no time axis', [['no time axis', !t], ['2+ measures', M.length >= 2]])) {
        // A low-cardinality whole number (inning 1–9, tier 1–4) may be a
        // CATEGORY axis: offer the aggregate and the spread per value.
        const ord = M.filter(m => m.ordinal).sort((a, b) => (b.ordinal.named - a.ordinal.named) || (a.distinct - b.distinct))[0];
        // The measure to aggregate along it: never another position or ordinal.
        const isPos = m => !!UNIT_OF[positionWord(m.name)];
        const other = ord && (M.find(m => m !== ord && !m.ordinal && !isPos(m)) || M.find(m => m !== ord && !isPos(m) && !(m.ordinal && m.ordinal.named)));
        const bothDiscrete = ord && other && other.allInt && other.distinct <= 12;
        if (ord && other) {
            const howO = aggregationOf(other);
            const ordF = { ...ord, kind: 'numeric' };
            if (howO) {
                for (const h of howO === 'sum' ? ['sum', 'mean'] : [howO]) {
                    const agg = aggregate(rows, [ordF], other, h);
                    const cols = agg.rows.map(e => ({ x: Number(e.keys[0]), y: e.value })).sort((a, b) => a.x - b.x).map(r => ({ x: String(r.x), y: r.y }));
                    push('Bar.createVertical', h === 'sum' ? 0.88 : 0.84,
                        `${ord.name} as an ordered category (${ord.distinct} values) — ${h === 'sum' ? 'total' : 'average'} ${other.name} per ${ord.name}`,
                        { data: cols, config: {} }, { categories: cols.length }, [], `${aggText(h, other, ord.name, n, cols.length)}, in ${ord.name} order`,
                        { answers: ['magnitude'], show: 'summary', fmt: { y: other } });
                }
            }
            if (n / ord.distinct >= 5) {
                push('BoxPlot.createBasic', 0.74, `the spread of ${other.name} within each ${ord.name}`,
                    { data: rows.map(r => ({ category: String(numberOf(r[ord.name])), value: val(r, other) })).filter(r => r.category !== 'null').sort((a, b) => Number(a.category) - Number(b.category)), config: {} },
                    { categories: ord.distinct, points: Math.round(n / ord.distinct) }, [], `mapped to { category: ${ord.name}, value: ${other.name} }`,
                    { answers: ['distribution'], show: 'summary' });
            }
            if (bothDiscrete) {
                const cells = new Map();
                for (const r of rows) {
                    const a = numberOf(r[ord.name]), b = numberOf(r[other.name]);
                    if (a === null || b === null) continue;
                    const k = `${a}|${b}`;
                    cells.set(k, { x: String(a), y: String(b), value: ((cells.get(k) || {}).value || 0) + 1, ax: a, by: b });
                }
                const grid = [...cells.values()].sort((p, q) => p.ax - q.ax || p.by - q.by).map(({ x, y, value }) => ({ x, y, value }));
                push('Scatter.createHeatmap', 0.8, `both ${ord.name} and ${other.name} are small whole numbers — a count per cell shows how often each pair occurs (dots would hide the repeats)`,
                    { data: grid, config: {} }, { points: grid.length }, [], `counted rows per ${ord.name} × ${other.name} cell`,
                    { answers: ['distribution', 'relationship'], show: 'summary' });
            }
        }
        const mapped = rows.map(r => ({
            x: val(r, m1), y: val(r, m2),
            category: dim ? String(r[dim.name]) : undefined,
            name: name ? String(r[name.name]) : undefined,
        }));
        const scatterCaveats = [];
        if (M.length > 2) scatterCaveats.push(`remaining measures unencoded: ${M.slice(2).map(m => m.name).join(', ')}`);
        if (sig.pair) scatterCaveats.push(`${sig.pair[0].name}/${sig.pair[1].name} look like a same-unit pair — a paired form likely reads better`);
        if (rangeOverlap(m1, m2) > 0.5 && !bothDiscrete) scatterCaveats.push(`${m1.name} and ${m2.name} share a range — if they share a unit, a y = x reference line (annotations: [{ type: 'diagonal' }]) shows which side of even each point sits`);
        const op = overlapOpacity(n);
        // An axis spanning three or more orders of magnitude (population,
        // GDP, revenue across companies) reads on a log scale.
        const logOf = m => m.min > 0 && m.max / m.min >= 1000;
        const logCfg = { ...(logOf(m1) ? { xScaleType: 'log' } : {}), ...(logOf(m2) ? { yScaleType: 'log' } : {}) };
        const cloudMax = (cardOf('Scatter.createBasic').points || [])[1];
        const dense = cloudMax != null && n > cloudMax;
        // Response-scale columns or an estimate with its bounds are one
        // shape, not two measures to correlate.
        const shaped = !!(S || (bounds && bounds.strong));
        if (shaped) scatterCaveats.push(S ? 'these columns are points of one response scale — plotting one against another says little' : `${bounds.low.name} / ${bounds.high.name} bound ${bounds.estimate.name} — plotting them against each other says little`);
        const scatterBase = shaped ? 0.45 : bothDiscrete ? 0.4 : (ord && ord.ordinal.named) ? 0.6 : sig.pair ? 0.72 : dense ? 0.6 : 0.88;
        const sc = push('Scatter.createBasic', scatterBase,
            `2 measures (${m1.name} vs ${m2.name}) — relationship, clusters, outliers` + (dim ? `, colored by ${dim.name}` : ''),
            { data: mapped, config: { ...(op.opacity < 1 ? { dotOpacity: op.opacity } : {}), ...logCfg } },
            { points: n },
            scatterCaveats.concat(bothDiscrete ? ['both axes are discrete — dots stack on the same spots and hide how often each occurs'] : []),
            `mapped to { x: ${m1.name}, y: ${m2.name}${dim ? `, category: ${dim.name}` : ''}${name ? `, name: ${name.name}` : ''} }`,
            { show: 'individuals', unencoded: M.slice(2).map(m => m.name), fmt: { x: m1, y: m2 } });
        if (op.opacity < 1) sc.why.push(`~${Math.round(op.share * 100)}% of dots overlap at this size — dotOpacity ${op.opacity} keeps the dense regions readable`);
        if (dense) {
            const points = mapped.map(({ x, y }) => ({ x, y }));
            const xy = `mapped to { x: ${m1.name}, y: ${m2.name} }`;
            push('Scatter.createContour', 0.86, `${n} points overplot as dots — smoothed density levels show where they concentrate`,
                { data: points, config: {} }, { points: n },
                'a smoothed estimate — its bandwidth shapes the levels, so check them against the raw points', xy, { show: 'summary' });
            push('Scatter.createDensity', 0.82, `the same cloud as hexagon tiles colored by count — exact counts per tile`,
                { data: points, config: {} }, { points: n }, [], xy, { show: 'summary' });
        }
        if (sig.pair && name) {
            const [a, b] = sig.pair;
            const range = /^(low|min|start|from|open)$/i.test(a.name) && /^(high|max|end|to|close)$/i.test(b.name);
            const pr = rows.map(r => ({ name: String(r[name.name]), start: val(r, a), end: val(r, b) }));
            if (range && /^(low|min)$/i.test(a.name)) {
                push('Bar.createRange', 0.93, `${a.name}/${b.name} per ${name.name} — a span from low to high`,
                    { data: rows.map(r => ({ name: String(r[name.name]), low: val(r, a), high: val(r, b) })), config: {} },
                    { rows: n }, [], `reshaped to { name: ${name.name}, low: ${a.name}, high: ${b.name} }`, { answers: ['distribution', 'magnitude'] });
            }
            push('Dot.createDumbbell', 0.92, `${a.name}/${b.name} read as a same-unit pair per ${name.name} — the gap is the message`,
                { data: pr, config: {} }, { rows: n }, [], `reshaped to { name: ${name.name}, start: ${a.name}, end: ${b.name} }`, { show: 'individuals' });
            push('Slope.createBasic', 0.76, `the same pair with crossings and rate-of-change visible`,
                { data: rows.map(r => ({ name: String(r[name.name]), before: val(r, a), after: val(r, b) })), config: { leftLabel: a.name, rightLabel: b.name } },
                { rows: n, periods: 2 }, [], `reshaped to { name: ${name.name}, before: ${a.name}, after: ${b.name} }`, { show: 'individuals' });
        }
        // Many measures per named entity: a table reads every value exactly.
        if (name && M.length >= 3 && n <= 200) {
            push('Table.createWithBars', 0.8, `${M.length} measures per ${name.name} — a sortable table reads every value`,
                { data: rows.map(r => Object.fromEntries([[name.name, r[name.name]], ...M.map(m => [m.name, roundFor(val(r, m), m)])])), config: tableConfig(name, M[0], [], n, M.slice(1)) },
                { rows: Math.min(n, 40) }, [], `one row per ${name.name}, one column per measure`, { answers: ['lookup', 'ranking', 'magnitude'], setup: TABLE_SETUP });
        }
    }

    // --- two categoricals + measure -------------------------------------------
    if (rule('grid', 'Two categoricals + one measure', [['no time axis', !t], ['exactly 1 measure', M.length === 1], ['2+ text columns', D.length >= 2 || (sig.hierarchy || sig.periodPair)]])) {
        const how = aggregationOf(m1);
        let treemapped = false;
        if (sig.hierarchy && m1.min >= 0 && how === 'sum' && (isVolume(m1) || ctx.intent === 'composition')) {
            treemapped = true;
            const { parent, child } = sig.hierarchy;
            const agg = aggregate(rows, [parent, child], m1, 'sum');
            push('Treemap.createBasic', 0.93, `${child.name} nests inside ${parent.name} — area per ${child.name}, grouped by ${parent.name}`,
                { data: agg.rows.map(({ keys: [g, c], value }) => ({ name: String(c), group: String(g), value })), config: {} },
                { cells: agg.rows.length, categories: parent.distinct }, [], `${agg.repeated ? 'summed per cell, ' : ''}mapped to { name: ${child.name}, group: ${parent.name}, value: ${m1.name} }`,
                { answers: ['composition', 'magnitude'] });
            const byChild = agg.rows.map(({ keys: [, c], value }) => ({ category: String(c), value })).sort((a, b) => b.value - a.value).slice(0, 20);
            push('Bar.createBasic', 0.76, `every ${child.name} ranked (its ${parent.name} in the tooltip)`,
                { data: byChild, config: {} }, { rows: byChild.length }, [], `mapped to { category: ${child.name}, value: ${m1.name} }, sorted desc`);
        }
        if (sig.periodPair && how !== undefined) {
            const { period, entity, values: [a, b] } = sig.periodPair;
            const by = new Map();
            for (const r of rows) {
                const e = r[entity.name];
                if (!by.has(e)) by.set(e, {});
                by.get(e)[String(r[period.name])] = val(r, m1);
            }
            const pairRows = [...by.entries()].filter(([, o]) => a in o && b in o).map(([e, o]) => ({ name: String(e), before: o[a], after: o[b] }));
            push('Slope.createBasic', 0.93, `${period.name} has two values (${a}, ${b}) for every ${entity.name} — the change per ${entity.name}`,
                { data: pairRows, config: { leftLabel: a, rightLabel: b } }, { rows: pairRows.length, periods: 2 }, [],
                `reshaped to { name: ${entity.name}, before: ${a}, after: ${b} }`, { answers: ['change'], show: 'individuals' });
            push('Dot.createDumbbell', 0.89, `the same change as gap-focused rows`,
                { data: pairRows.map(r => ({ name: r.name, start: r.before, end: r.after })), config: {} }, { rows: pairRows.length }, [],
                `reshaped to { name: ${entity.name}, start: ${a}, end: ${b} }`, { answers: ['change', 'deviation'], show: 'individuals' });
        }
        if (D.length >= 2) {
            const [d1, d2] = D.slice().sort((x, y) => y.distinct - x.distinct);
            const flowNames = D.some(d => /source|from|origin/i.test(d.name)) && D.some(d => /target|to|dest/i.test(d.name));
            if (flowNames) {
                const src = D.find(d => /source|from|origin/i.test(d.name));
                const tgt = D.find(d => /target|to|dest/i.test(d.name));
                const links = aggregate(rows, [src, tgt], m1, how || 'sum');
                const pairText = `${src.name} → ${tgt.name} pair`;
                push('Sankey.createBasic', 0.92, `${src.name} → ${tgt.name} + ${m1.name} reads as flow`,
                    { data: links.rows.map(({ keys: [x, y], value }) => ({ source: String(x), target: String(y), value })), config: {} },
                    { nodes: src.distinct + tgt.distinct, links: links.rows.length }, links.repeated ? [sumCaveat(pairText, m1)] : [],
                    `${links.repeated ? `${aggText(how || 'sum', m1, pairText, n, links.rows.length, 'links')}, ` : ''}mapped to { source: ${src.name}, target: ${tgt.name}, value: ${m1.name} }`);
            }
            if (how && !treemapped && !sig.periodPair) {
                const cells = aggregate(rows, [d1, d2], m1, how);
                const cellText = `${d1.name} × ${d2.name} cell`;
                const cellAgg = cells.repeated ? `${aggText(how, m1, cellText, n, cells.rows.length, 'cells')}, ` : '';
                push('Scatter.createHeatmap', 0.8, `2 categoricals (${d1.name} × ${d2.name}) + 1 measure — a value grid`,
                    { data: cells.rows.map(({ keys: [x, y], value }) => ({ x: String(x), y: String(y), value })), config: {} },
                    { points: d1.distinct * d2.distinct }, cells.repeated && how === 'sum' ? [sumCaveat(cellText, m1)] : [], `${cellAgg}mapped to { x: ${d1.name}, y: ${d2.name}, value: ${m1.name} }`);
                if (d1.distinct <= 8 && d2.distinct <= 4) {
                    const wide = new Map();
                    for (const { keys: [x, y], value } of cells.rows) {
                        const k = String(x);
                        if (!wide.has(k)) wide.set(k, { category: k });
                        wide.get(k)[String(y)] = value;
                    }
                    const keys = [...new Set(rows.map(r => String(r[d2.name])))];
                    push('Bar.createGrouped', 0.74, `both dimensions small (${d1.distinct} × ${d2.distinct}) — side-by-side bars with a shared baseline`,
                        { data: [...wide.values()], config: { keys, legend: true } }, { rows: d1.distinct, series: d2.distinct }, cells.repeated && how === 'sum' ? [sumCaveat(cellText, m1)] : [],
                        `${cellAgg}pivoted wide: one row per ${d1.name}, one column per ${d2.name}`);
                    if (how === 'sum' && m1.min >= 0) {
                        push('Bar.createStacked', isVolume(m1) ? 0.72 : 0.5, `each ${d1.name}'s total, split by ${d2.name}`,
                            { data: [...wide.values()], config: { keys, legend: true } }, { rows: d1.distinct }, ['stacking assumes the parts add up to a meaningful total'],
                            `${cellAgg}pivoted wide: one row per ${d1.name}, one column per ${d2.name}`, { answers: ['composition', 'magnitude'] });
                    }
                }
            }
        }
    }

    // --- entity + two temporal fields (interval) -----------------------------
    if (rule('gantt', 'Intervals: two temporal fields + a label', [['2+ temporal fields', sig.temporal.length >= 2], ['a name or dimension', name || dim]])) {
        const [ta, tb] = sig.temporal.slice().sort((a, b) => a.min - b.min);
        const label = name || dim;
        push('Bar.createGantt', 0.88, `two temporal fields (${ta.name}, ${tb.name}) per ${label.name} — intervals on a timeline`,
            { data: rows.map(r => ({ label: String(r[label.name]), start: val(r, ta), end: val(r, tb) })), config: {} },
            { rows: n }, [], `mapped to { label: ${label.name}, start: ${ta.name}, end: ${tb.name} }`);
    }

    return { candidates: out, trace };
}


/** Each category's share of the total, as ranked bars — composition past a donut's 6 slices. */
function shareBars(push, mapped, dim, m1, note) {
    const total = mapped.reduce((a, r) => a + (r.value || 0), 0);
    if (!(total > 0)) return;
    const shares = mapped.map(r => ({ category: r.category, value: r.value === null ? null : Math.round((1000 * r.value) / total) / 10 }))
        .sort((a, b) => (b.value ?? -1) - (a.value ?? -1));
    // A donut reads up to ~6 slices; past that the share bars lead.
    push('Bar.createBasic', mapped.length <= 6 ? 0.45 : 0.6, `each ${dim.name}'s share of total ${m1.name} (%), ranked — reads past a donut's 6 slices`,
        { data: shares.slice(0, 20), config: { valueFormat: v => `${v}%` } }, { rows: Math.min(shares.length, 20) },
        ['only if the values are parts of one whole — suggest() cannot verify that'], `${note ? `${note}, ` : ''}as % of the total, sorted desc`,
        { answers: ['composition'], show: 'summary' });
}

const TABLE_SETUP = "Tables need one-time registration: import { D3Table } from 'chart-factory/table'; ChartFactory.Table.register(D3Table);";

/** A value rounded for display in a table cell (the bar label is measured unformatted). */
function roundFor(v, f) {
    if (v === null || v === undefined || !Number.isFinite(v)) return v;
    const mag = Math.max(Math.abs(f.max || 0), Math.abs(f.min || 0), Math.abs(v));
    return mag >= 1000 ? Math.round(v) : mag >= 10 ? Math.round(v * 10) / 10 : Math.round(v * 100) / 100;
}

// Acronyms that stay upper case in a header ('gdp_per_capita' -> 'GDP per capita').
const ACRONYMS = new Set(['id', 'aov', 'arr', 'mrr', 'roi', 'roas', 'ctr', 'cvr', 'ltv', 'gdp', 'kpi', 'nps', 'sku', 'url', 'usd', 'eur', 'hr', 'era', 'ops', 'war', 'mph', 'utc', 'qa', 'ui', 'api']);
/** A field name as a sentence-case header: words split on _ - . and camelCase, first word capitalized, acronyms upper. */
function headerOf(name) {
    const words = String(name).replace(/([a-z0-9])([A-Z])/g, '$1 $2').split(/[\s_\-.]+/).filter(Boolean);
    return words.map((w, i) => {
        const lw = w.toLowerCase();
        if (ACRONYMS.has(lw) || (w.length > 1 && w === w.toUpperCase() && /[A-Z]/.test(w))) return w.toUpperCase();
        return i === 0 ? lw.charAt(0).toUpperCase() + lw.slice(1) : lw;
    }).join(' ');
}

/** A Table.createWithBars config: the label column, the bar column, and any extra columns the rows carry. */
function tableConfig(labelField, m, extras = [], k = 0, moreMeasures = []) {
    const columns = [
        { key: labelField.name, header: headerOf(labelField.name), className: 'primary-cell', sortable: true, sortType: 'text' },
        ...extras.slice(0, 3).map(e => ({ key: e.name, header: headerOf(e.name), sortable: true, sortType: 'text', className: 'secondary-cell' })),
        { key: m.name, header: headerOf(m.name), align: 'right', sortable: true, sortType: 'numeric', defaultSort: 'desc' },
        ...moreMeasures.slice(0, 4).map(x => ({ key: x.name, header: headerOf(x.name), align: 'right', sortable: true, sortType: 'numeric' })),
    ];
    // Display format: whole numbers past 1,000 (with separators), a percent
    // for a percent column, otherwise two decimals. The BAR column takes the
    // table's compact bar-label default (3.88M, 613K — the same as chart bar
    // ends) unless it is a percent.
    const fmtOf = f => (f.unit === '%' ? 'decimal' : (f.allInt || Math.abs(f.max) >= 1000) ? 'integer' : 'decimal2');
    for (const c of columns) {
        const f = [m, ...moreMeasures].find(x => x.name === c.key);
        if (f && (f !== m || f.unit === '%')) c.format = fmtOf(f);
    }
    // No colorScale: the table's default (flat neutral gray; gray up / muted red
    // down on a signed column) is the house look for in-cell bars.
    const cfg = { columns, barColumns: [{ key: m.name }] };
    if (k > 40) Object.assign(cfg, { maxRows: 25 });
    return cfg;
}

function twoPointRows(sortedRows, t, dim, m) {
    const periods = [...new Set(sortedRows.map(r => String(keyOf(r, t))))];
    if (periods.length !== 2) return null;
    const byGroup = groupBy(sortedRows, dim);
    const rows = [];
    for (const [g, rs] of byGroup) {
        if (rs.length !== 2) continue;
        rows.push({ name: String(g), before: val(rs[0], m), after: val(rs[1], m) });
    }
    return rows.length >= 2 ? rows : null;
}

// ---------------------------------------------------------------------------
// 5. Intent, show, affordances, audit
// ---------------------------------------------------------------------------

const INTENT_BONUS = 0.14, INTENT_MISS = 0.3, SHOW_BONUS = 0.08;

function scoreCandidates(cands, intent) {
    for (const c of cands) {
        const p = c.scoreParts;
        if (intent.value && intent.source !== 'assumed') p.intent = c.answers.includes(intent.value) ? INTENT_BONUS : -INTENT_MISS;
        if (intent.show && c.show && intent.show !== 'both') p.show = c.show === intent.show ? SHOW_BONUS : -SHOW_BONUS;
        c.score = Math.max(0, Math.min(1, Math.round((p.base + p.cardinality + p.intent + p.show + (intent.source === 'assumed' ? 0 : p.context || 0)) * 100) / 100));
    }
    return cands;
}

const GRAIN_ORDER = ['hour', 'day', 'week', 'month', 'quarter', 'year'];
const REGRAIN_TO = ['day', 'week', 'month', 'quarter', 'year'];
const GRAIN_DAYS = { hour: 1 / 24, day: 1, week: 7, month: 30.44, quarter: 91.31, year: 365.25 };

/** The UTC start of the `grain` bucket holding `ms` (the same buckets data.regrain uses). */
function grainStart(ms, grain) {
    const d = new Date(ms);
    const y = d.getUTCFullYear(), mo = d.getUTCMonth(), day = d.getUTCDate();
    if (grain === 'year') return Date.UTC(y, 0, 1);
    if (grain === 'quarter') return Date.UTC(y, Math.floor(mo / 3) * 3, 1);
    if (grain === 'month') return Date.UTC(y, mo, 1);
    if (grain === 'week') return Date.UTC(y, mo, day - ((d.getUTCDay() + 6) % 7));
    return Date.UTC(y, mo, day);
}

/** A date field's grain, from the median gap between its distinct values. */
function grainOfGap(gapMs) {
    if (!Number.isFinite(gapMs) || gapMs <= 0) return null;
    const days = gapMs / DAY_MS;
    return days < 0.9 ? 'hour' : days < 3 ? 'day' : days < 20 ? 'week' : days < 60 ? 'month' : days < 200 ? 'quarter' : 'year';
}

const isoDay = ms => new Date(ms).toISOString().slice(0, 10);

/** The time axis as plain facts: field, grain, span, the coarser grains data.regrain can roll it to, prior periods. */
function timeAffordance(sig, fields) {
    const t = sig.temporal[0];
    if (!t) return null;
    const yearGroup = sig.dimensions.find(d => d.yearGroup) || null;
    if (t.positionStandin) {
        // A year-over-year table: the within-year position is the axis, each year a series.
        const unit = UNIT_OF[positionWord(t.name)] || null;
        const years = yearGroup ? yearGroup.distinct : 0;
        return { field: t.name, grain: unit === 'doy' ? 'day' : unit, span: null, points: t.distinct,
            yearField: yearGroup ? yearGroup.name : null, years, regrainTo: [], hasPriorPeriod: years >= 2, yoyReady: years >= 2 };
    }
    if (t.yearStandin) {
        const n = t.periods || t.distinct;
        return { field: t.name, grain: 'year', span: { from: t.min, to: t.max, years: t.max - t.min + 1 },
            points: n, regrainTo: [], hasPriorPeriod: n >= 2, yoyReady: false };
    }
    const grain = grainOfGap(t.medianGapMs) || 'day';
    const days = (t.max - t.min) / DAY_MS + GRAIN_DAYS[grain];
    const years = Math.round((days / 365.25) * 100) / 100;
    // data.regrain reads Dates and ISO strings; other written formats need data.toDate first.
    const profile = fields.find(f => f.name === t.name) || t;
    const fmt = profile.dateFormat ? profile.dateFormat.id : null;
    const regrainable = !sig.composedFrom && (fmt === null || fmt === 'iso' || fmt === 'year-month');
    const regrainTo = !regrainable ? [] : REGRAIN_TO.filter(g => GRAIN_ORDER.indexOf(g) > GRAIN_ORDER.indexOf(grain) && grainStart(t.max, g) > grainStart(t.min, g));
    // Year over year needs the same within-year position in two years: a
    // sub-year grain over a span of about a year or more.
    const yoyReady = GRAIN_ORDER.indexOf(grain) < GRAIN_ORDER.indexOf('year') && (t.max - t.min) / DAY_MS >= 362;
    const out = { field: t.name, grain, span: { from: isoDay(t.min), to: isoDay(t.max), years }, points: t.distinct,
        regrainTo, hasPriorPeriod: t.distinct >= 2, yoyReady };
    if (t.repeats) out.rowsPerPoint = Math.round((sig.rowCount / t.distinct) * 10) / 10;
    if (fmt && !regrainable && !sig.composedFrom) out.format = fmt;
    if (sig.composedFrom) out.composedFrom = sig.composedFrom.slice();
    return out;
}

/**
 * Plain facts about the rows that an agent writes its next questions from:
 * the time axis, the dimensions (ordered or not, what nests under what), the
 * measures (how each aggregates), what is missing, and which intents a
 * candidate actually answers. No questions and no taste: the caller asks.
 */
function affordancesFor(sig, fields, scored) {
    const hier = sig.hierarchy;
    const dims = sig.dimensions.filter(d => !d.yearGroup).map(d => {
        const o = { field: d.name, distinct: d.distinct, ordered: !!d.ordered };
        if (hier && hier.parent.name === d.name) o.hierarchyChild = hier.child.name;
        if (hier && hier.child.name === d.name) o.hierarchyParent = hier.parent.name;
        return o;
    });
    if (sig.nameField) dims.push({ field: sig.nameField.name, distinct: sig.nameField.distinct, ordered: !!sig.nameField.ordered, rowLabel: true });
    const measures = sig.measures.map(m => {
        const kind = m.measureKind || measureKind(m);
        const o = { field: m.name, kind, min: m.min, max: m.max };
        const unit = m.unit || (m.currency ? 'currency' : null) || (kind === 'ratio' && m.min >= 0 && m.max <= 1 && !m.allInt ? 'fraction' : null);
        if (unit) o.unit = unit;
        if (kind === 'ratio' && m.parts) o.parts = { num: m.parts.num.name, den: m.parts.den.name, scale: m.parts.scale };
        if (isStock(m)) o.stock = true;
        return o;
    });
    const time = timeAffordance(sig, fields);
    const missing = [];
    if (!time) {
        const stamp = fields.find(f => f.kind === 'temporal' && f.distinct === 1);
        missing.push(stamp ? `one period only (${stamp.name} is the same in every row)` : 'no date column');
    } else if (time.points === 1) missing.push('one period only');
    else if (time.span && time.grain !== 'year' && !time.yoyReady) missing.push(`no prior year (${time.field} spans under a year)`);
    if (!measures.length) missing.push('no numeric measure');
    else if (measures.length === 1) missing.push('no second measure');
    const cats = dims.filter(d => !d.rowLabel);
    const label = dims.find(d => d.rowLabel);
    if (!cats.length) missing.push(label ? `no grouping dimension (${label.field} names each row)` : 'no category dimension');
    // One unordered category and no other text column that could nest under it.
    const only = cats.length === 1 ? cats[0] : null;
    if (only && !only.ordered && !only.hierarchyChild && !idNamed(only.field) && !dims.some(d => d !== only && d.distinct < sig.rowCount)) missing.push(`no level below ${only.field}`);
    if (!time && sig.primaryDim && !sig.primaryDim.yearGroup && sig.rowsPerGroup <= 1.0001) missing.push(`one row per ${sig.primaryDim.name}: no rows behind each value`);
    for (const m of measures) if (m.kind === 'ratio' && !m.parts) missing.push(`${m.field} is a ratio with no numerator/denominator columns: it cannot be re-aggregated exactly`);
    const intentsAnswerable = intentNames.filter(i => scored.some(c => (c.answers || []).includes(i)));
    return { time, dimensions: dims, measures, missing, intentsAnswerable };
}

/** Per field: what it was read as, the role it got, and why. Nothing disappears unexplained. */
function auditFields(fields, sig) {
    const has = (arr, f) => arr.some(x => x.name === f.name);
    return fields.map(f => {
        const T = sig.temporal.find(x => x.name === f.name);
        const m = sig.measures.find(x => x.name === f.name);
        let role, note = null;
        if (T) role = T.yearStandin ? (T.periods === 2 ? 'period pair (2 years)' : 'time axis (year column)') : T.positionStandin ? 'time axis (position within the year)' : 'time axis';
        else if (sig.primaryDim && sig.primaryDim.name === f.name) role = sig.primaryDim.yearGroup ? 'grouping: one series per year' : 'grouping dimension';
        else if (has(sig.dimensions, f)) role = 'dimension';
        else if (m) role = `measure (${m.measureKind}${m.parts ? `, = ${m.parts.num.name} / ${m.parts.den.name}` : ''}${m.ordinal && m.ordinal.named ? ', or an ordered category' : ''})`;
        else if (sig.nameField && sig.nameField.name === f.name) role = 'row label';
        else if (f.kind === 'numeric') { role = 'not charted'; note = 'an identifier, or a year already carried by the date column'; }
        else if (f.kind === 'id') { role = 'not charted'; note = 'unique per row: a label'; }
        else if (f.kind === 'empty') { role = 'not charted'; note = 'empty'; }
        else if (f.kind === 'style' || f.kind === 'media') { role = 'not charted'; note = f.kind === 'style' ? 'colors: pass as colorAccessor to style the marks' : 'image or link URLs: pass as imageAccessor for image marks'; }
        else role = 'not charted';
        const parsedAs = f.kind === 'temporal' ? `date${f.dateFormat ? ` (${f.dateFormat.id}${f.dateFormat.ambiguous ? ', ambiguous day/month — read month-first' : ''})` : ''}`
            : f.kind === 'numeric' ? `number${f.unit ? ` (${f.unit})` : ''}${f.written ? ', written with separators or a unit' : ''}` : f.kind;
        return { field: f.name, parsedAs, role, note, distinct: f.distinct, nulls: f.nulls };
    });
}

// ---------------------------------------------------------------------------
// 6. Also consider: every builder whose data contract fits the rows
// ---------------------------------------------------------------------------

/**
 * The signature roles of a read table, in the vocabulary of the metadata's
 * `signature` (metadata/README.md): counts of time axes, measures and text
 * dimensions (a row-name column counts as one), the row count, and the
 * structural readings it holds.
 */
function signatureRoles(rows, sig) {
    const t = sig.temporal[0] || null;
    const M = sig.measures, dim = sig.primaryDim, m1 = M[0];
    const label = sig.nameField || dim;
    const readings = new Set();
    const add = (r, on) => { if (on) readings.add(r); };
    add('pairs', sig.pair || sig.periodPair || (t && (t.periods === 2 || t.distinct === 2)));
    add('bounds', sig.bounds);
    add('hierarchy', sig.hierarchy);
    add('stages', !t && M.length === 1 && dim && funnelReading(rows, dim, m1));
    add('flow', sig.dimensions.some(d => /source|from|origin/i.test(d.name)) && sig.dimensions.some(d => /target|to|dest/i.test(d.name)));
    add('ranks', t && dim && m1 && ((/(^|_)rank(ing)?s?($|_)/i.test(m1.name) && m1.allInt && m1.min >= 1) || ranksByStructure(rows, t, dim, m1)));
    add('scale', sig.scale);
    add('percentiles', M.filter(m => /^p\d{1,3}$/i.test(m.name)).length >= 3);
    if (M.length === 1 && m1.allInt && m1.min >= 0) {
        const units = rows.reduce((a, r) => a + (numberOf(r[m1.name]) || 0), 0);
        add('units', units >= 10 && units <= 300);
    }
    add('signed', M.some(m => m.min < 0 && m.max > 0));
    add('ordered', label && label.ordered);
    const maxes = M.map(m => m.max);
    add('sameScale', !sig.bounds && M.length >= 2 && M.every(m => m.min >= 0) && Math.min(...maxes) > 0 && Math.max(...maxes) <= 2.5 * Math.min(...maxes));
    add('parts', !sig.bounds && M.length >= 1 && scaleGroups(M).length === 1 && M.every(m => (m.measureKind || measureKind(m)) === 'additive' && !isStock(m) && m.min >= 0));
    add('daily', sig.daily);
    // A row-name column counts as a dimension when it is the rows' label (a
    // team, a product), not a row id beside a grouping column (order_id
    // beside country).
    const nameDim = sig.nameField && (sig.dimensions.length === 0 || sig.rowCount <= 30) ? 1 : 0;
    return {
        temporal: sig.temporal.length, measures: M.length,
        dimensions: sig.dimensions.length + nameDim,
        rows: sig.rowCount, readings,
    };
}

const inRange = (n, [lo, hi]) => n >= lo && (hi === null || n <= hi);
function fitsSignature(specs, roles) {
    return specs.some(sp => inRange(roles.temporal, sp.temporal) && inRange(roles.measures, sp.measures) &&
        inRange(roles.dimensions, sp.dimensions) && (!sp.rows || inRange(roles.rows, sp.rows)) &&
        (sp.requires || []).every(r => roles.readings.has(r)));
}

/**
 * Builders whose data contract fits the rows (metadata `signature`) but that
 * no rule emitted: the other options the guide lists, unscored and
 * unrendered, so an agent sees every fitting chart. A primitive counts as
 * emitted when it or any of its presets was; a preset appears only when it
 * declares a signature of its own (a different data shape).
 */
function alsoConsiderFor(rows, sig, cands) {
    const emitted = new Set();
    for (const c of cands) {
        for (const b of [c.builder, c.metaBuilder, ...(c.variants || []).map(v => v.builder)]) {
            if (!b || !BUILDER_METADATA[b]) continue;
            emitted.add(b);
            if (BUILDER_METADATA[b].primitive) emitted.add(BUILDER_METADATA[b].primitive);
        }
    }
    const roles = signatureRoles(rows, sig);
    const out = [];
    for (const [builder, m] of Object.entries(BUILDER_METADATA)) {
        if (!m.signature || emitted.has(builder) || !fitsSignature(m.signature, roles)) continue;
        out.push({ builder, whenToUse: m.guide.whenToUse, notFor: m.guide.notFor, fit: 'shape' });
    }
    return out;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * @param {Array<object>} rows  Flat row objects (CSV-shaped is fine: numbers
 *   written as '1,240', '$3.2M' or '4.7%' and dates as '4/15/2026', '2024-07'
 *   or 'Jan 2025' are read as numbers and dates).
 * @param {object} [options]
 *   intent:  'magnitude' | 'ranking' | 'trend' | 'change' | 'composition' |
 *            'distribution' | 'relationship' | 'deviation' | 'flow' | 'lookup'
 *   ask:     a plain-English question — parsed for intent, show and the fields it names
 *   show:    'summary' | 'individuals' | 'both' — the aggregate or the data points
 *   exclude: field names to leave out
 *   limit:   max candidates returned (default 5)
 *   factory: the ChartFactory create() resolves against (injected; tests only)
 * @returns {{ fields, signature, intent, candidates, alternatives, alsoConsider,
 *             affordances, shapeCandidates, questions, audit, trace }}
 *   alsoConsider: [{ builder, whenToUse, notFor, fit: 'shape' }] — builders
 *            whose data contract fits these rows (metadata `signature`) that
 *            no rule emitted; unscored and unrendered — the other options
 *            the guide lists, for the caller (an agent) to judge.
 *   affordances: { time, dimensions, measures, missing, intentsAnswerable } —
 *            plain facts about the rows (affordancesFor) that the caller
 *            writes its next questions from. suggest never writes them.
 */
export function makeSuggest(defaultFactory) {
    return function suggest(rows, options = {}) {
        const { limit = 5, factory = defaultFactory(), exclude = [] } = options;
        if (!Array.isArray(rows) || rows.length === 0) {
            console.warn('ChartFactory.suggest: rows must be a non-empty array of objects');
            return { fields: [], signature: null, intent: null, candidates: [], alternatives: [], alsoConsider: [], affordances: null, shapeCandidates: [], questions: [], audit: [], trace: [] };
        }
        const input = exclude.length ? rows.map(r => Object.fromEntries(Object.entries(r || {}).filter(([k]) => !exclude.includes(k)))) : rows;
        const fields = profileFields(input);
        const intent = resolveIntent(options, fields);
        let { signature, raw, trace, ctx } = pipeline(input, fields, intent);
        let readRows = input;
        // A year column beside a within-year position that is NOT a
        // year-over-year table (other columns key the rows, or the years run
        // on): the two together are one date. Compose it, and the rows get
        // a real time axis instead of the month plotted as a measure.
        const composed = composeTime(input, signature, fields);
        if (composed) {
            const sub = pipeline(composed.rows, profileFields(composed.rows), intent);
            for (const c of sub.raw) c.transform = c.transform ? `${composed.note}; ${c.transform}` : composed.note;
            sub.trace.unshift({ id: 'compose', title: `Compose ${composed.parts.join(' + ')} into one date`, on: true, gates: [{ label: composed.note, pass: true }] });
            ({ signature, raw, trace, ctx } = sub);
            readRows = composed.rows;
            signature.composedFrom = composed.parts;
        }
        // A question that is not about time ("how much per region", "what
        // share", "who is above average") asked of rows that carry a date:
        // collapse the date away first, then answer it per category.
        if (intent.value && COLLAPSE_INTENTS.has(intent.value) && signature.temporal.length && signature.measures.length) {
            const t = signature.temporal[0];
            const m = signature.measures[0];
            const how = aggregationOf(m);
            const named = signature.dimensions.filter(d => intent.subject.includes(d.name) && !d.yearGroup);
            const keep = named.length ? named : signature.primaryDim && !signature.primaryDim.yearGroup ? [signature.primaryDim] : [];
            if (how && keep.length) {
                const agg = aggregate(input, keep, m, how);
                const collapsed = agg.rows.map(e => Object.fromEntries([...keep.map((d, i) => [d.name, e.keys[i]]), [m.name, e.value]]));
                const sub = pipeline(collapsed, profileFields(collapsed), intent);
                // The question names no time, so the over-time charts answer a
                // follow-up ("…and how did it move?"), not the question.
                const timeWords = /\b(time|trend|over|since|daily|weekly|monthly|quarterly|yearly|by (day|week|month|quarter|year|date)|history|change|grew|growth)\b/i;
                if (options.ask && !timeWords.test(options.ask)) for (const c of raw) if (c.rule === 'trend' || c.rule === 'panel') {
                    c.scoreParts.context = -0.3;
                    c.caveats.push(`the question isn't about time — this answers the follow-up "how did it move over ${t.name}?"`);
                }
                const prefix = `collapsed over ${t.name}: ${aggText(how, m, keep.map(d => d.name).join(' × '), input.length, collapsed.length)}`;
                for (const c of sub.raw) {
                    c.transform = c.transform ? `${prefix}; ${c.transform}` : prefix;
                    c.rule = `collapse:${c.rule}`;
                    raw.push(c);
                }
                ctx.questions.push(...sub.ctx.questions);
                trace.push({ id: 'collapse', title: `Collapse ${t.name} for a '${intent.value}' question`, on: true,
                    gates: [{ label: `intent is ${intent.value}`, pass: true }, { label: `kept ${keep.map(d => d.name).join(', ')}`, pass: true }] });
            }
        }
        const finish = c => ({
            ...c,
            create(selector, overrides = {}) { return createCandidate(factory, c, selector, overrides); },
        });
        const byScore = (a, b) => b.score - a.score;
        // Shape-only ranking first (kept visible when an intent re-ranks).
        const shapeScored = scoreCandidates(raw.map(c => ({ ...c, scoreParts: { ...c.scoreParts } })), { value: null, show: null, source: 'assumed' }).sort(byScore);
        const scored = scoreCandidates(raw, intent).sort(byScore);
        const candidates = scored.slice(0, limit).map(finish);
        // The best candidate for each other intent the data could serve.
        const alternatives = [];
        for (const name of intentNames) {
            if (name === intent.value) continue;
            const best = scored.find(c => c.answers[0] === name || (c.answers.includes(name) && !candidates.slice(0, 1).some(x => x.builder === c.builder)));
            if (best && !alternatives.some(a => a.builder === best.builder && a.rule === best.rule)) alternatives.push({ intent: name, builder: best.builder, score: best.score, why: best.why[0] });
        }
        const questions = ctx.questions.slice();
        if (intent.value && intent.source !== 'assumed' && !scored.some(c => c.answers.includes(intent.value))) {
            const need = { trend: 'a date or period column', change: 'two periods to compare', relationship: 'a second measure', flow: 'a source and a target, or ordered stages', distribution: 'row-level data (not totals)', composition: 'an additive measure that is never negative' }[intent.value];
            questions.unshift({ field: null, ask: `nothing here answers '${intent.value}'${need ? ` — it needs ${need}` : ''}`, intentGap: intent.value });
        }
        for (const f of fields) {
            if (f.dateFormat && f.dateFormat.ambiguous) questions.push({ field: f.name, ask: `${f.name}: are these month/day or day/month dates? (read month-first)` });
        }
        if (candidates.length === 0) {
            console.warn('ChartFactory.suggest: no signature rule matched — see docs/chart-guide.md to choose by hand');
        }
        return {
            fields, signature, intent, candidates,
            alternatives: alternatives.slice(0, 6),
            alsoConsider: alsoConsiderFor(readRows, signature, raw),
            affordances: affordancesFor(signature, fields, scored),
            shapeCandidates: intent.source === 'assumed' ? [] : shapeScored.slice(0, limit).map(c => ({ builder: c.builder, score: c.score })),
            questions, audit: auditFields(fields, signature), trace,
        };
    };
}

const UNIT_OF = { month: 'month', mo: 'month', mnth: 'month', mth: 'month', quarter: 'quarter', qtr: 'quarter', q: 'quarter', week: 'week', wk: 'week', day: 'day', doy: 'doy', dayofyear: 'doy' };

/** The month index (1–12) a calendar month name stands for, or null. */
const monthOfName = v => {
    const m = /^(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)/i.exec(String(v).trim());
    return m ? ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'].indexOf(m[1].toLowerCase()) + 1 : null;
};

/**
 * A year column beside within-year position columns (month, quarter, week,
 * day, a month NAME), when the rows are not a year-over-year table: the
 * columns together are one date. Returns { rows, note, parts } with a
 * composed ISO date column replacing them, or null.
 */
function composeTime(rows, sig, fields) {
    if (sig.temporal.some(t => !t.yearStandin && !t.positionStandin)) return null;     // a real date already
    if (sig.temporal.some(t => t.positionStandin)) return null;                        // year-over-year applies
    const numeric = fields.filter(f => f.kind === 'numeric');
    const year = (sig.temporal[0] && sig.temporal[0].yearStandin ? sig.temporal[0] : null) ||
        numeric.find(f => f.allInt && f.min >= 1500 && f.max <= 2100 && YEAR_NAME.test(f.name));
    if (!year) return null;
    const pos = numeric.filter(f => f !== year && f.allInt).map(f => ({ f, unit: UNIT_OF[positionWord(f.name)] })).filter(x => x.unit);
    const monthName = fields.find(f => f.kind === 'categorical' && calendarNames(rows, f.name) && rows.filter(r => present(r[f.name])).every(r => monthOfName(r[f.name])));
    const month = pos.find(x => x.unit === 'month') || (monthName ? { f: monthName, unit: 'month', named: true } : null);
    const quarter = pos.find(x => x.unit === 'quarter');
    const week = pos.find(x => x.unit === 'week' && !/month/i.test(x.f.name));
    const dayish = pos.filter(x => x.unit === 'day' || x.unit === 'doy');
    const dow = dayish.find(x => /week/i.test(x.f.name) && x.f.min >= 0 && x.f.max <= 7);
    const dom = dayish.find(x => x !== dow && /month/i.test(x.f.name) || (x !== dow && x.unit === 'day' && month && x.f.max <= 31));
    const doy = dayish.find(x => x !== dow && x !== dom);
    const pick = month || week || quarter || doy;
    if (!pick) return null;
    // A text column renaming the position one-to-one (a survey question
    // beside its number q, a promo code beside its month) makes the position
    // an attribute of that entity, not a point in the year.
    if (!pick.named && sig.dimensions.concat(sig.idFields).some(d => d.kind === 'categorical' && !calendarNames(rows, d.name) && renames(rows, pick.f.name, d.name))) return null;
    const range = { month: [1, 12], quarter: [1, 4], week: [1, 54], doy: [1, 366], day: [1, 366] }[pick.unit];
    const posOf = r => (pick.named ? monthOfName(r[pick.f.name]) : numberOf(r[pick.f.name]));
    const zeroBased = !pick.named && pick.f.min === 0;
    const inRange = v => v !== null && v >= range[0] - (zeroBased ? 1 : 0) && v <= range[1] - (zeroBased ? 1 : 0);
    // Rows outside the unit's range are allowed only as SUBTOTALS: a
    // "quarter 5" row whose measures equal the sum of its year's quarters.
    // Anything else out of range (a 13th fiscal month) means it is no position.
    const outside = rows.filter(r => !inRange(posOf(r)));
    if (outside.length > 0.25 * rows.length) return null;
    if (outside.length) {
        const ms = sig.measures.filter(m => m !== pick.f && m.name !== year.name && !UNIT_OF[positionWord(m.name)] && !(yearish(m) && YEAR_NAME.test(m.name)));
        const subtotal = r => ms.length > 0 && ms.every(m => {
            const v = numberOf(r[m.name]);
            const sum = rows.filter(o => o !== r && inRange(posOf(o)) && numberOf(o[year.name]) === numberOf(r[year.name]))
                .reduce((a, o) => a + (numberOf(o[m.name]) || 0), 0);
            return v !== null && Math.abs(v - sum) <= 0.01 * Math.max(Math.abs(sum), 1);
        });
        if (!outside.every(subtotal)) return null;
    }
    const used = new Set([year.name, pick.f.name]);
    if (month && dom) used.add(dom.f.name);
    if (week && dow && pick === week) used.add(dow.f.name);
    // Columns that only re-express a composed part (a quarter beside the
    // month, a week of the month, the month's name) go too.
    const extras = pos.filter(x => !used.has(x.f.name) && x !== doy).map(x => x.f.name)
        .concat(fields.filter(f => f.kind === 'categorical' && calendarNames(rows, f.name)).map(f => f.name))
        .filter(n => !used.has(n));
    const name = `${year.name}_${pick.named ? 'month' : pick.f.name}`;
    const out = [];
    let dropped = 0;
    for (const r of rows) {
        const y = numberOf(r[year.name]);
        let p = posOf(r);
        if (y === null || !inRange(p)) { dropped++; continue; }
        if (zeroBased) p += 1;
        let ms;
        if (pick.unit === 'month') ms = Date.UTC(y, p - 1, used.has(dom && dom.f.name) ? (numberOf(r[dom.f.name]) || 1) : 1);
        else if (pick.unit === 'quarter') ms = Date.UTC(y, (p - 1) * 3, 1);
        else if (pick.unit === 'week') ms = Date.UTC(y, 0, 1) + ((p - 1) * 7 + (used.has(dow && dow.f.name) ? Math.max(0, (numberOf(r[dow.f.name]) || 1) - 1) : 0)) * DAY_MS;
        else ms = Date.UTC(y, 0, 1) + (p - 1) * DAY_MS;
        const row = {};
        for (const [k, v] of Object.entries(r)) if (!used.has(k) && !extras.includes(k)) row[k] = v;
        row[name] = new Date(ms).toISOString().slice(0, 10);
        out.push(row);
    }
    const parts = [...used];
    const notes = [`composed ${parts.join(' + ')} into a date (${name})`];
    if (extras.length) notes.push(`dropped ${extras.join(', ')} (parts of the same date)`);
    if (dropped) notes.push(`left out ${dropped} subtotal rows (outside the ${pick.unit} range, each the sum of its year)`);
    return { rows: out, parts, note: notes.join('; ') };
}

const COLLAPSE_INTENTS = new Set(['magnitude', 'ranking', 'composition', 'deviation', 'lookup', 'distribution']);

/** profile → signature (+ the ask's subject first) → rules, for one table of rows. */
function pipeline(input, fields, intent) {
    const signature = enrichSignature(input, fields, buildSignature(input, fields));
    if (intent.subject.length) {
        const rank = f => { const i = intent.subject.indexOf(f.name); return i < 0 ? 99 : i; };
        signature.measures.sort((a, b) => rank(a) - rank(b));
        const named = signature.dimensions.filter(d => intent.subject.includes(d.name)).sort((a, b) => rank(a) - rank(b))[0];
        if (named && !(signature.primaryDim && signature.primaryDim.yearGroup)) {
            signature.primaryDim = named;
            signature.rowsPerGroup = input.length / named.distinct;
        }
    }
    const ctx = { intent: intent.value, questions: [], rule: null };
    const { candidates: raw, trace } = suggestCandidates(input, signature, ctx);
    return { signature, raw, trace, ctx };
}

let tableIds = 0;
function createCandidate(factory, c, selector, overrides) {
    if (c.builder === 'facet') {
        const chart = { ...c.config.chart, config: { ...c.config.chart.config, ...overrides } };
        return factory.facet(selector, { ...c.config, data: c.data, chart });
    }
    const [family, method] = c.builder.split('.');
    if (family === 'Table') {
        let table;
        // Table selectors are element ids (the factory adds the '#').
        let target = selector;
        if (typeof selector === 'string' && selector.startsWith('#')) target = selector.slice(1);
        else if (selector && selector.nodeType === 1) {
            if (!selector.id) selector.id = `suggest-table-${++tableIds}`;
            target = selector.id;
        }
        try { table = factory.Table[method](target, { ...c.config, ...overrides }); }
        catch (e) { throw new Error(`ChartFactory.suggest: ${c.builder} — ${e.message} (${TABLE_SETUP})`); }
        if (table && typeof table.render === 'function') table.render(c.data);
        return table;
    }
    return factory[family][method](selector, { data: c.data, ...c.config, ...overrides });
}
