/**
 * D3 Chart Factory - Unified chart creation system
 *
 * Charts fill their container by default and re-render responsively.
 *
 * ES module source. The browser IIFE bundle (dist/chart-factory.js) is
 * generated with `npm run build` and exposes window.ChartFactory using the
 * page's global d3.
 *
 * @requires d3 v7+ (peer dependency)
 * @see docs/API.md for the complete per-builder configuration reference
 */

import * as d3 from 'd3';
import { createTextMeasurer, formatMarkValue, formatTooltipValue, TooltipManager } from './d3-base.js';
import { BUILDER_METADATA } from './builder-metadata.generated.mjs';
import { data } from './d3-data.js';
import { palettes, getPalette, paletteType, paletteRamp, themeInterpolator } from './palettes.js';
import { makeSuggest } from './d3-suggest.js';
import { makeCritique } from './d3-critique.js';

// ============================================
// Utility Functions
// ============================================

function getCSSVar(name, fallback = '') {
    const value = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    return value || fallback;
}

// Unique-per-instance suffixes for SVG def ids (clipPaths, gradients,
// masks, filters). Several charts can share one document (React mounts,
// dashboards) and url(#...) resolves to the FIRST matching id in the
// document — colliding ids let one chart's defs clip or paint another's
// marks. Salt + counter rather than Math.random so seeded-RNG test runs
// draw nothing extra from the sequence.
// colorScheme configs accept a d3 interpolator function OR its name as a
// string ('YlOrRd', 'viridis', 'interpolateYlGnBu') so canonical configs
// stay fully serializable (registry entries, JSON configs, AI output).
// Named schemes and the builder defaults (always d3 built-ins) re-anchor
// for the dark theme (themeInterpolator: lightness inverted, brighter =
// more); a function the caller passes is theirs and is used as-is.
function resolveColorScheme(scheme, fallback) {
    if (typeof scheme === 'function') return scheme;
    if (typeof scheme === 'string' && scheme.length) {
        // 1) d3 built-in interpolator by name (e.g. 'YlOrRd', 'viridis').
        const name = scheme.startsWith('interpolate')
            ? scheme
            : 'interpolate' + scheme[0].toUpperCase() + scheme.slice(1);
        if (typeof d3[name] === 'function') return themeInterpolator(d3[name]);
        // 2) a Chart Factory sequential/diverging/alert palette name -> an
        // interpolator over its (dark-re-anchored) ramp. Categorical palettes
        // are not gradients, so they fall through to the warning.
        const ramp = paletteType(scheme) !== 'categorical' ? paletteRamp(scheme) : undefined;
        if (ramp) return d3.interpolateRgbBasis(ramp);
        console.warn(`ChartFactory: unknown colorScheme '${scheme}' — using the builder default.`);
    }
    return themeInterpolator(fallback);
}

const DEF_ID_SALT = Date.now().toString(36);
let defIdSeq = 0;
function uniqueDefId() {
    return DEF_ID_SALT + '-' + (++defIdSeq);
}

// Interactive-legend emphasis (universal, wrapper-level): series-bearing
// elements carry a `data-series="<ordinal>"` attribute that lines up with
// the legend item order (category-coloured marks carry the same ordinal as
// `data-legend-index` — tagLegendMarks). Highlighting series `active` dims
// every element whose ordinal differs to --legend-dim-opacity; `active ==
// null` clears. A mark that belongs to several legend items (a Sankey link
// touches two nodes) lists them space-separated: `data-series="3 7"`.
// One implementation for every builder that emits the marker — builders
// without it simply don't respond (graceful).
const EMPHASIS_MARKS = '[data-series], [data-legend-index]';
function markOrdinals(el) {
    const raw = el.getAttribute('data-series') ?? el.getAttribute('data-legend-index');
    return String(raw).split(' ').map(Number);
}
function applySeriesEmphasis(rootEl, active) {
    if (!rootEl) return;
    const svg = rootEl.querySelector(':scope > svg') || rootEl.querySelector('svg');
    if (!svg) return;
    const clear = active === null || active === undefined;
    if (clear) {
        // Only marks a previous emphasis touched carry an inline opacity.
        svg.querySelectorAll(EMPHASIS_MARKS).forEach(el => {
            if (el.style.opacity !== '') el.style.opacity = '';
        });
        return;
    }
    const dim = getCSSVarNumber('--legend-dim-opacity', 0.18);
    svg.querySelectorAll(EMPHASIS_MARKS).forEach(el => {
        const on = markOrdinals(el).includes(active);
        el.style.transition = 'opacity 0.15s';
        el.style.opacity = on ? '' : dim;
    });
}

// Legend toggle (interactive legends remove a series on click): the
// wrapper passes the hidden series' ids to the builder as the internal
// `__hiddenSeries` key. A builder that supports removal assigns its colours
// over the FULL set first (a series keeps its colour when others leave),
// drops the hidden series BEFORE computing domains / stacks / layout, keeps
// its marks' data-series ordinals at their full-set positions, and reports
// the full set as `legendSeries: [{ id, label, color }]`. A builder whose
// legend keys something removal would misstate (a waterfall's kinds, a
// Likert scale's levels) reports `legendRemovable: false` or no
// legendSeries at all: its legend highlights on hover only.
function hiddenSeriesSet(opts) {
    const h = opts && opts.__hiddenSeries;
    return Array.isArray(h) && h.length ? new Set(h.map(String)) : null;
}
/** `list` without its hidden members — never empty: when every member is
 *  hidden (a setData that left only hidden series) the full list draws. */
function visibleSeries(list, idOf, hidden) {
    if (!hidden) return list;
    const kept = list.filter((x, i) => !hidden.has(String(idOf(x, i))));
    return kept.length ? kept : list;
}
/** `{ legendSeries }` for a keys-based builder: every key, its display
 *  label and the colour its scale assigns. */
function keyLegendSeries(allKeys, labels, colorOf) {
    return {
        legendSeries: allKeys.map(k => ({
            id: String(k),
            label: labels && labels[k] !== undefined ? labels[k] : k,
            color: colorOf(k)
        }))
    };
}

function getCSSVarNumber(name, fallback) {
    // NaN-check, not ||: a token explicitly set to 0 (e.g. no stroke, no
    // stagger) is a real value, not "unset".
    const value = parseFloat(getCSSVar(name, ''));
    return Number.isNaN(value) ? fallback : value;
}

/**
 * Text color for a label painted ON a filled mark (treemap cell, funnel bar).
 * Deliberately theme-INDEPENDENT: contrast is against the fill, and a light
 * cell needs dark text in dark mode too. This is the one sanctioned place
 * for literal black/white in the factory — everything else reads a token.
 */
function contrastTextOn(fill) {
    return (d3.hsl(fill).l || 0) < 0.62 ? '#ffffff' : '#111827';
}

// Row-key alias (friction-log): categorical builders read `category`, the
// donut reads `label` — with these fallbacks, rows keyed either way work in
// both places. An explicit *Accessor always wins; only the DEFAULTS alias.
const categoryOrLabel = d => (d && d.category !== undefined ? d.category : d && d.label);
const labelOrCategory = d => (d && d.label !== undefined ? d.label : d && d.category);

// Fit a per-row label font to the space a dense row layout leaves it: the
// token size while rows are roomy, scaling down with the row below that,
// never under `min` px (smaller is unreadable — callers hide instead).
function fitRowFont(basePx, availablePx, min = 8) {
    return Math.min(basePx, Math.max(min, Math.floor(availablePx)));
}

// ============================================
// Builder presets
// ============================================
//
// A PRIMITIVE owns a data contract; an encoding variant over the same
// contract is a named PRESET over an explicit mode option; a name that hides
// two data contracts is split. A preset is one config over a primitive,
// kept as a name because named variants are the selection vocabulary
// (docs/line-primitives.md):
//
//   preset(selector, config) = primitive(selector, { ...defaults, ...mapConfig(config) })
//
// A caller key always wins over `defaults`; `undefined` never overrides one.
// The responsive wrapper wraps a preset exactly like a primitive — it is a
// plain `create*` method on the raw family object — so a preset validates
// against its OWN metadata (the primitive's cells and options, adjusted by
// the preset's `universal` / `pins` / `dataShape` — metadata/README.md),
// gets its own states / link / brush lifecycle, and returns the primitive's
// result shape untouched.
//
// A preset applies a CONFIG and nothing else: it never accepts an alias
// spelling of a primitive option. The only keys of its own it may read are
// the ones that express a different DATA SHAPE — createCumulativeVsMoving's
// flat rows with two value columns, where the primitive takes `series[]`.
//
//   factory          the RAW family object (LineChartFactory), not the wrapped one
//   primitiveMethod  method name on that object ('createBasic')
//   name             'Line.createSmoothed' — surfaces in builder-labelled warnings
//   defaults         config applied UNDER the caller's; exactly the metadata's
//                    `preset` JSON (the family specs render against that field,
//                    so the two cannot drift)
//   mapConfig        (config) => config — derive hook, run BEFORE the merge on
//                    the caller's original keys (plus the wrapper's injections,
//                    which must pass through). Two uses: derive the primitive's
//                    config from the preset's own (data-shape) keys, or supply
//                    a default that cannot be a JSON constant — a live token
//                    read, a formatter closure. Such a default is set only
//                    when the caller left that key undefined, so caller-wins
//                    still holds. A preset with a mapConfig is
//                    `computed: true` in its metadata, and a primitive key its
//                    mapConfig always overrides is listed there under `pins`.
//
// The merged config re-runs the alias / field-accessor normalization so
// defaults and mappings may use string accessors ('value') and the universal
// alias spellings.
const PRESET_SPEC_KEYS = new Set(['name', 'primitive', 'defaults', 'mapConfig']);
// (Declared above the first preset table in the file, so every family
// registers its presets after this const is initialized.)

