/**
 * Value parsing for ChartFactory.suggest — numbers and dates the way people
 * write them, not only the way a program would.
 *
 * Numbers: thousands separators ('1,240,500'), a currency sign ('$3.2M',
 * '€450K'), a trailing percent ('4.7%'), accounting negatives ('(1,200)').
 * A percent keeps its written value (4.7, not 0.047) and records unit '%'.
 * A leading-zero integer ('02139', '007') is a CODE, never a number.
 *
 * Dates: ISO dates/datetimes, year-month ('2024-07', '2024/07'), US and
 * day-first dates with a four-digit year ('4/15/2026', '15.04.2026' —
 * decided per column by whether a part runs past 12, else read month-first
 * and flagged ambiguous), month names with a year ('Jan 2025', 'January
 * 2025', 'Jan 15, 2025', '15 Jan 2025') and quarters ('2024 Q1', 'Q1 2024').
 * Every date parses to UTC midnight of its first day; the emitted value is an
 * ISO 'YYYY-MM-DD' string, so configs stay JSON.
 */

export const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}([T ].*)?$/;

const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const MONTH_WORD = '(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\\.?';
const monthIndex = w => MONTHS.indexOf(w.toLowerCase().slice(0, 3));
const utc = (y, m, d) => Date.UTC(y, m, d);
const validYMD = (y, m, d) => {
    if (m < 0 || m > 11 || d < 1 || d > 31) return false;
    const t = new Date(utc(y, m, d));
    return t.getUTCMonth() === m && t.getUTCDate() === d;
};

// Each format: id, regex, and a parser from the match to epoch ms (or NaN).
const DATE_FORMATS = [
    { id: 'iso', re: ISO_DATE_RE, parse: s => Date.parse(s) },
    { id: 'year-month', re: /^(\d{4})[-/](0[1-9]|1[0-2])$/, parse: (s, m) => utc(+m[1], +m[2] - 1, 1) },
    { id: 'month-name-year', re: new RegExp(`^${MONTH_WORD}\\s+(\\d{4})$`, 'i'), parse: (s, m) => utc(+m[2], monthIndex(m[1]), 1) },
    { id: 'month-name-day-year', re: new RegExp(`^${MONTH_WORD}\\s+(\\d{1,2}),?\\s+(\\d{4})$`, 'i'),
        parse: (s, m) => (validYMD(+m[3], monthIndex(m[1]), +m[2]) ? utc(+m[3], monthIndex(m[1]), +m[2]) : NaN) },
    { id: 'day-month-name-year', re: new RegExp(`^(\\d{1,2})\\s+${MONTH_WORD},?\\s+(\\d{4})$`, 'i'),
        parse: (s, m) => (validYMD(+m[3], monthIndex(m[2]), +m[1]) ? utc(+m[3], monthIndex(m[2]), +m[1]) : NaN) },
    { id: 'quarter', re: /^(?:(\d{4})\s*-?\s*Q([1-4])|Q([1-4])\s*-?\s*(\d{4}))$/i,
        parse: (s, m) => utc(+(m[1] || m[4]), (+(m[2] || m[3]) - 1) * 3, 1) },
    // Slash/dot dates with a four-digit year: the order is decided per column.
    { id: 'numeric-dmy-or-mdy', re: /^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/, parse: null },
];

/** The date format a string matches (or null), plus its regex match. */
function matchDate(s) {
    for (const f of DATE_FORMATS) {
        const m = f.re.exec(s);
        if (m) return { f, m };
    }
    return null;
}

/**
 * Inspect a column's strings: the shared date format (when ≥ 90% match one)
 * and a parser for it. Returns null when the column isn't dates.
 */
export function detectDateFormat(strings) {
    if (strings.length === 0) return null;
    const counts = new Map();
    let firstOver12 = false, secondOver12 = false;
    for (const s of strings) {
        const hit = matchDate(s);
        if (!hit) continue;
        counts.set(hit.f.id, (counts.get(hit.f.id) || 0) + 1);
        if (hit.f.id === 'numeric-dmy-or-mdy') {
            if (+hit.m[1] > 12) firstOver12 = true;
            if (+hit.m[2] > 12) secondOver12 = true;
        }
    }
    let best = null;
    for (const [id, n] of counts) if (!best || n > best.n) best = { id, n };
    if (!best || best.n < 0.9 * strings.length) return null;
    let id = best.id, ambiguous = false;
    let parse;
    if (id === 'numeric-dmy-or-mdy') {
        if (firstOver12 && secondOver12) return null;           // not dates at all
        const dayFirst = firstOver12;
        ambiguous = !firstOver12 && !secondOver12;
        id = dayFirst ? 'day-month-year' : 'month-day-year';
        parse = s => {
            const m = /^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/.exec(s);
            if (!m) return NaN;
            const [d, mo] = dayFirst ? [+m[1], +m[2] - 1] : [+m[2], +m[1] - 1];
            return validYMD(+m[3], mo, d) ? utc(+m[3], mo, d) : NaN;
        };
    } else {
        const f = DATE_FORMATS.find(x => x.id === id);
        parse = s => { const m = f.re.exec(s); return m ? f.parse(s, m) : NaN; };
    }
    return { id, ambiguous, parse };
}

const isoOf = ms => new Date(ms).toISOString().slice(0, 10);

/** A temporal value of a profiled field as epoch ms (NaN when unparseable). */
export function timeOf(v, field) {
    if (v instanceof Date) return v.getTime();
    if (v === null || v === undefined || v === '') return NaN;
    if (typeof v === 'number') return v;                        // stand-in axes carry numbers
    const s = String(v).trim();
    if (field && field.dateFormat && field.dateFormat.id !== 'iso') return field.dateFormat.parse(s);
    return Date.parse(s);
}

/** A temporal cell as the builder-facing value: Date / ISO kept, other formats → ISO day. */
export function emitTime(v, field) {
    if (v instanceof Date) return v;
    if (!field || !field.dateFormat || field.dateFormat.id === 'iso') return v;
    const ms = timeOf(v, field);
    return Number.isFinite(ms) ? isoOf(ms) : null;
}

// ---- numbers -------------------------------------------------------------

const CURRENCY = /^[$€£¥]/;
const NUM_RE = /^([-+])?\(?([$€£¥])?\s*(\d{1,3}(?:,\d{3})+|\d+)?(\.\d+)?\s*([kmb])?\)?\s*(%)?$/i;

/**
 * Parse one written number. Returns { value, unit, currency, code } or null.
 * `code` marks a leading-zero integer (a zip, an account number): not a number.
 */
export function parseNumber(raw) {
    if (typeof raw === 'number') return Number.isFinite(raw) ? { value: raw, unit: null } : null;
    if (typeof raw !== 'string') return null;
    const s = raw.trim();
    if (s === '') return null;
    // '02139', '007': codes. '01'..'09' are ordinary two-digit numbers (months, days).
    if (/^0\d{2,}$/.test(s)) return { value: Number(s), unit: null, code: true };
    // Plain JS numbers first ('1e3', '-4.5', '12').
    const plain = Number(s);
    if (Number.isFinite(plain) && !/^0x/i.test(s)) return { value: plain, unit: null };
    const m = NUM_RE.exec(s);
    if (!m || (!m[3] && !m[4])) return null;
    const negative = m[1] === '-' || (s.startsWith('(') && s.endsWith(')'));
    let value = Number(`${(m[3] || '0').replace(/,/g, '')}${m[4] || ''}`);
    const suffix = (m[5] || '').toLowerCase();
    if (suffix === 'k') value *= 1e3;
    else if (suffix === 'm') value *= 1e6;
    else if (suffix === 'b') value *= 1e9;
    if (!Number.isFinite(value)) return null;
    return { value: negative ? -value : value, unit: m[6] ? '%' : (m[2] ? m[2] : null), currency: !!m[2] || CURRENCY.test(s) };
}

/** A numeric cell of a profiled field as a number (null when missing or unparseable). */
export function numberOf(v, field) {
    if (v === null || v === undefined) return null;
    if (typeof v === 'number') return Number.isFinite(v) ? v : null;
    if (typeof v === 'boolean') return null;
    const p = parseNumber(String(v));
    return p && !p.code ? p.value : null;
}

export { isoOf };
