/**
 * Chart Factory - Shared Utilities
 *
 * Common utilities used across all D3 visualization components.
 *
 * @requires d3 v7+ (peer dependency)
 */

import * as d3 from 'd3';

/**
 * Get CSS variable value with fallback
 * @param {string} name - CSS variable name (e.g., '--font-family')
 * @param {string} fallback - Fallback value if variable not found
 * @returns {string} The CSS variable value or fallback
 */
export function getCSSVar(name, fallback = '') {
    const value = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    return value || fallback;
}

/**
 * Text measurement utility class
 * Creates a hidden DOM element to measure text width accurately
 */
export class TextMeasurer {
    constructor() {
        this.element = null;
    }

    /**
     * Initialize the hidden measurement element
     * @private
     */
    init() {
        if (!this.element) {
            this.element = d3.select('body')
                .append('div')
                .style('position', 'absolute')
                .style('visibility', 'hidden')
                .style('white-space', 'nowrap')
                .style('font-family', getCSSVar('--font-family', 'sans-serif'))
                .style('font-size', getCSSVar('--font-size-lg', '13px'));
        }
        return this.element;
    }

    /**
     * Measure the width of text
     * @param {string} text - Text to measure
     * @param {string} fontSize - Font size (optional)
     * @param {string} fontWeight - Font weight (optional)
     * @param {Object} options - Additional options
     * @param {string} options.letterSpacing - Letter spacing
     * @param {string} options.textTransform - Text transform (e.g., 'uppercase')
     * @param {string} options.fontFamily - Font family override (else the
     *     base --font-family; lets callers measure cells whose family a
     *     theme retargets via a token, e.g. --table-primary-font)
     * @returns {number} Width in pixels
     */
    measure(text, fontSize = null, fontWeight = null, options = {}) {
        const el = this.init();
        if (fontSize) el.style('font-size', fontSize);
        if (fontWeight) el.style('font-weight', fontWeight);

        // Reset optional styles
        el.style('font-family', options.fontFamily || getCSSVar('--font-family', 'sans-serif'));
        el.style('letter-spacing', options.letterSpacing || 'normal');
        el.style('text-transform', options.textTransform || 'none');

        el.text(text);
        return el.node().getBoundingClientRect().width;
    }

    /**
     * Clean up the measurement element
     */
    destroy() {
        if (this.element) {
            this.element.remove();
            this.element = null;
        }
    }
}

/**
 * Create a D3 sequential color scale
 * @param {string} type - Scale type name (orange, blue, green, etc.)
 * @param {Array} domain - [min, max] domain values
 * @returns {Function} D3 color scale function
 */
export function createColorScale(type, domain) {
    // Endpoints/stops are design tokens (themeable via --scale-* in
    // tokens.css); the hex literals are fallbacks for token-less embeds.
    const t = (name, fallback) => getCSSVar(name, fallback);
    const scales = {
        orange: d3.scaleSequential()
            .domain(domain)
            .interpolator(d3.interpolateRgb(t('--scale-orange-lo', '#fff5eb'), t('--scale-orange-hi', '#ff6b35'))),

        orangeRed: d3.scaleSequential()
            .domain(domain)
            .interpolator(d3.interpolateRgb(t('--scale-orange-lo', '#fff5eb'), t('--scale-orange-red-hi', '#d7191c'))),

        blue: d3.scaleSequential()
            .domain(domain)
            .interpolator(d3.interpolateRgb(t('--scale-blue-lo', '#e0f3f8'), t('--scale-blue-hi', '#4575b4'))),

        teal: d3.scaleSequential()
            .domain(domain)
            .interpolator(d3.interpolateRgb(t('--scale-blue-lo', '#e0f3f8'), t('--scale-teal-hi', '#1a9988'))),

        aqua: d3.scaleSequential()
            .domain(domain)
            .interpolator(d3.interpolateRgbBasis([
                t('--scale-aqua-1', '#a4d7e1'), t('--scale-aqua-2', '#4ec1d4'),
                t('--scale-aqua-3', '#0095b7'), t('--scale-aqua-4', '#005e8b')])),

        grayscale: d3.scaleSequential()
            .domain(domain)
            .interpolator(d3.interpolateRgb(t('--scale-gray-lo', '#f5f5f5'), t('--scale-gray-hi', '#333333'))),

        purple: d3.scaleSequential()
            .domain(domain)
            .interpolator(d3.interpolateRgbBasis([
                t('--scale-purple-1', '#f3e5f5'), t('--scale-purple-2', '#ce93d8'),
                t('--scale-purple-3', '#ab47bc'), t('--scale-purple-4', '#7b1fa2')])),

        green: d3.scaleSequential()
            .domain(domain)
            .interpolator(d3.interpolateRgbBasis([
                t('--scale-green-1', '#e8f5e9'), t('--scale-green-2', '#a5d6a7'),
                t('--scale-green-3', '#66bb6a'), t('--scale-green-4', '#2e7d32')])),

        diverging: d3.scaleDiverging()
            .domain([domain[0], (domain[0] + domain[1]) / 2, domain[1]])
            .interpolator(d3.interpolateRdBu)
    };

    return scales[type] || scales.orange;
}

/**
 * Shared canvas-based text measurer. Returns a `measure(text, weight?, size?,
 * family?)` function bound to one reused 2d context. This is THE text
 * measurement utility — builders must not create their own canvases.
 */
let _measureCtx = null;
export function createTextMeasurer(defaults = {}) {
    if (!_measureCtx) {
        _measureCtx = document.createElement('canvas').getContext('2d');
    }
    const baseFamily = defaults.family || getCSSVar('--font-family', 'system-ui, sans-serif');
    const baseSize = defaults.size || getCSSVar('--font-size-md', '13px');
    const baseWeight = defaults.weight || 'normal';
    return function measure(text, weight = baseWeight, size = baseSize, family = baseFamily) {
        _measureCtx.font = `${weight} ${size} ${family}`;
        return _measureCtx.measureText(String(text)).width;
    };
}

/**
 * Calculate luminance for contrast detection
 * @param {string} color - CSS color string
 * @returns {number} Luminance value (0-1)
 */
export function getLuminance(color) {
    const rgb = d3.rgb(color);
    const r = rgb.r / 255;
    const g = rgb.g / 255;
    const b = rgb.b / 255;
    const [rs, gs, bs] = [r, g, b].map(val =>
        val <= 0.03928 ? val / 12.92 : Math.pow((val + 0.055) / 1.055, 2.4)
    );
    return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
}

/**
 * Get contrasting text color (black or white) based on background
 * @param {string} bgColor - Background color
 * @returns {string} '#000' or '#fff'
 */
export function getContrastColor(bgColor) {
    return getLuminance(bgColor) > 0.5 ? '#000' : '#fff';
}

/**
 * Standard tooltip number format — THE fallback at the end of every
 * `tooltipValueFormat || valueFormat || formatTooltipValue` chain:
 * full precision with thousands separators (integers exact, >= 1,000 one
 * decimal, >= 1 two, below 1 three significant digits — a 0.0423 rate never
 * prints "0.0"); non-numbers pass through.
 * @param {number} v
 * @returns {string}
 */
export function formatTooltipValue(v) {
    if (typeof v !== 'number' || !isFinite(v)) return v;
    if (Number.isInteger(v)) return v.toLocaleString();
    const a = Math.abs(v);
    if (a >= 1000) return v.toLocaleString(undefined, { maximumFractionDigits: 1 });
    if (a >= 1) return v.toLocaleString(undefined, { maximumFractionDigits: 2 });
    return v.toLocaleString(undefined, { maximumSignificantDigits: 3 });
}

/**
 * Default mark-label number format (bar ends, segments, cells, center
 * totals, in-cell table bars) when the caller names no format: short form at
 * 3 significant digits from 10,000 up (3.88M, 613K, 18.2K — K not k, B not
 * G), the tooltip format below (1,240 · 12.35 · 0.0423). One function for
 * the chart builders and the table, so a table bar and a chart bar print one
 * number one way. Non-numbers pass through.
 * @param {number} v
 * @returns {string}
 */
export function formatMarkValue(v) {
    if (typeof v !== 'number' || !isFinite(v)) return v;
    if (Math.abs(v) >= 1e4) {
        return d3.format('.3~s')(v).replace(/k$/, 'K').replace(/G$/, 'B');
    }
    return formatTooltipValue(v);
}

/**
 * Format a numeric value based on format type
 * @param {*} value - Value to format
 * @param {string} format - Format type (decimal, decimal2, percentage, currency, integer)
 * @returns {string} Formatted value
 */
export function formatValue(value, format) {
    if (value === null || value === undefined) return '';
    // Missing is missing: a numeric format never turns a blank cell ('' from
    // a CSV), whitespace or a non-number into 0.0 / NaN / a bare '%'.
    const numeric = ['decimal', 'decimal2', 'percentage', 'currency', 'integer'].includes(format);
    const num = numeric && !(typeof value === 'string' && value.trim() === '') ? parseFloat(value) : NaN;
    if (numeric && !Number.isFinite(num)) return '';

    switch (format) {
        case 'decimal':
            return num.toFixed(1);
        case 'decimal2':
            return num.toFixed(2);
        case 'percentage':
            return `${value}%`;
        case 'currency':
            // Money always shows cents ($60.50, never $60.5).
            return `$${num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
        case 'integer':
            return Math.trunc(num).toLocaleString();
        default:
            return value;
    }
}

/**
 * Apply staggered entrance animation to a D3 selection
 * @param {d3.Selection} selection - D3 selection to animate
 * @param {number} duration - Animation duration in ms
 * @param {number} staggerDelay - Delay between each element in ms
 * @param {Object} fromStyles - Starting styles
 * @param {Object} toStyles - Ending styles
 */
export function staggeredEntrance(selection, duration, staggerDelay, fromStyles, toStyles) {
    // Apply initial styles
    Object.entries(fromStyles).forEach(([key, value]) => {
        selection.style(key, value);
    });

    // Animate to final styles
    selection.transition()
        .delay((d, i) => i * staggerDelay)
        .duration(duration)
        .ease(d3.easeCubicOut)
        .call(transition => {
            Object.entries(toStyles).forEach(([key, value]) => {
                transition.style(key, value);
            });
        });
}

// Default export with all utilities
export default {
    getCSSVar,
    TextMeasurer,
    createColorScale,
    getLuminance,
    getContrastColor,
    formatValue,
    formatMarkValue,
    staggeredEntrance
};

// ============================================
// Tooltip Manager
// ============================================

export class TooltipManager {
    constructor(container) {
        this.tooltip = null;
        this.container = container || document.body;
        this.init();
    }

    init() {
        // One shared tooltip node per container ('.d3-tooltip'; the legacy
        // '.chart-tooltip' class is kept for back-compat selectors).
        this.tooltip = d3.select(this.container).select('.d3-tooltip');
        if (this.tooltip.empty()) {
            this.tooltip = d3.select(this.container)
                .append('div')
                .attr('class', 'd3-tooltip chart-tooltip')
                // Positioning/behavior only — appearance lives in base.css.
                .style('position', 'fixed')
                .style('pointer-events', 'none')
                .style('opacity', 0)
                .style('transition', 'opacity 0.15s')
                .style('z-index', getCSSVar('--tooltip-z-index', '9999'));
            this._applyFallbackStylesIfUnstyled();
        }
    }

    // If base.css isn't loaded (bare-JS embeds), the class carries no
    // appearance — detect that once and apply a minimal inline look.
    _applyFallbackStylesIfUnstyled() {
        const node = this.tooltip.node();
        const cs = getComputedStyle(node);
        const bg = cs.backgroundColor;
        if (!bg || bg === 'transparent' || bg === 'rgba(0, 0, 0, 0)') {
            this.tooltip
                .style('background', getCSSVar('--color-bg-container', '#ffffff'))
                .style('border', `1px solid ${getCSSVar('--color-border-tooltip', '#e5e7eb')}`)
                .style('border-radius', '6px')
                .style('padding', '10px 13px')
                .style('font-family', getCSSVar('--font-family', 'system-ui, sans-serif'))
                .style('font-size', getCSSVar('--tooltip-font-size', '12px'))
                .style('box-shadow', getCSSVar('--shadow-tooltip', '0 4px 12px rgba(0,0,0,0.15)'))
                .style('display', 'flex')
                .style('flex-direction', 'column')
                .style('gap', '3px');
        }
    }

    /**
     * Standard tooltip shell. Row shapes (visual hierarchy top to bottom:
     * title > values > labels > notes):
     *   { title, color? }          strongest text; optional entity swatch
     *   { label, value, color? }   metric row (label muted, value tabular)
     *   { value, color? }          bare emphasized value
     *   { note, color? }           small aside ('⚠ Anomaly'-style)
     *   { ..., footer: true }      hairline rule above (totals)
     *   { ..., bar: fraction }     3px mini bar under the row (share-of-total)
     *   { label, muted: true }     legacy muted label (back-compat)
     *   { ..., series: id }        tags a metric row with the series it
     *                              reports (data-series), so setActiveRow(id)
     *                              can band it without rewriting the tooltip
     *   { ..., active: true }      the hovered-series row band: a tint of the
     *                              row's color (--tooltip-row-active-alpha)
     * Returns HTML for use with show(). Prefer this over hand-built markup
     * so every chart's tooltip looks identical and stays tokenized.
     */
    static rows(rows) {
        return rows.map(r => {
            const footer = r.footer ? ' d3-tooltip-footer' : '';
            const swatch = r.color
                ? `<span class="d3-tooltip-swatch" style="background:${r.color}"></span>`
                : '';
            const bar = (r.bar !== undefined && r.bar !== null)
                ? `<div class="d3-tooltip-bar" style="width:${Math.max(0, Math.min(1, r.bar)) * 100}%;background:${r.color || 'var(--chart-primary, #3b82f6)'}"></div>`
                : '';

            // Series rows carry their color as a custom property so the
            // active band can tint itself in the series color.
            const seriesAttr = (r.series !== undefined && r.series !== null)
                ? ` data-series="${String(r.series).replace(/&/g, '&amp;').replace(/"/g, '&quot;')}"`
                : '';
            const rowColor = r.color ? ` style="--tooltip-row-color:${r.color}"` : '';
            const active = r.active ? ' d3-tooltip-row-active' : '';

            let row;
            if (r.title !== undefined) {
                row = `<div class="d3-tooltip-title${footer}">${swatch}${r.title}</div>`;
            } else if (r.note !== undefined) {
                const noteStyle = r.color ? ` style="color:${r.color}"` : '';
                row = `<div class="d3-tooltip-note${footer}"${noteStyle}>${r.note}</div>`;
            } else if (r.muted || (r.label !== undefined && r.value === undefined)) {
                row = `<div class="d3-tooltip-label${footer}">${r.label}</div>`;
            } else if (r.label === undefined) {
                row = `<div class="d3-tooltip-value${footer}">${swatch}${r.value}</div>`;
            } else {
                row = `<div class="d3-tooltip-row${footer}${active}"${seriesAttr}${rowColor}>${swatch}<span class="d3-tooltip-label">${r.label}</span><span class="d3-tooltip-value">${r.value}</span></div>`;
            }
            return bar ? `<div>${row}${bar}</div>` : row;
        }).join('');
    }

    /** Convenience: the common title-over-value tooltip. */
    showLabelValue(label, value, event, color) {
        this.show(TooltipManager.rows([
            { title: label },
            { value, color }
        ]), event);
    }

    show(html, event) {
        // The node is shared page-wide: skip the DOM write when the content
        // is unchanged (a pointer moving within one hovered x), so only the
        // position — and any setActiveRow toggle — touches the DOM. The
        // first-child check catches a write that bypassed show().
        const node = this.tooltip.node();
        if (node.__cfHtml !== html || node.firstChild !== node.__cfFirst) {
            this.tooltip.html(html);
            node.__cfHtml = html;
            node.__cfFirst = node.firstChild;
        }
        this.tooltip.style('opacity', 1);
        this.position(event);
    }

    /**
     * Band the row tagged `series: id` (null clears every band) by toggling
     * a class in place — no re-render, so the band follows the pointer on
     * every move. Rows render via rows(); a tooltipContent override that
     * keeps the `series` tags gets the band too.
     */
    setActiveRow(id) {
        const key = id === null || id === undefined ? null : String(id);
        this.tooltip.node().querySelectorAll('[data-series]').forEach(el => {
            el.classList.toggle('d3-tooltip-row-active', el.getAttribute('data-series') === key);
        });
    }

    position(event) {
        const node = this.tooltip.node();
        const width = node.offsetWidth;
        const height = node.offsetHeight;
        const vw = window.innerWidth;
        const vh = window.innerHeight;

        // Fixed positioning against the viewport (robust inside scrolled,
        // transformed, or position:fixed host layouts), flipped when close
        // to an edge and always clamped fully on-screen.
        let left = event.clientX + 12;
        if (left + width + 8 > vw) left = event.clientX - width - 12;
        let top = event.clientY - 10;
        if (top + height + 8 > vh) top = event.clientY - height - 10;
        left = Math.max(4, Math.min(left, vw - width - 4));
        top = Math.max(4, Math.min(top, vh - height - 4));

        this.tooltip
            .style('left', left + 'px')
            .style('top', top + 'px');
    }

    hide() {
        this.tooltip.style('opacity', 0);
    }
}
